window.__qzParts=window.__qzParts||{};window.__qzParts.scilife=[{"p":"Bộ phận nào của cơ thể bơm máu đi nuôi khắp cơ thể?","o":["Trái tim","Dạ dày","Lá phổi","Bộ não"],"a":"Trái tim","h":"Bộ phận này đập thình thịch trong lồng ngực của em.","e":"Trái tim co bóp không ngừng để bơm máu mang ô-xi và chất dinh dưỡng đi khắp cơ thể.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chúng ta hít thở lấy khí ô-xi nhờ bộ phận nào?","o":["Lá phổi","Trái tim","Dạ dày","Lá gan"],"a":"Lá phổi","h":"Có hai lá nằm hai bên lồng ngực.","e":"Lá phổi là nơi trao đổi khí: lấy ô-xi từ không khí vào máu và thải khí các-bô-níc ra ngoài.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào điều khiển mọi hoạt động của cơ thể, giúp em suy nghĩ và ghi nhớ?","o":["Bộ não","Trái tim","Dạ dày","Lá phổi"],"a":"Bộ não","h":"Bộ phận này nằm trong hộp sọ.","e":"Bộ não là trung tâm điều khiển của cơ thể, giúp ta suy nghĩ, ghi nhớ và cảm nhận.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Thức ăn sau khi em nhai và nuốt sẽ đi xuống bộ phận nào để được nghiền nát tiếp?","o":["Dạ dày","Lá phổi","Trái tim","Thận"],"a":"Dạ dày","h":"Bộ phận này như một chiếc túi co bóp trong bụng.","e":"Dạ dày co bóp và tiết dịch để nghiền thức ăn thành dạng lỏng trước khi xuống ruột.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Con người có mấy giác quan chính để cảm nhận thế giới?","o":["5 giác quan","3 giác quan","7 giác quan","2 giác quan"],"a":"5 giác quan","h":"Thị giác, thính giác, khứu giác, vị giác và xúc giác.","e":"Con người có 5 giác quan: nhìn (mắt), nghe (tai), ngửi (mũi), nếm (lưỡi) và sờ chạm (da).","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Giác quan nào giúp em ngửi được mùi thơm của hoa?","o":["Khứu giác (mũi)","Vị giác (lưỡi)","Thính giác (tai)","Xúc giác (da)"],"a":"Khứu giác (mũi)","h":"Mũi của em làm nhiệm vụ này.","e":"Khứu giác ở mũi giúp ta phân biệt các mùi thơm, mùi khó chịu và mùi nguy hiểm như khói cháy.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Người trưởng thành có bao nhiêu chiếc xương trong cơ thể (khoảng)?","o":["Khoảng 206 chiếc","Khoảng 100 chiếc","Khoảng 500 chiếc","Khoảng 50 chiếc"],"a":"Khoảng 206 chiếc","h":"Em bé mới sinh có nhiều xương hơn người lớn đấy.","e":"Người trưởng thành có khoảng 206 chiếc xương; trẻ sơ sinh có khoảng 300 chiếc, nhiều xương sẽ dính liền lại khi lớn lên.","t":"khoa-hoc","l":"thu-thach"},{"p":"Chiếc xương nào dài và chắc nhất trong cơ thể người?","o":["Xương đùi","Xương sườn","Xương cánh tay","Xương sọ"],"a":"Xương đùi","h":"Chiếc xương này ở phần đùi của chân.","e":"Xương đùi là chiếc xương dài nhất và chắc nhất, giúp nâng đỡ toàn bộ cơ thể.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hộp sọ có nhiệm vụ quan trọng gì?","o":["Bảo vệ bộ não","Giúp ta nhai cơm","Giúp ta nghe tiếng","Bơm máu đi khắp cơ thể"],"a":"Bảo vệ bộ não","h":"Hộp sọ cứng như một chiếc mũ bảo hiểm tự nhiên.","e":"Hộp sọ là bộ khung xương cứng bao bọc và bảo vệ bộ não mềm bên trong.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Trẻ em có bao nhiêu chiếc răng sữa?","o":["20 chiếc","32 chiếc","16 chiếc","28 chiếc"],"a":"20 chiếc","h":"Răng sữa sẽ được thay bằng răng vĩnh viễn khi em lớn.","e":"Trẻ em có 20 chiếc răng sữa; khi trưởng thành, bộ răng vĩnh viễn có 32 chiếc.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Người trưởng thành có bao nhiêu chiếc răng vĩnh viễn?","o":["32 chiếc","20 chiếc","24 chiếc","40 chiếc"],"a":"32 chiếc","h":"Gồm cả 4 chiếc răng khôn mọc sau cùng.","e":"Người trưởng thành có 32 chiếc răng vĩnh viễn, trong đó có 4 răng khôn thường mọc muộn nhất.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cơ quan nào trong cơ thể là cơ quan lớn nhất?","o":["Làn da","Lá gan","Trái tim","Lá phổi"],"a":"Làn da","h":"Cơ quan này bao bọc toàn bộ cơ thể em.","e":"Da là cơ quan lớn nhất của cơ thể, giúp bảo vệ cơ thể và cho ta cảm giác sờ chạm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào của mắt giống như một cửa sổ trong suốt cho ánh sáng đi vào?","o":["Giác mạc","Lông mi","Mí mắt","Lông mày"],"a":"Giác mạc","h":"Nó nằm ở phía trước nhất của con mắt.","e":"Giác mạc là lớp trong suốt ở phía trước mắt, cho ánh sáng đi vào và giúp mắt nhìn thấy.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi em chạy nhanh, nhịp tim và nhịp thở thay đổi thế nào?","o":["Đều nhanh hơn","Đều chậm lại","Tim nhanh còn thở chậm","Không thay đổi gì"],"a":"Đều nhanh hơn","h":"Cơ thể cần nhiều ô-xi hơn khi vận động.","e":"Khi vận động mạnh, tim đập nhanh hơn và ta thở nhanh hơn để đưa thêm ô-xi vào cơ thể.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao khi bị thương chảy máu, ta phải băng bó và giữ vết thương sạch?","o":["Để cầm máu và tránh vi khuẩn xâm nhập gây nhiễm trùng","Để vết thương đẹp hơn","Để máu chuyển màu","Không cần lý do"],"a":"Để cầm máu và tránh vi khuẩn xâm nhập gây nhiễm trùng","h":"Vi khuẩn ở khắp nơi và rất thích vết thương hở.","e":"Băng bó giúp cầm máu và ngăn vi khuẩn, bụi bẩn xâm nhập làm vết thương nhiễm trùng, lâu lành.","t":"khoa-hoc","l":"thu-thach"},{"p":"Để xương chắc khỏe, em cần ăn uống đủ chất gì và tắm nắng hợp lý?","o":["Can-xi và vi-ta-min D","Chỉ cần ăn kẹo","Chỉ cần uống nước ngọt","Chất béo"],"a":"Can-xi và vi-ta-min D","h":"Sữa và cá là nguồn chất này rất tốt.","e":"Can-xi (có trong sữa, cá nhỏ, tôm) cùng vi-ta-min D từ nắng sớm giúp xương chắc khỏe.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khí nào trong máu được các tế bào hồng cầu chở đi nuôi cơ thể?","o":["Khí ô-xi","Khí ni-tơ","Khí các-bô-níc thừa","Hơi nước"],"a":"Khí ô-xi","h":"Hồng cầu có màu đỏ và chở loại khí ta hít vào.","e":"Tế bào hồng cầu chở ô-xi từ phổi tới mọi nơi trong cơ thể và mang khí thải các-bô-níc trở về phổi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bộ phận nào giúp em giữ thăng bằng và nghe được âm thanh?","o":["Tai","Mũi","Lưỡi","Da"],"a":"Tai","h":"Bộ phận này có hai chiếc, hai bên đầu.","e":"Tai không chỉ giúp nghe mà phần tai trong còn giúp cơ thể giữ thăng bằng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi em sốt cao, nhiệt độ cơ thể thay đổi thế nào so với bình thường (khoảng 37 độ)?","o":["Cao hơn bình thường","Thấp hơn bình thường","Bằng đúng 0 độ","Không đo được"],"a":"Cao hơn bình thường","h":"Sốt là dấu hiệu cơ thể đang chống lại vi khuẩn, vi rút.","e":"Khi sốt, nhiệt độ cơ thể tăng lên trên 37,5 độ; ta cần nghỉ ngơi, uống nước và báo cho người lớn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Thói quen nào sau khi chơi ngoài sân về nhà giúp em tránh bị ốm?","o":["Rửa tay bằng xà phòng","Ăn kẹo ngay","Uống nước đá thật nhiều","Đi ngủ ngay không thay áo"],"a":"Rửa tay bằng xà phòng","h":"Tay em chạm vào rất nhiều thứ bẩn khi chơi.","e":"Rửa tay bằng xà phòng giúp loại bỏ vi khuẩn, là thói quen đơn giản nhất để phòng bệnh.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào trong ống tiêu hoá hấp thụ phần lớn chất dinh dưỡng từ thức ăn vào máu?","o":["Ruột non","Dạ dày","Miệng","Thực quản"],"a":"Ruột non","h":"Bộ phận này rất dài, cuộn trong bụng em.","e":"Ruột non dài khoảng 5–6 mét ở người lớn, là nơi hấp thụ phần lớn chất dinh dưỡng từ thức ăn.","t":"khoa-hoc","l":"kho"},{"p":"Vì sao ta không nên nhịn ăn sáng trước khi đến trường?","o":["Vì bữa sáng cung cấp năng lượng cho cả buổi học","Vì thầy cô sẽ phạt","Vì ăn sáng làm đẹp da","Không có lý do gì"],"a":"Vì bữa sáng cung cấp năng lượng cho cả buổi học","h":"Sau một đêm dài ngủ, cơ thể đã tiêu hết năng lượng dự trữ.","e":"Bữa sáng giúp em có năng lượng và tập trung học tốt hơn sau một đêm dài không ăn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Uống đủ nước mỗi ngày có lợi ích gì cho cơ thể?","o":["Giúp cơ thể hoạt động tốt và không bị mệt","Làm em cao thêm 1 mét","Làm tóc đổi màu","Không có lợi ích gì"],"a":"Giúp cơ thể hoạt động tốt và không bị mệt","h":"Hơn một nửa cơ thể em là nước đấy.","e":"Nước chiếm hơn một nửa cơ thể; uống đủ nước giúp máu lưu thông, da đẹp vàđầu óc minh mẫn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi em hắt hơi hoặc ho, vì sao nên che miệng bằng khăn giấy hoặc khuỷu tay?","o":["Để không bắn giọt nước chứa vi khuẩn, vi rút sang người khác","Để tiếng ho nhỏ hơn","Để trông lịch sự hơn thôi","Để giữ ấm cổ họng"],"a":"Để không bắn giọt nước chứa vi khuẩn, vi rút sang người khác","h":"Giọt bắn li ti từ miệng có thể bay xa tới vài mét.","e":"Che miệng khi ho, hắt hơi giúp ngăn giọt bắn mang mầm bệnh lây sang người xung quanh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Nên đánh răng vào những lúc nào trong ngày?","o":["Buổi sáng sau khi thức dậy và buổi tối trước khi đi ngủ","Chỉ khi răng đau","Một tuần một lần","Sau khi ăn kẹo"],"a":"Buổi sáng sau khi thức dậy và buổi tối trước khi đi ngủ","h":"Tối thiểu hai lần mỗi ngày nhé.","e":"Đánh răng ít nhất hai lần mỗi ngày, nhất là buổi tối trước khi ngủ, giúp ngăn sâu răng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào của cơ thể tạo ra các tế bào máu mới?","o":["Tủy xương","Lá lách","Dạ dày","Da"],"a":"Tủy xương","h":"Nó nằm ở bên trong các xương lớn.","e":"Tủy đỏ nằm trong xương tạo ra hồng cầu, bạch cầu và tiểu cầu mới cho cơ thể mỗi ngày.","t":"khoa-hoc","l":"kho"},{"p":"Khi trời nắng to, vì sao em nên đội mũ và che chắn cẩn thận?","o":["Để tránh tia nắng gắt làm hại da và gây say nắng","Để trông đẹp hơn","Để tóc mọc nhanh hơn","Không cần lý do"],"a":"Để tránh tia nắng gắt làm hại da và gây say nắng","h":"Nắng gắt giữa trưa chứa nhiều tia có hại cho da.","e":"Tia tử ngoại trong nắng gắt làm hại da; phơi nắng lâu còn gây say nắng, chóng mặt, nguy hiểm cho sức khoẻ.","t":"khoa-hoc","l":"thu-thach"},{"p":"Giấc ngủ đủ giấc giúp ích gì cho học sinh?","o":["Giúp cơ thể lớn lên, đầu óc tỉnh táo và nhớ bài tốt hơn","Chỉ để mơ đẹp","Làm mất thời gian chơi","Không có ích gì"],"a":"Giúp cơ thể lớn lên, đầu óc tỉnh táo và nhớ bài tốt hơn","h":"Khi ngủ, cơ thể vẫn âm thầm lớn lên đấy.","e":"Ngủ đủ giúp cơ thể tiết chất tăng trưởng, đầu óc tỉnh táo và ghi nhớ bài học tốt hơn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ xương của người còn được gọi là gì của cơ thể?","o":["Bộ khung nâng đỡ cơ thể","Bộ áo giáp bằng sắt","Hệ thống ống nước","Hệ thống dây điện"],"a":"Bộ khung nâng đỡ cơ thể","h":"Nhờ nó mà cơ thể đứng thẳng được.","e":"Bộ xương là bộ khung nâng đỡ, giúp cơ thể đứng thẳng, di chuyển và bảo vệ các cơ quan bên trong.","t":"khoa-hoc","l":"thu-thach"},{"p":"Mồ hôi chảy ra khi trời nóng có tác dụng gì?","o":["Giúp cơ thể mát xuống","Làm cơ thể nóng thêm","Làm em thơm hơn","Không có tác dụng"],"a":"Giúp cơ thể mát xuống","h":"Mồ hôi bay hơi sẽ mang theo nhiệt.","e":"Khi mồ hôi bay hơi, nó mang theo nhiệt giúp cơ thể hạ nhiệt và mát hơn trong ngày nắng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hai quả thận trong cơ thể có nhiệm vụ chính là gì?","o":["Lọc máu và tạo nước tiểu để thải chất cặn bã","Bơm máu đi khắp cơ thể","Nghiền nát thức ăn","Tạo ra tiếng nói"],"a":"Lọc máu và tạo nước tiểu để thải chất cặn bã","h":"Nhờ có chúng mà máu luôn được làm sạch.","e":"Thận lọc máu liên tục, loại bỏ chất cặn bã và nước thừa tạo thành nước tiểu.","t":"khoa-hoc","l":"kho"},{"p":"Khi em vui cười hay buồn khóc, đó là nhờ bộ phận nào cảm nhận và biểu lộ?","o":["Bộ não cùng các cơ trên mặt","Dạ dày","Lá gan","Xương đùi"],"a":"Bộ não cùng các cơ trên mặt","h":"Cảm xúc bắt đầu từ trong đầu của em.","e":"Bộ não cảm nhận cảm xúc và điều khiển các cơ mặt để ta cười, khóc hay ngạc nhiên.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao bác sĩ khuyên không nên nhìn điện thoại, máy tính quá lâu liên tục?","o":["Vì mắt sẽ mỏi, dễ bị cận thị","Vì điện thoại sẽ hỏng","Vì sẽ hết pin nhanh","Không có lý do"],"a":"Vì mắt sẽ mỏi, dễ bị cận thị","h":"Mắt cũng cần được nghỉ ngơi như chân tay vậy.","e":"Nhìn màn hình lâu làm mắt mỏi và tăng nguy cơ cận thị; nên cho mắt nghỉ, nhìn ra xa sau mỗi 20–30 phút.","t":"khoa-hoc","l":"thu-thach"},{"p":"Tập thể dục thường xuyên giúp cơ thể thế nào?","o":["Khỏe mạnh, xương chắc, tim phổi tốt","Lùn đi","Dễ ốm hơn","Học kém đi"],"a":"Khỏe mạnh, xương chắc, tim phổi tốt","h":"Vận động là liều thuốc bổ tự nhiên.","e":"Tập thể dục giúp tim phổi khỏe, xương chắc, cơ thể dẻo dai và học tập tập trung hơn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào nối giữa miệng và dạ dày, đưa thức ăn xuống?","o":["Thực quản","Khí quản","Ruột non","Tĩnh mạch"],"a":"Thực quản","h":"Nó là một ống cơ nằm sau khí quản.","e":"Thực quản là ống cơ co bóp đẩy thức ăn từ miệng xuống dạ dày.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi chạy, em thở bằng mũi hay miệng và cảm thấy thế nào cũng là bình thường, nhưng bộ phận nào trao đổi khí cho máu?","o":["Lá phổi","Dạ dày","Thận","Gan"],"a":"Lá phổi","h":"Hai lá này phồng lên xẹp xuống theo nhịp thở.","e":"Lá phổi là nơi trao đổi khí: ô-xi vào máu, khí các-bô-níc được thở ra.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Số lần tim đập mỗi phút khi nghỉ ngơi của học sinh khoảng bao nhiêu?","o":["Khoảng 70–100 lần","Khoảng 10–20 lần","Khoảng 300 lần","Khoảng 5 lần"],"a":"Khoảng 70–100 lần","h":"Hãy đặt tay lên ngực và đếm thử một phút nhé.","e":"Khi nghỉ ngơi, tim học sinh đập khoảng 70–100 lần mỗi phút; khi vận động sẽ đập nhanh hơn.","t":"khoa-hoc","l":"kho"},{"p":"Vì sao em phải ăn nhiều loại thức ăn khác nhau (cơm, thịt, cá, rau, quả)?","o":["Để cơ thể đủ các chất dinh dưỡng khác nhau","Để bữa ăn đẹp mắt","Để no lâu hơn","Không có lý do"],"a":"Để cơ thể đủ các chất dinh dưỡng khác nhau","h":"Mỗi loại thức ăn cho ta một loại chất khác nhau.","e":"Mỗi nhóm thức ăn cung cấp chất khác nhau: chất bột đường cho năng lượng, chất đạm để lớn lên, rau quả cho vi-ta-min.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Lưỡi giúp ta nếm được những vị cơ bản nào?","o":["Ngọt, chua, mặn, đắng và vị ngon của thịt (umami)","Chỉ có vị ngọt","Vị cay là một vị cơ bản","Không nếm được vị đắng"],"a":"Ngọt, chua, mặn, đắng và vị ngon của thịt (umami)","h":"Vị cay thực ra là cảm giác đau nhẹ, không phải vị cơ bản đâu.","e":"Lưỡi nếm được 5 vị cơ bản: ngọt, chua, mặn, đắng và umami (vị ngon của thịt, nước dùng).","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi em bị ngã trầy da và chảy ít máu, việc đầu tiên nên làm là gì?","o":["Rửa vết thương bằng nước sạch rồi băng lại","Thổi vào vết thương liên tục","Bôi bùn lên vết thương","Mặc kệ không làm gì"],"a":"Rửa vết thương bằng nước sạch rồi băng lại","h":"Nước sạch giúp cuốn trôi bụi bẩn và vi khuẩn.","e":"Sơ cứu vết thương nhỏ: rửa bằng nước sạch, sát trùng nếu có, rồi băng lại và báo người lớn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Động vật nào là động vật lớn nhất trên Trái Đất?","o":["Cá voi xanh","Voi châu Phi","Hươu cao cổ","Cá mập voi"],"a":"Cá voi xanh","h":"Con vật này sống dưới biển và dài bằng mấy chiếc xe buýt.","e":"Cá voi xanh dài tới khoảng 30 mét và nặng hơn cả đàn voi cộng lại, là động vật lớn nhất từng sống trên Trái Đất.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Động vật trên cạn nào lớn nhất?","o":["Voi châu Phi","Hà mã","Tê giác","Trâu rừng"],"a":"Voi châu Phi","h":"Con vật này có đôi tai rất to và cái vòi dài.","e":"Voi châu Phi là động vật trên cạn lớn nhất, có thể nặng tới 6 tấn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Động vật nào cao nhất trên cạn?","o":["Hươu cao cổ","Voi","Ngựa","Lạc đà"],"a":"Hươu cao cổ","h":"Cái cổ của nó dài ơi là dài.","e":"Hươu cao cổ cao tới 5–6 mét nhờ chiếc cổ dài, giúp nó ăn lá trên ngọn cây cao.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Loài thú nào chạy nhanh nhất trên cạn?","o":["Báo săn (báo gepa)","Ngựa","Chó sói","Linh dương"],"a":"Báo săn (báo gepa)","h":"Nó tăng tốc nhanh như một chiếc xe thể thao.","e":"Báo săn chạy nhanh nhất trên cạn, có thể đạt khoảng 100 km mỗi giờ trong quãng ngắn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Loài chim nào lớn nhất thế giới nhưng không biết bay?","o":["Đà điểu","Đại bàng","Chim cánh cụt","Thiên nga"],"a":"Đà điểu","h":"Nó chạy rất nhanh bằng đôi chân dài.","e":"Đà điểu là loài chim lớn nhất, cao gần 3 mét; nó không bay được nhưng chạy rất nhanh.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Loài chim nào nhỏ nhất thế giới và có thể bay lùi?","o":["Chim ruồi","Chim sẻ","Chim én","Chim chích"],"a":"Chim ruồi","h":"Nó bé xíu, đập cánh nhanh đến mức kêu vo ve như ong.","e":"Chim ruồi là loài chim nhỏ nhất; nó có thể bay đứng yên một chỗ và bay lùi nhờ đôi cánh đập cực nhanh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Loài thú duy nhất biết bay thật sự là loài nào?","o":["Dơi","Sóc bay","Chồn bay","Thằn lằn bay"],"a":"Dơi","h":"Sóc bay chỉ lượn từ cây này sang cây khác thôi, không đập cánh bay lên được.","e":"Dơi là loài thú duy nhất biết bay thật sự bằng đôi cánh có màng da; các loài \"bay\" khác chỉ biết lượn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cá heo là cá hay là thú?","o":["Là thú","Là cá","Là loài lưỡng cư","Là bò sát"],"a":"Là thú","h":"Hãy nhớ cách nó sinh con và nuôi con.","e":"Cá heo là thú: nó đẻ con, nuôi con bằng sữa và thở bằng phổi nên phải thường xuyên ngoi lên mặt nước hít thở.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con nhện có bao nhiêu chân?","o":["8 chân","6 chân","10 chân","4 chân"],"a":"8 chân","h":"Nhiều hơn số chân của côn trùng hai chân.","e":"Nhện có 8 chân nên không thuộc nhóm côn trùng; côn trùng chỉ có 6 chân.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Côn trùng như ong, kiến, bướm đều có bao nhiêu chân?","o":["6 chân","8 chân","4 chân","Không có chân"],"a":"6 chân","h":"Hãy thử đếm chân của một con kiến.","e":"Mọi côn trùng đều có 6 chân và cơ thể chia làm 3 phần: đầu, ngực, bụng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao ếch được gọi là loài lưỡng cư?","o":["Vì nhỏ sống ở nước, lớn sống cả ở nước và trên cạn","Vì nó có hai màu da","Vì nó kêu được hai thứ tiếng","Vì nó có hai mắt to"],"a":"Vì nhỏ sống ở nước, lớn sống cả ở nước và trên cạn","h":"\"Lưỡng cư\" nghĩa là sống ở hai nơi.","e":"Nòng nọc (ếch con) sống dưới nước và thở bằng mang; ếch trưởng thành sống cả trên cạn và dưới nước nên gọi là lưỡng cư.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con tằm ăn lá dâu rồi nhả ra thứ gì quý để dệt vải?","o":["Tơ tằm","Mật ong","Sáp ong","Bông"],"a":"Tơ tằm","h":"Thứ này óng ánh và làm nên áo lụa mềm mại.","e":"Tằm ăn lá dâu rồi nhả tơ làm kén; người ta kéo sợi tơ đó để dệt nên vải lụa.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Trong đàn ong mật, con ong nào có nhiệm vụ đẻ trứng?","o":["Ong chúa","Ong thợ","Ong đực","Ong lính"],"a":"Ong chúa","h":"Mỗi tổ ong chỉ có một con như vậy.","e":"Ong chúa là con ong duy nhất trong tổ chuyên đẻ trứng; ong thợ làm mọi việc khác như kiếm mật, xây tổ, nuôi ấu trùng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Gấu trúc (gấu panda) thích ăn nhất món gì?","o":["Tre và trúc","Thịt bò","Cá hồi","Táo"],"a":"Tre và trúc","h":"Nó ngồi ôm những cây xanh dài mà gặm cả ngày.","e":"Gấu trúc dành phần lớn thời gian trong ngày để ăn tre, trúc — món ăn chiếm gần như toàn bộ bữa ăn của nó.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Loài thú nào kỳ lạ: đẻ trứng nhưng lại nuôi con bằng sữa, sống ở nước Úc?","o":["Thú mỏ vịt","Thú có túi","Gấu koala","Chim kiwi"],"a":"Thú mỏ vịt","h":"Nó có cái mỏ giống vịt và chân có màng như rái cá.","e":"Thú mỏ vịt là một trong số rất ít loài thú đẻ trứng; con non vẫn bú sữa mẹ như các loài thú khác.","t":"khoa-hoc","l":"kho"},{"p":"Ở loài cá ngựa, con nào mang bầu và sinh con?","o":["Cá ngựa bố","Cá ngựa mẹ","Cả bố và mẹ thay phiên","Cá ngựa không sinh con"],"a":"Cá ngựa bố","h":"Đây là điều ngược đời hiếm thấy trong thế giới động vật.","e":"Cá ngựa mẹ chuyển trứng vào túi ấp của cá ngựa bố; bố sẽ mang trứng cho đến khi hàng trăm cá ngựa con chào đời.","t":"khoa-hoc","l":"kho"},{"p":"Con bạch tuộc có bao nhiêu xúc tu (tay)?","o":["8 xúc tu","6 xúc tu","10 xúc tu","4 xúc tu"],"a":"8 xúc tu","h":"Tên tiếng Anh của nó là \"octopus\", và \"octo\" nghĩa là tám.","e":"Bạch tuộc có 8 xúc tu đầy giác hút giúp nó bám và bắt mồi; nó còn có tới 3 trái tim.","t":"khoa-hoc","l":"thu-thach"},{"p":"Lạc đà tích trữ gì trong cái bướu trên lưng để sống được lâu trong sa mạc?","o":["Mỡ","Nước","Cát","Không khí"],"a":"Mỡ","h":"Nhiều người tưởng là nước nhưng không phải đâu.","e":"Bướu lạc đà chứa mỡ dự trữ; khi thiếu ăn, cơ thể dùng mỡ này để tạo năng lượng, giúp nó nhịn được nhiều ngày.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hoa văn sọc trên mình mỗi con ngựa vằn như thế nào?","o":["Mỗi con một kiểu, không con nào giống con nào","Con nào cũng giống hệt nhau","Chỉ có ở ngựa vằn cái","Đổi màu theo mùa"],"a":"Mỗi con một kiểu, không con nào giống con nào","h":"Giống như dấu vân tay của người vậy.","e":"Sọc của mỗi con ngựa vằn là độc nhất, khác nhau như vân tay người, giúp chúng nhận ra nhau.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao cá không bao giờ nhắm mắt khi ngủ?","o":["Vì cá không có mí mắt","Vì cá không bao giờ ngủ","Vì cá ngủ dưới cát","Vì mắt cá không cần nghỉ"],"a":"Vì cá không có mí mắt","h":"Hãy nhớ lại hình dáng con cá mà xem.","e":"Phần lớn các loài cá không có mí mắt nên không nhắm mắt được; chúng vẫn ngủ bằng cách nằm im và phản ứng rất chậm.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con giun đất có ích gì cho ruộng vườn?","o":["Làm đất tơi xốp, giúp cây lớn tốt","Ăn hết sâu bọ","Hút nước cho đất khô","Không có ích gì"],"a":"Làm đất tơi xốp, giúp cây lớn tốt","h":"Nó được gọi là \"người cày ruộng\" của tự nhiên.","e":"Giun đất đào hang làm đất tơi xốp, thoáng khí và phân của giun làm đất thêm màu mỡ cho cây.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chuột túi (kangaroo) mang con nhỏ của mình ở đâu?","o":["Trong chiếc túi trước bụng","Trên lưng","Trong hang đất","Trên cây"],"a":"Trong chiếc túi trước bụng","h":"Chiếc túi này ấm áp và an toàn cho con non.","e":"Chuột túi mẹ mang con trong túi trước bụng; chuột túi con sinh ra bé xíu và sống trong túi nhiều tháng bú sữa.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao gấu lại ngủ đông suốt mùa đông lạnh giá?","o":["Để tiết kiệm năng lượng khi trời lạnh và khan hiếm thức ăn","Vì gấu lười biếng","Để tránh bị ướt mưa","Để thay bộ lông mới"],"a":"Để tiết kiệm năng lượng khi trời lạnh và khan hiếm thức ăn","h":"Mùa đông ở xứ lạnh, thức ăn rất khó kiếm.","e":"Ngủ đông giúp gấu tiết kiệm năng lượng, sống nhờ lớp mỡ tích trữ khi mùa đông lạnh và ít thức ăn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Chim cú mèo săn mồi giỏi vào lúc nào?","o":["Ban đêm","Buổi trưa","Buổi sáng sớm","Mọi lúc như nhau"],"a":"Ban đêm","h":"Đôi mắt to của nó nhìn rất rõ trong bóng tối.","e":"Cú mèo là thợ săn đêm: mắt to nhìn rõ trong tối, tai thính và bay không một tiếng động.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chim công trống xoè chiếc đuôi to đẹp rực rỡ để làm gì?","o":["Để thu hút chim công mái","Để dọa hổ báo","Để che mưa","Để bay nhanh hơn"],"a":"Để thu hút chim công mái","h":"Trong thế giới loài chim, con trống thường đẹp hơn con mái.","e":"Công trống xoè đuôi lộng lẫy và rung rung để khoe với công mái; công mái có bộ lông màu nhạt hơn nhiều.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Tắc kè hoa đổi màu da chủ yếu để làm gì?","o":["Để ngụy trang trốn kẻ thù và rình mồi","Để cho đẹp","Để báo trời sắp mưa","Để làm mát cơ thể là chính"],"a":"Để ngụy trang trốn kẻ thù và rình mồi","h":"Màu da của nó hòa vào màu lá cây, cành cây xung quanh.","e":"Tắc kè hoa đổi màu để hòa lẫn với môi trường, vừa trốn kẻ thù vừa âm thầm rình mồi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Voi dùng bộ phận nào để vặt lá, cầm thức ăn và phun nước tắm?","o":["Cái vòi","Đôi ngà","Đôi tai to","Cái đuôi"],"a":"Cái vòi","h":"Bộ phận này vừa là mũi vừa như một cánh tay.","e":"Vòi voi là mũi và môi trên kéo dài, rất khéo léo: vừa ngửi, vừa cầm nắm thức ăn, vừa hút nước để uống và tắm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Con nào sau đây là động vật ăn thịt?","o":["Con hổ","Con thỏ","Con ngựa","Con bò"],"a":"Con hổ","h":"Hãy nghĩ xem nó săn con vật khác hay ăn cỏ.","e":"Hổ là động vật ăn thịt, có răng nanh sắc và móng vuốt để săn mồi; thỏ, ngựa, bò là động vật ăn cỏ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chim gõ kiến gõ mỏ liên tục vào thân cây để làm gì?","o":["Tìm sâu và côn trùng ẩn dưới vỏ cây để ăn","Để xây nhà cho chim sẻ","Để gọi bạn tình bằng tiếng gõ","Để mài mỏ cho sắc"],"a":"Tìm sâu và côn trùng ẩn dưới vỏ cây để ăn","h":"Tiếng \"cốc cốc cốc\" vang khắp rừng.","e":"Gõ kiến dùng mỏ cứng gõ vào thân cây, nghe và khoét tìm sâu bọ ẩn dưới vỏ cây để ăn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con hải ly nổi tiếng với \"công trình\" nào trong tự nhiên?","o":["Đắp đập bằng cây gỗ ngang qua suối","Đào hang sâu 100 mét","Xây tổ trên đỉnh núi","Dệt lưới bắt cá"],"a":"Đắp đập bằng cây gỗ ngang qua suối","h":"Công trình này tạo thành những hồ nước nhỏ.","e":"Hải ly đốn cây bằng đôi răng chắc khỏe và đắp đập ngang suối, tạo hồ nước an toàn cho tổ của mình.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con bạch tuộc phun ra chất gì để trốn kẻ thù?","o":["Mực đen","Nước sôi","Cát","Khói trắng"],"a":"Mực đen","h":"Chất này làm nước đục ngầu trong chốc lát.","e":"Khi gặp nguy hiểm, bạch tuộc phun một đám mực đen làm kẻ thù không nhìn thấy, rồi nhanh chóng trốn thoát.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Con đom đóm phát sáng ở phần nào của cơ thể?","o":["Ở bụng","Ở mắt","Ở cánh","Ở chân"],"a":"Ở bụng","h":"Ánh sáng của nó nhấp nháy trong đêm hè.","e":"Đom đóm có cơ quan phát sáng ở bụng; ánh sáng nhấp nháy giúp chúng tìm và gọi bạn trong đêm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao muỗi cái lại đốt người còn muỗi đực thì không?","o":["Muỗi cái cần hút máu để có chất đẻ trứng","Muỗi đực không có vòi","Muỗi cái thích mùi mồ hôi","Muỗi đực chỉ sống một ngày"],"a":"Muỗi cái cần hút máu để có chất đẻ trứng","h":"Bữa ăn máu giúp muỗi cái hoàn thành việc sinh sản.","e":"Muỗi cái hút máu người và động vật để lấy chất đạm nuôi trứng; muỗi đực chỉ hút nhựa cây và mật hoa.","t":"khoa-hoc","l":"thu-thach"},{"p":"Ruồi nhà đậu lên thức ăn thì nguy hiểm vì sao?","o":["Vì chân và mình ruồi mang vi khuẩn từ nơi bẩn vào thức ăn","Vì ruồi ăn hết thức ăn","Vì ruồi làm thức ăn bị lạnh","Vì tiếng ruồi vo ve khó chịu"],"a":"Vì chân và mình ruồi mang vi khuẩn từ nơi bẩn vào thức ăn","h":"Ruồi thường đậu ở những nơi rất bẩn trước đó.","e":"Ruồi hay đậu ở rác và chất bẩn nên mang theo nhiều vi khuẩn; khi đậu lên thức ăn, chúng làm bẩn thức ăn và gây bệnh tiêu hoá.","t":"khoa-hoc","l":"thu-thach"},{"p":"Sư tử đực khác sư tử cái ở điểm dễ nhận thấy nào nhất?","o":["Có bờm lớn quanh đầu","To hơn gấp đôi","Có sọc trên lưng","Có đôi cánh nhỏ"],"a":"Có bờm lớn quanh đầu","h":"Chiếc bờm làm nó trông rất oai vệ.","e":"Sư tử đực có bờm lông lớn quanh đầu và cổ, còn sư tử cái không có bờm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bướm nếm mùi vị thức ăn bằng bộ phận nào thật bất ngờ?","o":["Bằng chân","Bằng râu","Bằng cánh","Bằng bụng"],"a":"Bằng chân","h":"Nó đậu lên lá là biết lá có ngon và hợp để đẻ trứng không.","e":"Bướm có cơ quan nếm ở chân; khi đậu lên lá, nó \"nếm\" ngay được xem lá đó có phù hợp không.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con sứa có bộ não và trái tim không?","o":["Không có cả não lẫn tim","Có não nhưng không có tim","Có tim nhưng không có não","Có đủ cả hai"],"a":"Không có cả não lẫn tim","h":"Vậy mà nó vẫn bơi, bắt mồi và sống được hàng trăm triệu năm.","e":"Sứa không có não, không có tim và không có xương; cơ thể nó gồm tới khoảng 95% là nước.","t":"khoa-hoc","l":"kho"},{"p":"Sao biển có khả năng đặc biệt nào khi bị mất một cánh tay?","o":["Mọc lại cánh tay mới","Biến thành con cá","Thay đổi giới tính","Phát sáng trong tối"],"a":"Mọc lại cánh tay mới","h":"Khả năng này gọi là tái sinh.","e":"Sao biển có thể mọc lại cánh tay đã mất; thậm chí một cánh tay có phần thân đi kèm còn mọc thành một con sao biển mới.","t":"khoa-hoc","l":"kho"},{"p":"Ve sầu kêu inh ỏi nhất vào mùa nào?","o":["Mùa hè","Mùa đông","Mùa thu","Mùa xuân"],"a":"Mùa hè","h":"Tiếng ve là âm thanh quen thuộc của sân trường mỗi độ hè về.","e":"Ve sầu kêu râm ran vào mùa hè; tiếng kêu do ve đực phát ra để gọi bạn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chim cánh cụt không biết bay, vậy nó giỏi nhất việc gì?","o":["Bơi lặn dưới nước","Leo cây","Đào hang sâu","Chạy trên cát"],"a":"Bơi lặn dưới nước","h":"Đôi cánh của nó biến thành hai mái chèo.","e":"Cánh cụt bơi lặn rất giỏi nhờ đôi cánh như mái chèo và thân hình thon; nó sống ở vùng biển lạnh Nam bán cầu.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con lười (con vật treo mình trên cây ở rừng Nam Mỹ) nổi tiếng vì điều gì?","o":["Di chuyển vô cùng chậm chạp","Nhảy rất xa","Kêu rất to","Bơi rất nhanh"],"a":"Di chuyển vô cùng chậm chạp","h":"Tên của nó đã nói lên tất cả rồi.","e":"Con lười di chuyển cực kỳ chậm; nó ăn lá cây và ngủ tới 15–20 giờ mỗi ngày trên cành cây.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Ốc sên bò được qua cả những chỗ sắc nhọn và trèo lên tường nhờ đâu?","o":["Chất nhầy trơn ở dưới chân","Những cái móc nhỏ ở vỏ","Nam châm ở chân","Bốn chân có móng"],"a":"Chất nhầy trơn ở dưới chân","h":"Vệt sáng bóng nó để lại trên đường đi chính là thứ đó.","e":"Ốc sên tiết chất nhầy trơn dưới bàn chân cơ bắp, giúp nó bò êm, bám được lên tường và không bị thương bởi vật sắc.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con mèo nhìn rõ trong bóng tối hơn người nhờ bộ phận nào đặc biệt?","o":["Đôi mắt thu nhận ánh sáng rất tốt","Đôi tai to","Bộ ria mép","Cái đuôi dài"],"a":"Đôi mắt thu nhận ánh sáng rất tốt","h":"Ria mép giúp mèo cảm nhận xung quanh, nhưng nhìn tối là nhờ bộ phận khác.","e":"Mắt mèo có lớp phản chiếu ánh sáng đặc biệt nên nhìn rõ trong tối; ria mép giúp mèo cảm nhận vật cản quanh mặt.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Con chó đánh hơi giỏi hơn người rất nhiều nhờ bộ phận nào?","o":["Cái mũi với hàng trăm triệu tế bào ngửi","Đôi tai dựng","Đôi mắt tinh","Bộ lông dày"],"a":"Cái mũi với hàng trăm triệu tế bào ngửi","h":"Nhờ vậy chó được huấn luyện để tìm người và đồ vật.","e":"Mũi chó có tới khoảng 300 triệu tế bào cảm nhận mùi, hơn người rất nhiều lần, nên chó đánh hơi cực kỳ thính.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bộ phận nào của cây giúp cây quang hợp, làm ra thức ăn cho cây?","o":["Lá cây","Rễ cây","Thân cây","Hoa"],"a":"Lá cây","h":"Bộ phận này thường có màu xanh lục.","e":"Lá là \"nhà bếp\" của cây: nhờ chất xanh trong lá và ánh nắng, cây làm ra thức ăn nuôi mình.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Rễ cây có nhiệm vụ chính là gì?","o":["Hút nước và chất khoáng từ đất, giữ cây đứng vững","Làm hoa nở đẹp","Nở ra quả","Thu hút ong bướm"],"a":"Hút nước và chất khoáng từ đất, giữ cây đứng vững","h":"Bộ phận này cắm sâu xuống đất.","e":"Rễ hút nước và chất khoáng nuôi cây, đồng thời bám chặt vào đất giữ cây đứng vững trước gió.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cây xanh nhả ra loại khí nào khi quang hợp, rất cần cho người và động vật thở?","o":["Khí ô-xi","Khí các-bô-níc","Khí ni-tơ","Khói bụi"],"a":"Khí ô-xi","h":"Đây là lý do ta gọi rừng là \"lá phổi xanh\".","e":"Khi quang hợp, cây xanh lấy khí các-bô-níc và nhả ra ô-xi, làm không khí trong lành hơn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Để quang hợp, cây xanh cần những thứ gì?","o":["Ánh sáng mặt trời, nước và khí các-bô-níc","Chỉ cần đất","Chỉ cần bóng tối","Cần thịt và cá"],"a":"Ánh sáng mặt trời, nước và khí các-bô-níc","h":"Thiếu một trong ba thứ này cây sẽ yếu đi.","e":"Quang hợp cần ánh nắng, nước (rễ hút lên) và khí các-bô-níc (lá lấy từ không khí) để tạo thức ăn và ô-xi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hoa hướng dương có đặc điểm gì thú vị với mặt trời?","o":["Hoa thường quay về phía mặt trời","Hoa chỉ nở ban đêm","Hoa đổi màu theo giờ","Hoa bay theo gió"],"a":"Hoa thường quay về phía mặt trời","h":"Tên của nó đã gợi ý rồi đấy.","e":"Hoa hướng dương non thường hướng về phía mặt trời trong ngày, như luôn dõi theo ông mặt trời.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cây xương rồng sống được ở sa mạc khô nóng nhờ đặc điểm nào?","o":["Thân mọng nước dự trữ nước, lá biến thành gai để đỡ mất nước","Rễ rất ngắn","Lá to và mỏng","Hoa nở quanh năm"],"a":"Thân mọng nước dự trữ nước, lá biến thành gai để đỡ mất nước","h":"Hãy nhìn những cái gai của nó mà suy ra.","e":"Xương rồng dự trữ nước trong thân mọng; lá biến thành gai giúp cây mất ít nước và tránh bị động vật ăn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bộ phận nào của cây sẽ lớn lên thành quả?","o":["Hoa (phần bầu nhụy của hoa)","Rễ","Lá","Vỏ cây"],"a":"Hoa (phần bầu nhụy của hoa)","h":"Muốn có quả ngon, cây phải ra hoa trước đã.","e":"Sau khi thụ phấn, bầu nhụy của hoa phát triển thành quả, bên trong quả có hạt.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hạt giống nảy mầm thành cây con cần những điều kiện chính nào?","o":["Đủ nước, không khí và nhiệt độ ấm vừa","Phải có thịt để ăn","Phải để trong tủ lạnh","Phải chiếu đèn cả đêm"],"a":"Đủ nước, không khí và nhiệt độ ấm vừa","h":"Thiếu nước thì hạt sẽ ngủ yên không nảy mầm.","e":"Hạt cần nước để mềm vỏ, cần không khí để thở và nhiệt độ phù hợp để nảy mầm thành cây con.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao hạt giống và quả của nhiều loài cây lại có cánh, có lông hoặc có móc?","o":["Để nhờ gió, nước hoặc động vật mang đi xa phát tán","Để cho đẹp","Để chống lạnh","Để bơi dưới nước"],"a":"Để nhờ gió, nước hoặc động vật mang đi xa phát tán","h":"Hạt bồ công anh bay theo gió là một ví dụ.","e":"Hạt có cánh nhờ gió bay xa, hạt có móc bám vào lông thú, hạt nhẹ nổi trên nước — tất cả để cây con mọc ở nơi mới.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây bàng, cây phượng trên sân trường rụng nhiều lá vào mùa nào ở miền Bắc?","o":["Mùa đông","Mùa hè","Mùa mưa","Quanh năm không rụng"],"a":"Mùa đông","h":"Khi trời trở lạnh, lá cây chuyển vàng rồi rụng.","e":"Vào mùa đông lạnh, nhiều cây ở miền Bắc rụng lá để giảm mất nước và chống chọi giá rét.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vòng tuổi trên thân cây gỗ bị cưa ngang cho ta biết điều gì?","o":["Số năm tuổi của cây","Số lá của cây","Số quả cây đã ra","Chiều cao của cây"],"a":"Số năm tuổi của cây","h":"Mỗi năm cây tạo thêm một vòng mới.","e":"Mỗi vòng sáng – tối trên mặt cắt thân cây ứng với một năm sống; đếm số vòng sẽ biết tuổi của cây.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây lúa, cây ngô cho ta hạt để ăn thuộc nhóm cây gì?","o":["Cây lương thực","Cây ăn quả","Cây cảnh","Cây lấy gỗ"],"a":"Cây lương thực","h":"Đây là những cây nuôi sống con người mỗi ngày.","e":"Lúa, ngô, khoai, sắn là cây lương thực — nguồn thức ăn chính của con người.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Tre, trúc thuộc họ cây gì dù thân chúng cao và cứng như gỗ?","o":["Họ cỏ (họ lúa)","Họ thông","Họ đậu","Họ hoa hồng"],"a":"Họ cỏ (họ lúa)","h":"Câu trả lời sẽ làm em bất ngờ đấy.","e":"Tre thuộc họ cỏ cùng với lúa và ngô; thân tre rỗng, có đốt và lớn rất nhanh — có loài cao thêm gần 1 mét mỗi ngày.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây sen mọc ở đâu?","o":["Dưới ao hồ nước nông, lá và hoa nổi trên mặt nước","Trên đỉnh núi cao","Trong sa mạc","Trên cây khác"],"a":"Dưới ao hồ nước nông, lá và hoa nổi trên mặt nước","h":"\"Gần bùn mà chẳng hôi tanh mùi bùn\".","e":"Sen sống ở ao hồ: rễ cắm trong bùn, lá và hoa vươn lên trên mặt nước.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao lá sen không bị ướt đẫm khi nước đổ lên?","o":["Vì mặt lá có lớp sáp làm nước trượt đi thành giọt","Vì lá sen bằng nhựa","Vì sen không sống ở nước","Vì lá sen tự khô ngay"],"a":"Vì mặt lá có lớp sáp làm nước trượt đi thành giọt","h":"Giọt nước lăn tròn trên lá sen như hạt ngọc.","e":"Mặt lá sen phủ lớp sáp đặc biệt khiến nước co thành giọt tròn và lăn đi, mang theo bụi bẩn — gọi là hiệu ứng lá sen.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây nào được coi là biểu tượng của làng quê Việt Nam, dùng làm đũa, nhà, đồ chơi?","o":["Cây tre","Cây thông","Cây xương rồng","Cây bàng"],"a":"Cây tre","h":"\"Tre xanh, xanh tự bao giờ\" — cây này gắn với mọi làng quê.","e":"Tre là biểu tượng của làng quê Việt Nam, dùng làm nhà, đũa, rổ rá, đồ chơi và gắn với truyền thuyết Thánh Gióng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Thực vật trên Trái Đất quan trọng với muôn loài chủ yếu vì lý do gì?","o":["Chúng làm ra ô-xi và thức ăn cho hầu hết các sinh vật","Chúng làm cho đất màu đỏ","Chúng che hết ánh nắng","Chúng làm ra mưa"],"a":"Chúng làm ra ô-xi và thức ăn cho hầu hết các sinh vật","h":"Mọi con vật ăn cỏ, rồi con vật ăn thịt lại ăn con vật ăn cỏ.","e":"Cây xanh quang hợp tạo ô-xi và thức ăn; hầu như mọi chuỗi thức ăn trong tự nhiên đều bắt đầu từ thực vật.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây chuối sau khi ra một buồng quả sẽ thế nào?","o":["Cây mẹ tàn đi, cây con mọc lên từ gốc thay thế","Cây ra quả tiếp mãi mãi","Cây biến thành cây khác","Cây chết cả bụi ngay"],"a":"Cây mẹ tàn đi, cây con mọc lên từ gốc thay thế","h":"Hãy để ý bụi chuối sau nhà: luôn có cây con nối tiếp.","e":"Một cây chuối chỉ ra quả một lần rồi tàn; nhưng từ gốc sẽ mọc nhiều cây con thay thế nên bụi chuối vẫn xanh tốt.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Loài cây nào sống lâu nhất và cao lớn bậc nhất trong rừng, thân to đến mức nhiều người ôm không hết, ở nước Mỹ?","o":["Cây củ tùng (sequoia) khổng lồ","Cây thông thường","Cây bách","Cây sồi"],"a":"Cây củ tùng (sequoia) khổng lồ","h":"Có cây cao hơn 80 mét và sống hơn 2.000 năm.","e":"Cây củ tùng khổng lồ ở Mỹ cao tới hơn 80 mét, thân to hàng chục người ôm và sống hơn 2.000 năm.","t":"khoa-hoc","l":"kho"},{"p":"Nấm có phải là thực vật không?","o":["Không, nấm thuộc một giới riêng khác thực vật","Có, nấm là thực vật không có lá","Nấm là động vật","Nấm là khoáng vật"],"a":"Không, nấm thuộc một giới riêng khác thực vật","h":"Nấm không có chất xanh và không quang hợp được.","e":"Nấm thuộc giới nấm riêng: chúng không quang hợp mà sống nhờ phân hủy chất hữu cơ như lá khô, gỗ mục.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao không nên tự hái nấm lạ trong rừng để ăn?","o":["Vì nhiều loài nấm độc trông rất giống nấm ăn được, ăn phải có thể nguy hiểm đến tính mạng","Vì nấm rừng không ngon","Vì nấm sẽ hết trong rừng","Vì nấm chỉ ăn được khi nấu với thịt"],"a":"Vì nhiều loài nấm độc trông rất giống nấm ăn được, ăn phải có thể nguy hiểm đến tính mạng","h":"Ngay cả người lớn cũng khó phân biệt nấm độc bằng mắt thường.","e":"Nhiều nấm độc có hình dáng, màu sắc giống hệt nấm ăn được; chỉ ăn nấm rõ nguồn gốc và do người lớn chọn mua.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bèo tấm, rong rêu trong ao cho cá lợi ích gì?","o":["Tạo ô-xi trong nước và là nơi trú ẩn, thức ăn của cá nhỏ","Làm nước đục đi","Ăn hết cá con","Không có lợi ích"],"a":"Tạo ô-xi trong nước và là nơi trú ẩn, thức ăn của cá nhỏ","h":"Cá nhỏ hay núp dưới đám bèo để trốn kẻ thù.","e":"Thực vật dưới nước quang hợp tạo ô-xi cho cá thở, đồng thời là nơi trú ẩn và thức ăn của nhiều loài nhỏ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bộ phận nào của cây đưa nước từ rễ lên lá?","o":["Thân cây (các mạch dẫn trong thân)","Hoa","Vỏ quả","Hạt"],"a":"Thân cây (các mạch dẫn trong thân)","h":"Nước đi ngược chiều trọng lực lên ngọn cây cao hàng chục mét.","e":"Trong thân cây có các mạch dẫn nhỏ xíu như ống hút, đưa nước và chất khoáng từ rễ lên tận lá.","t":"khoa-hoc","l":"thu-thach"},{"p":"Mùa nào cây cối đâm chồi nảy lộc mạnh nhất ở miền Bắc nước ta?","o":["Mùa xuân","Mùa đông","Mùa thu","Cuối mùa hè"],"a":"Mùa xuân","h":"\"Mùa xuân là Tết trồng cây\" đấy.","e":"Mùa xuân ấm áp, mưa phùn ẩm ướt là lúc cây cối đâm chồi nảy lộc sau mùa đông lạnh.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nước trên Trái Đất tồn tại ở những dạng (trạng thái) nào?","o":["Lỏng, rắn (băng) và khí (hơi nước)","Chỉ ở dạng lỏng","Chỉ ở dạng băng","Chỉ ở dạng khí"],"a":"Lỏng, rắn (băng) và khí (hơi nước)","h":"Nước đá, nước uống và hơi nước bốc lên từ nồi cơm.","e":"Nước có 3 trạng thái: lỏng (nước thường), rắn (băng, tuyết) và khí (hơi nước trong không khí).","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Ở nhiệt độ nào nước bắt đầu đóng băng?","o":["0 độ C","10 độ C","50 độ C","100 độ C"],"a":"0 độ C","h":"Đây là nhiệt độ của ngăn đá tủ lạnh trở xuống.","e":"Nước đóng băng ở 0 độ C và sôi ở 100 độ C (ở điều kiện thông thường).","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nước sôi ở nhiệt độ nào?","o":["100 độ C","50 độ C","80 độ C","120 độ C"],"a":"100 độ C","h":"Khi nước sôi, bọt khí nổi lên sùng sục.","e":"Nước sôi ở 100 độ C; vì vậy khi nấu ăn ta phải cẩn thận kẻo bị bỏng hơi nước nóng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hơi nước trong không khí gặp lạnh ngưng tụ thành mây và rơi xuống thành gì?","o":["Mưa","Gió","Sấm","Cầu vồng"],"a":"Mưa","h":"Đây là vòng tuần hoàn của nước trong tự nhiên.","e":"Hơi nước bốc lên, gặp lạnh ngưng tụ thành mây; khi nặng quá sẽ rơi xuống thành mưa, thấm vào đất và chảy ra sông biển rồi lại bốc hơi.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Sau cơn mưa, khi mặt trời ló ra, ta thường thấy gì nhiều màu trên bầu trời?","o":["Cầu vồng","Sao băng","Mặt Trăng","Mây đen"],"a":"Cầu vồng","h":"Hiện tượng này có 7 màu xếp cong cong như cây cầu.","e":"Cầu vồng xuất hiện khi ánh nắng chiếu qua các giọt nước mưa, tách ra thành 7 màu: đỏ, cam, vàng, lục, lam, chàm, tím.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cầu vồng có bao nhiêu màu chính?","o":["7 màu","5 màu","3 màu","10 màu"],"a":"7 màu","h":"Đỏ, cam, vàng, lục, lam, chàm và…","e":"Cầu vồng có 7 màu chính: đỏ, cam, vàng, xanh lục, xanh lam (xanh dương), chàm và tím.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao ta thấy tia chớp trước rồi mới nghe tiếng sấm?","o":["Vì ánh sáng đi nhanh hơn âm thanh rất nhiều","Vì sấm được tạo ra sau chớp","Vì tai nghe chậm hơn mắt nhìn","Vì mây che mất tiếng sấm"],"a":"Vì ánh sáng đi nhanh hơn âm thanh rất nhiều","h":"Ánh sáng và âm thanh cùng xuất phát nhưng tốc độ khác nhau.","e":"Tia chớp và tiếng sấm sinh ra cùng lúc, nhưng ánh sáng truyền nhanh hơn âm thanh nhiều lần nên ta thấy chớp trước.","t":"khoa-hoc","l":"thu-thach"},{"p":"Gió là gì?","o":["Là không khí chuyển động","Là mây di chuyển","Là hơi nước bay lên","Là ánh nắng chiếu xuống"],"a":"Là không khí chuyển động","h":"Khi em chạy, em cũng cảm thấy \"gió\" phả vào mặt đấy.","e":"Gió là không khí chuyển động từ nơi này đến nơi khác; gió mạnh hay yếu tùy vào sự chênh lệch khí áp.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Không khí có trọng lượng không?","o":["Có, không khí có trọng lượng dù rất nhẹ","Không, không khí không nặng chút nào","Chỉ không khí nóng mới có","Chỉ không khí lạnh mới có"],"a":"Có, không khí có trọng lượng dù rất nhẹ","h":"Một quả bóng bay căng và quả bóng xẹp cân sẽ khác nhau đấy.","e":"Không khí tuy không nhìn thấy nhưng có trọng lượng; toàn bộ lớp không khí đè lên Trái Đất tạo thành khí áp.","t":"khoa-hoc","l":"thu-thach"},{"p":"Lớp không khí bao bọc quanh Trái Đất được gọi là gì?","o":["Khí quyển","Đại dương","Lớp vỏ đất","Mây"],"a":"Khí quyển","h":"Nhờ lớp này mà sự sống tồn tại được.","e":"Khí quyển là lớp không khí bao quanh Trái Đất, cho ta ô-xi để thở và che chở khỏi nhiều tia có hại của Mặt Trời.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Thành phần nào chiếm nhiều nhất trong không khí?","o":["Khí ni-tơ (khoảng 78%)","Khí ô-xi","Khí các-bô-níc","Hơi nước"],"a":"Khí ni-tơ (khoảng 78%)","h":"Khí ta thở để sống chỉ chiếm khoảng một phần năm thôi.","e":"Không khí gồm khoảng 78% ni-tơ, 21% ô-xi và 1% các khí khác cùng hơi nước.","t":"khoa-hoc","l":"thu-thach"},{"p":"Dụng cụ nào dùng để đo nhiệt độ?","o":["Nhiệt kế","La bàn","Cân","Thước kẻ"],"a":"Nhiệt kế","h":"Khi em sốt, mẹ dùng dụng cụ này kẹp để biết nhiệt độ cơ thể.","e":"Nhiệt kế dùng để đo nhiệt độ của cơ thể, của không khí hay của nước.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Sương mù vào buổi sáng sớm là gì?","o":["Là những giọt nước li ti bay lơ lửng gần mặt đất","Là khói bếp bay lên","Là mây rơi xuống đất","Là bụi mịn"],"a":"Là những giọt nước li ti bay lơ lửng gần mặt đất","h":"Sương mù thực chất là một đám mây ở rất thấp.","e":"Ban đêm không khí lạnh làm hơi nước ngưng tụ thành giọt li ti lơ lửng gần mặt đất — đó là sương mù.","t":"khoa-hoc","l":"thu-thach"},{"p":"Tuyết rơi ở những nơi nào trên Trái Đất?","o":["Nơi rất lạnh như vùng cực và núi cao, mùa đông ở xứ lạnh","Ở mọi nơi khi mùa đông đến","Chỉ ở sa mạc","Chỉ ở gần biển"],"a":"Nơi rất lạnh như vùng cực và núi cao, mùa đông ở xứ lạnh","h":"Ở Việt Nam, tuyết rất hiếm và chỉ có thể xuất hiện trên đỉnh núi cao phía Bắc những ngày rét đậm.","e":"Tuyết rơi khi hơi nước đóng băng thành tinh thể; tuyết thường gặp ở vùng cực, xứ lạnh và đỉnh núi cao.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao mùa hè ta mặc áo màu sáng lại thấy mát hơn áo màu tối?","o":["Vì màu sáng phản chiếu ánh nắng tốt hơn, hấp thụ ít nhiệt hơn","Vì áo sáng nhẹ hơn","Vì áo sáng đắt hơn","Vì màu tối làm từ vải dày hơn"],"a":"Vì màu sáng phản chiếu ánh nắng tốt hơn, hấp thụ ít nhiệt hơn","h":"Hãy nghĩ về cảm giác đứng dưới nắng trong chiếc áo đen.","e":"Màu tối hấp thụ nhiều ánh nắng và nóng lên; màu sáng phản chiếu ánh nắng nên mặc mát hơn vào mùa hè.","t":"khoa-hoc","l":"thu-thach"},{"p":"Băng (nước đá) khi để ra ngoài trời nắng sẽ dần biến thành gì?","o":["Nước lỏng (tan chảy)","Hơi nước ngay lập tức","Cát","Không biến mất"],"a":"Nước lỏng (tan chảy)","h":"Hiện tượng này gọi là sự nóng chảy.","e":"Băng tan chảy thành nước khi ấm lên trên 0 độ C; nước tiếp tục nóng sẽ bay hơi thành hơi nước.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Quần áo phơi ngoài nắng nhanh khô là nhờ hiện tượng gì?","o":["Sự bay hơi của nước trong quần áo","Gió thổi bay nước đi hết","Mặt trời hút nước","Vải tự vắt khô"],"a":"Sự bay hơi của nước trong quần áo","h":"Nước trong áo biến thành hơi bay vào không khí.","e":"Nắng và gió làm nước trong quần áo bay hơi nhanh hơn, nên quần áo mau khô.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi đun nước bằng ấm siêu tốc, ta thấy hơi trắng bốc lên ở vòi ấm. Hơi trắng đó là gì?","o":["Hơi nước gặp lạnh ngưng tụ thành giọt nước li ti","Khói của ấm","Bụi bay lên","Khí ô-xi thoát ra"],"a":"Hơi nước gặp lạnh ngưng tụ thành giọt nước li ti","h":"Hơi nước thật thì trong suốt, không nhìn thấy được đâu.","e":"Hơi trắng là hơi nước nóng gặp không khí lạnh, ngưng tụ thành vô số giọt nước li ti lơ lửng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao các đám mây thường có màu trắng nhưng mây dông lại đen xám?","o":["Vì mây dông rất dày và chứa nhiều nước nên che kín ánh nắng","Vì mây dông làm bằng khói","Vì mây dông ở cao hơn","Vì ban đêm mới có mây dông"],"a":"Vì mây dông rất dày và chứa nhiều nước nên che kín ánh nắng","h":"Đám mây càng dày, ánh sáng càng khó xuyên qua.","e":"Mây mỏng cho ánh nắng xuyên qua nên trông trắng; mây dông dày đặc, chứa nhiều giọt nước nên tối xám và sắp đổ mưa.","t":"khoa-hoc","l":"thu-thach"},{"p":"Mưa đá là gì?","o":["Là những viên băng cứng rơi xuống trong cơn dông mạnh","Là mưa rất lạnh thông thường","Là tuyết rơi mùa hè","Là mưa có màu trắng đục"],"a":"Là những viên băng cứng rơi xuống trong cơn dông mạnh","h":"Viên lớn có thể to bằng quả trứng gà và rất nguy hiểm.","e":"Mưa đá xảy ra trong cơn dông mạnh: giọt nước bị đẩy lên cao đóng băng thành viên đá rồi rơi xuống.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hệ Mặt Trời của chúng ta có bao nhiêu hành tinh?","o":["8 hành tinh","9 hành tinh","7 hành tinh","10 hành tinh"],"a":"8 hành tinh","h":"Hãy đếm: Thủy, Kim, Đất, Hỏa, Mộc, Thổ, Thiên Vương, Hải Vương.","e":"Hệ Mặt Trời có 8 hành tinh; Trái Đất là hành tinh thứ ba tính từ Mặt Trời.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hành tinh nào gần Mặt Trời nhất?","o":["Sao Thủy","Sao Kim","Trái Đất","Sao Hỏa"],"a":"Sao Thủy","h":"Hành tinh này nhỏ và quay quanh Mặt Trời nhanh nhất.","e":"Sao Thủy gần Mặt Trời nhất, một năm trên Sao Thủy chỉ dài 88 ngày Trái Đất.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hành tinh nào lớn nhất trong hệ Mặt Trời?","o":["Sao Mộc","Sao Thổ","Trái Đất","Sao Hải Vương"],"a":"Sao Mộc","h":"Hành tinh này to đến mức chứa được hơn 1.000 Trái Đất.","e":"Sao Mộc là hành tinh lớn nhất, là một khối cầu khí khổng lồ với cơn bão lớn đã tồn tại hàng trăm năm.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hành tinh nào được gọi là \"hành tinh đỏ\"?","o":["Sao Hỏa","Sao Kim","Sao Mộc","Sao Thổ"],"a":"Sao Hỏa","h":"Màu đỏ của nó do đất đá chứa nhiều sắt bị gỉ.","e":"Sao Hỏa có màu đỏ vì bề mặt chứa nhiều ô-xít sắt (gỉ sắt); con người đã đưa nhiều robot lên khám phá nơi này.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hành tinh nào có chiếc vành đai (vòng) rộng và đẹp nổi tiếng?","o":["Sao Thổ","Sao Hỏa","Sao Thủy","Sao Kim"],"a":"Sao Thổ","h":"Vành đai của nó làm từ băng và đá nhỏ.","e":"Sao Thổ nổi tiếng với vành đai sáng rộng làm từ vô số mảnh băng và đá quay quanh nó.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hành tinh nào nóng nhất trong hệ Mặt Trời dù không phải gần Mặt Trời nhất?","o":["Sao Kim","Sao Thủy","Sao Hỏa","Sao Mộc"],"a":"Sao Kim","h":"Lớp khí dày của nó giữ nhiệt như một nhà kính khổng lồ.","e":"Sao Kim nóng nhất (khoảng 465 độ C) vì lớp khí các-bô-níc dày giữ nhiệt, tạo hiệu ứng nhà kính rất mạnh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Mặt Trời có phải là một ngôi sao không?","o":["Có, Mặt Trời là một ngôi sao","Không, Mặt Trời là một hành tinh","Không, Mặt Trời là vệ tinh","Không, Mặt Trời là một đám mây"],"a":"Có, Mặt Trời là một ngôi sao","h":"Ban đêm em nhìn thấy rất nhiều ngôi sao như Mặt Trời ở rất xa.","e":"Mặt Trời là một ngôi sao — một quả cầu khí nóng khổng lồ tự phát sáng; nó ở gần ta nhất nên trông to và sáng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao các hành tinh không tự phát sáng như các ngôi sao mà ta vẫn nhìn thấy chúng?","o":["Vì chúng phản chiếu ánh sáng của Mặt Trời","Vì chúng có đèn rất to","Vì chúng tự cháy như sao","Vì Mặt Trăng chiếu sáng chúng"],"a":"Vì chúng phản chiếu ánh sáng của Mặt Trời","h":"Giống như Mặt Trăng sáng là nhờ ánh nắng phản chiếu vậy.","e":"Hành tinh không tự phát sáng; ta thấy chúng vì bề mặt chúng phản chiếu ánh sáng Mặt Trời đến mắt ta.","t":"khoa-hoc","l":"thu-thach"},{"p":"Mặt Trăng là gì của Trái Đất?","o":["Là vệ tinh tự nhiên","Là một ngôi sao nhỏ","Là một hành tinh","Là một đám mây đặc"],"a":"Là vệ tinh tự nhiên","h":"Nó quay quanh Trái Đất gần một tháng một vòng.","e":"Mặt Trăng là vệ tinh tự nhiên duy nhất của Trái Đất, quay một vòng quanh Trái Đất hết khoảng một tháng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Một vòng quay của Trái Đất quanh Mặt Trời mất bao lâu?","o":["Một năm (khoảng 365 ngày)","Một tháng","Một ngày","Mười năm"],"a":"Một năm (khoảng 365 ngày)","h":"Đó là lý do có năm mới mỗi năm.","e":"Trái Đất quay một vòng quanh Mặt Trời mất khoảng 365 ngày, tạo thành một năm với bốn mùa nối tiếp nhau.","t":"khoa-hoc","l":"thu-thach"},{"p":"Trái Đất tự quay một vòng quanh trục của mình mất bao lâu?","o":["24 giờ (một ngày đêm)","1 giờ","1 tuần","1 tháng"],"a":"24 giờ (một ngày đêm)","h":"Nhờ vòng quay này mà có ngày và đêm.","e":"Trái Đất tự quay một vòng hết 24 giờ; phía hướng về Mặt Trời là ban ngày, phía khuất là ban đêm.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vào mùa hè ở nước ta, ngày và đêm so với nhau thế nào?","o":["Ngày dài hơn đêm","Đêm dài hơn ngày","Ngày đêm bằng nhau đúng 12 giờ","Không có đêm"],"a":"Ngày dài hơn đêm","h":"Mùa hè trời sáng từ rất sớm và tối muộn.","e":"Mùa hè ở bán cầu Bắc, ngày dài hơn đêm; mùa đông thì ngược lại, đêm dài hơn ngày.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao Mặt Trăng có lúc tròn như cái đĩa, có lúc khuyết như lưỡi liềm?","o":["Vì phần Mặt Trăng được Mặt Trời chiếu sáng mà ta nhìn thấy thay đổi mỗi ngày","Vì Mặt Trăng tự thay đổi hình dạng","Vì mây che mất một phần","Vì Trái Đất che bóng lên Mặt Trăng hằng đêm"],"a":"Vì phần Mặt Trăng được Mặt Trời chiếu sáng mà ta nhìn thấy thay đổi mỗi ngày","h":"Mặt Trăng không tự đổi hình, chỉ là góc nhìn của ta thay đổi.","e":"Mặt Trăng luôn là khối cầu; khi nó di chuyển quanh Trái Đất, phần sáng ta nhìn thấy thay đổi dần tạo nên trăng tròn, trăng khuyết.","t":"khoa-hoc","l":"thu-thach"},{"p":"Sao băng (sao sa) thực ra là gì?","o":["Là mảnh đá nhỏ lao vào khí quyển và bốc cháy","Là ngôi sao rơi xuống đất","Là máy bay bay cao","Là đèn trời bay lên"],"a":"Là mảnh đá nhỏ lao vào khí quyển và bốc cháy","h":"Đừng lo, không có ngôi sao nào rơi cả.","e":"Sao băng là những mảnh đá, bụi vũ trụ nhỏ lao vào khí quyển Trái Đất với tốc độ lớn, ma sát nóng lên và phát sáng rồi cháy hết.","t":"khoa-hoc","l":"thu-thach"},{"p":"Dải Ngân Hà mà ta thuộc về là gì?","o":["Là thiên hà chứa hệ Mặt Trời của chúng ta","Là một con sông trên trời","Là một hành tinh lớn","Là một chòm sao"],"a":"Là thiên hà chứa hệ Mặt Trời của chúng ta","h":"Đêm hè trong trẻo, em có thể thấy một dải sáng mờ vắt ngang trời.","e":"Dải Ngân Hà là thiên hà của chúng ta, chứa hàng trăm tỷ ngôi sao, trong đó có Mặt Trời.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Người đầu tiên bay vào vũ trụ là ai?","o":["Yuri Gagarin (Liên Xô)","Neil Armstrong (Mỹ)","Phạm Tuân (Việt Nam)","Buzz Aldrin (Mỹ)"],"a":"Yuri Gagarin (Liên Xô)","h":"Sự kiện này diễn ra năm 1961.","e":"Năm 1961, nhà du hành Liên Xô Yuri Gagarin trở thành người đầu tiên bay vào vũ trụ trên tàu Vostok 1.","t":"khoa-hoc","l":"thu-thach"},{"p":"Người đầu tiên đặt chân lên Mặt Trăng là ai?","o":["Neil Armstrong (Mỹ)","Yuri Gagarin (Liên Xô)","Phạm Tuân (Việt Nam)","Michael Collins (Mỹ)"],"a":"Neil Armstrong (Mỹ)","h":"Câu nói nổi tiếng: \"Một bước đi nhỏ của con người, một bước nhảy vọt của nhân loại\".","e":"Năm 1969, phi hành gia Mỹ Neil Armstrong là người đầu tiên bước đi trên Mặt Trăng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Dụng cụ nào giúp các nhà thiên văn nhìn rõ các vì sao và hành tinh ở rất xa?","o":["Kính thiên văn","Kính lúp","Kính hiển vi","Ống nhòm đồ chơi"],"a":"Kính thiên văn","h":"Dụng cụ này to và thường đặt trên đỉnh núi cao.","e":"Kính thiên văn thu ánh sáng từ các vật thể ở xa giúp ta quan sát sao, hành tinh và thiên hà rõ hơn mắt thường rất nhiều.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao ta thấy Mặt Trời mọc ở phía Đông và lặn ở phía Tây?","o":["Vì Trái Đất tự quay từ Tây sang Đông","Vì Mặt Trời quay quanh Trái Đất","Vì gió thổi mặt trời đi","Vì Mặt Trăng đẩy Mặt Trời"],"a":"Vì Trái Đất tự quay từ Tây sang Đông","h":"Thực ra Mặt Trời đứng yên tương đối, còn Trái Đất thì quay.","e":"Trái Đất tự quay từ Tây sang Đông nên ta thấy Mặt Trời như mọc lên ở phía Đông và lặn xuống phía Tây.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hiện tượng thủy triều (nước biển dâng lên, rút xuống mỗi ngày) chủ yếu do đâu?","o":["Sức hút của Mặt Trăng đối với nước biển","Gió thổi mạnh","Mưa nhiều","Sóng thần"],"a":"Sức hút của Mặt Trăng đối với nước biển","h":"Mặt Trăng tuy nhỏ hơn Trái Đất nhưng ở rất gần.","e":"Sức hút của Mặt Trăng (và một phần của Mặt Trời) kéo nước biển phồng lên gây thủy triều lên xuống mỗi ngày.","t":"khoa-hoc","l":"kho"},{"p":"Khi Mặt Trăng đi vào giữa Trái Đất và Mặt Trời, che khuất Mặt Trời, ta có hiện tượng gì?","o":["Nhật thực","Nguyệt thực","Sao băng","Cầu vồng"],"a":"Nhật thực","h":"Lúc này ban ngày bỗng tối sầm lại trong ít phút.","e":"Nhật thực xảy ra khi Mặt Trăng che khuất Mặt Trời; khi xem nhật thực phải dùng kính bảo vệ mắt chuyên dụng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi Trái Đất đi vào giữa Mặt Trời và Mặt Trăng, bóng Trái Đất che Mặt Trăng, ta có hiện tượng gì?","o":["Nguyệt thực","Nhật thực","Trăng khuyết thường ngày","Mưa sao băng"],"a":"Nguyệt thực","h":"Mặt Trăng lúc này thường có màu đỏ đồng.","e":"Nguyệt thực xảy ra khi bóng của Trái Đất phủ lên Mặt Trăng, làm trăng tối đi và chuyển màu đỏ đồng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Ánh sáng từ Mặt Trời mất khoảng bao lâu để tới Trái Đất?","o":["Khoảng 8 phút","Khoảng 8 giây","Khoảng 8 giờ","Truyền tới ngay lập tức"],"a":"Khoảng 8 phút","h":"Ánh sáng đi nhanh nhất vũ trụ: khoảng 300.000 km mỗi giây.","e":"Ánh sáng Mặt Trời mất khoảng 8 phút mới tới Trái Đất; vì vậy ta luôn nhìn thấy Mặt Trời của 8 phút trước.","t":"khoa-hoc","l":"kho"},{"p":"Vì sao các nhà du hành vũ trụ phải mặc bộ đồ bảo hộ kín mít khi ra ngoài không gian?","o":["Vì ngoài không gian không có không khí để thở và nhiệt độ rất khắc nghiệt","Để trông đẹp khi chụp ảnh","Để không bị ướt mưa","Để bay nhanh hơn"],"a":"Vì ngoài không gian không có không khí để thở và nhiệt độ rất khắc nghiệt","h":"Bộ đồ đó như một con tàu vũ trụ mini bảo vệ con người.","e":"Ngoài không gian không có không khí, áp suất và nhiệt độ cực kỳ khắc nghiệt nên bộ đồ bảo hộ cung cấp ô-xi và bảo vệ cơ thể.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Trên Mặt Trăng, các nhà du hành nhảy cao và nhẹ nhàng hơn trên Trái Đất vì sao?","o":["Vì sức hút (trọng lực) của Mặt Trăng yếu hơn Trái Đất","Vì trên Mặt Trăng không có không khí cản","Vì giày của họ có lò xo","Vì Mặt Trăng nhỏ nên dễ nhảy"],"a":"Vì sức hút (trọng lực) của Mặt Trăng yếu hơn Trái Đất","h":"Mặt Trăng nhỏ và nhẹ hơn Trái Đất nhiều.","e":"Trọng lực trên Mặt Trăng chỉ bằng khoảng một phần sáu trên Trái Đất nên các nhà du hành bước đi nảy lên nhẹ nhàng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao một con tàu biển đi ra xa dần thì thân tàu khuất trước, cột buồm khuất sau cùng?","o":["Vì mặt biển cong theo hình cầu của Trái Đất","Vì mắt ta nhìn kém đi","Vì tàu chìm dần xuống nước","Vì sương mù che thân tàu"],"a":"Vì mặt biển cong theo hình cầu của Trái Đất","h":"Đây là một bằng chứng xưa nhất cho thấy Trái Đất hình cầu.","e":"Vì Trái Đất hình cầu, tàu đi xa sẽ khuất dần sau đường cong của mặt biển: thân tàu biến mất trước, cột buồm cao khuất sau cùng.","t":"khoa-hoc","l":"kho"},{"p":"Tên lửa bay lên được là nhờ điều gì?","o":["Khí nóng phụt mạnh xuống dưới đẩy tên lửa lên trên","Cánh quạt khổng lồ","Gió thổi lên","Nam châm hút từ vũ trụ"],"a":"Khí nóng phụt mạnh xuống dưới đẩy tên lửa lên trên","h":"Giống như quả bóng bay xì hơi bay vụt đi vậy.","e":"Động cơ tên lửa phụt khí nóng với tốc độ lớn xuống phía dưới, lực đẩy ngược lại nâng tên lửa bay lên.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bầu trời ban ngày có màu xanh chủ yếu vì sao?","o":["Vì không khí làm tán xạ ánh sáng xanh của Mặt Trời khắp bầu trời","Vì bầu trời phản chiếu màu của biển","Vì mây có màu xanh nhạt","Vì mắt ta nhìn sai màu"],"a":"Vì không khí làm tán xạ ánh sáng xanh của Mặt Trời khắp bầu trời","h":"Lúc hoàng hôn, ánh sáng đi đường dài hơn nên bầu trời chuyển đỏ cam.","e":"Ánh sáng Mặt Trời gồm nhiều màu; không khí tán xạ màu xanh mạnh nhất nên ta thấy bầu trời màu xanh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Nam châm hút được những vật làm bằng chất gì?","o":["Sắt (và một số kim loại)","Gỗ","Nhựa","Giấy"],"a":"Sắt (và một số kim loại)","h":"Hãy thử đưa nam châm lại gần chiếc đinh và miếng gỗ mà xem.","e":"Nam châm hút sắt và một số kim loại như thép, ni-ken, co-ban; nó không hút gỗ, nhựa, giấy hay nhôm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi đưa hai cực giống nhau của hai thanh nam châm lại gần nhau (ví dụ hai cực Bắc), điều gì xảy ra?","o":["Chúng đẩy nhau ra","Chúng hút nhau chặt","Chúng dính vào nhau","Không có gì xảy ra"],"a":"Chúng đẩy nhau ra","h":"Khác cực thì hút, còn cùng cực thì…","e":"Hai cực cùng tên của nam châm sẽ đẩy nhau, hai cực khác tên (Bắc – Nam) sẽ hút nhau.","t":"khoa-hoc","l":"thu-thach"},{"p":"Nhà phát minh nào nổi tiếng với bóng đèn điện và được gọi là \"phù thủy xứ Menlo Park\"?","o":["Thomas Edison","Albert Einstein","Isaac Newton","Alexander Graham Bell"],"a":"Thomas Edison","h":"Ông đã thử hàng nghìn lần mới làm được bóng đèn sáng bền.","e":"Thomas Edison phát minh bóng đèn điện thực dụng và hệ thống phát điện, giúp thắp sáng cả thế giới.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Ai là người phát minh ra chiếc điện thoại đầu tiên?","o":["Alexander Graham Bell","Thomas Edison","Anh em nhà Wright","Marie Curie"],"a":"Alexander Graham Bell","h":"Cuộc gọi đầu tiên của ông là gọi cho người trợ lý ở phòng bên.","e":"Alexander Graham Bell được công nhận là người phát minh điện thoại vào năm 1876.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hai anh em nào đã chế tạo và bay thành công chiếc máy bay đầu tiên?","o":["Anh em nhà Wright","Anh em nhà Edison","Anh em nhà Bell","Anh em nhà Ford"],"a":"Anh em nhà Wright","h":"Chuyến bay đầu tiên năm 1903 chỉ kéo dài 12 giây.","e":"Năm 1903, hai anh em người Mỹ Orville và Wilbur Wright thực hiện chuyến bay bằng máy bay có động cơ đầu tiên trong lịch sử.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bốn phát minh vĩ đại của người Trung Quốc cổ đại là những gì?","o":["Giấy, la bàn, thuốc súng và kỹ thuật in","Bóng đèn, điện thoại, máy bay, ô tô","Kính thiên văn, đồng hồ, xe đạp, tàu thủy","Ti vi, máy tính, internet, điện thoại"],"a":"Giấy, la bàn, thuốc súng và kỹ thuật in","h":"Cả bốn thứ này đều làm thay đổi cả thế giới.","e":"Người Trung Quốc cổ đại có tứ đại phát minh: làm giấy, la bàn, thuốc súng và in ấn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Kính lúp giúp em nhìn rõ con chữ nhỏ vì nó làm gì?","o":["Làm vật trông to hơn","Làm vật đổi màu","Chiếu đèn vào vật","Thu vật lại gần mắt"],"a":"Làm vật trông to hơn","h":"Kính lúp là một thấu kính cong ở giữa dày hơn ở mép.","e":"Kính lúp là thấu kính hội tụ làm cho hình ảnh của vật trông to hơn, giúp ta đọc chữ nhỏ và quan sát vật nhỏ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Âm thanh có truyền đi được trong khoảng không vũ trụ (chân không) không?","o":["Không, vì không có không khí hay vật chất để truyền âm","Có, âm thanh truyền nhanh hơn cả ánh sáng","Có, nhưng rất nhỏ","Chỉ truyền được tiếng nổ lớn"],"a":"Không, vì không có không khí hay vật chất để truyền âm","h":"Vì vậy trong phim vũ trụ, những vụ nổ \"ầm ầm\" ngoài không gian thực ra không đúng đâu.","e":"Âm thanh cần môi trường như không khí, nước hay vật rắn để truyền đi; trong chân không hoàn toàn không có âm thanh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi em hét to vào một thung lũng rồi nghe tiếng của mình vọng lại, hiện tượng đó gọi là gì?","o":["Tiếng vang (tiếng dội)","Tiếng sấm","Tiếng gió","Tiếng vọng của chim"],"a":"Tiếng vang (tiếng dội)","h":"Âm thanh đập vào vách núi rồi quay lại tai em.","e":"Tiếng vang xảy ra khi âm thanh gặp mặt chắn lớn như vách núi, bức tường và dội ngược lại tai ta.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao chiếc tàu biển bằng sắt nặng hàng nghìn tấn vẫn nổi trên mặt nước?","o":["Vì thân tàu rỗng, chứa nhiều không khí nên tính chung nhẹ hơn nước","Vì sắt nhẹ hơn nước","Vì tàu có động cơ mạnh","Vì nước biển mặn hơn nước ngọt"],"a":"Vì thân tàu rỗng, chứa nhiều không khí nên tính chung nhẹ hơn nước","h":"Một miếng sắt đặc thì chìm, nhưng cái chảo sắt mỏng lại có thể nổi đấy.","e":"Thân tàu rỗng chứa nhiều không khí nên khối lượng riêng trung bình của cả con tàu nhỏ hơn nước, nhờ lực đẩy của nước mà tàu nổi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Lực nào giúp em đi bộ mà không bị trượt ngã và giúp xe đạp phanh lại được?","o":["Lực ma sát","Lực hút của nam châm","Lực đẩy của gió","Lực nổi của nước"],"a":"Lực ma sát","h":"Nếu mặt đường trơn như băng, lực này rất nhỏ nên dễ ngã.","e":"Ma sát là lực cản sinh ra khi hai bề mặt chạm nhau; nhờ ma sát ta đi lại vững vàng, xe phanh được và cầm nắm đồ vật không tuột.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bập bênh ở sân chơi là ví dụ của dụng cụ đơn giản nào trong vật lý?","o":["Đòn bẩy","Ròng rọc","Mặt phẳng nghiêng","Bánh xe"],"a":"Đòn bẩy","h":"Archimedes nói: cho tôi một điểm tựa, tôi sẽ nâng cả Trái Đất.","e":"Bập bênh là đòn bẩy: một thanh cứng tựa trên điểm tựa giúp nâng vật nặng ở đầu bên kia dễ dàng hơn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cột cờ ở sân trường kéo lá cờ lên cao trót lọt nhờ bộ phận đơn giản nào ở trên đỉnh cột?","o":["Ròng rọc","Nam châm","Lò xo","Bánh răng"],"a":"Ròng rọc","h":"Bộ phận này là một bánh xe nhỏ có rãnh cho sợi dây chạy qua.","e":"Ròng rọc trên đỉnh cột cờ giúp đổi hướng lực kéo: ta kéo dây xuống dưới mà lá cờ lại đi lên trên.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao đường lên núi người ta làm quanh co uốn lượn thay vì làm thẳng đứng lên đỉnh?","o":["Vì đường dốc thoai thoải (mặt phẳng nghiêng dài) đi đỡ mệt và xe dễ lên hơn","Để ngắm cảnh được lâu hơn","Để đường đẹp hơn","Vì không đủ đá làm đường thẳng"],"a":"Vì đường dốc thoai thoải (mặt phẳng nghiêng dài) đi đỡ mệt và xe dễ lên hơn","h":"Dốc càng thoải thì đi càng nhẹ, dù quãng đường dài hơn.","e":"Đường quanh co là mặt phẳng nghiêng dài: độ dốc nhỏ giúp xe và người lên cao tốn ít sức hơn dù phải đi xa hơn.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao mọi vật rơi xuống đất mà không bay lên trời?","o":["Vì Trái Đất hút mọi vật về phía nó (trọng lực)","Vì không khí đè vật xuống","Vì vật nào cũng nặng","Vì mặt đất có nam châm"],"a":"Vì Trái Đất hút mọi vật về phía nó (trọng lực)","h":"Nhà bác học Newton đã nghĩ ra điều này khi thấy quả táo rơi.","e":"Trái Đất hút mọi vật về phía tâm của nó — đó là trọng lực, hay còn gọi là lực hút của Trái Đất.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nhà bác học nào nổi tiếng với câu chuyện quả táo rơi và định luật vạn vật hấp dẫn?","o":["Isaac Newton","Albert Einstein","Galileo Galilei","Thomas Edison"],"a":"Isaac Newton","h":"Ông là nhà khoa học vĩ đại người Anh.","e":"Isaac Newton là người nêu ra định luật vạn vật hấp dẫn, giải thích vì sao táo rơi xuống đất và Mặt Trăng quay quanh Trái Đất.","t":"khoa-hoc","l":"thu-thach"},{"p":"Tia sét trong cơn dông thực chất là gì?","o":["Là dòng điện khổng lồ phóng trong không khí","Là ánh sáng của mặt trời bị mây che","Là một ngôi sao rơi","Là lửa từ mặt đất bốc lên"],"a":"Là dòng điện khổng lồ phóng trong không khí","h":"Điện trong tự nhiên mạnh hơn điện trong nhà rất nhiều.","e":"Tia sét là dòng điện cực mạnh phóng giữa các đám mây hoặc từ mây xuống đất khi trời dông.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao trên đường ray tàu hỏa, giữa hai đoạn ray người ta để một khe hở nhỏ?","o":["Để ray có chỗ giãn nở khi trời nóng mà không bị cong vênh","Để tàu chạy êm hơn","Để tiết kiệm sắt","Để nước mưa thoát xuống"],"a":"Để ray có chỗ giãn nở khi trời nóng mà không bị cong vênh","h":"Kim loại nóng lên thì dài ra đấy.","e":"Kim loại nở ra khi nóng và co lại khi lạnh; khe hở giúp đường ray không bị cong vênh vào những ngày nắng nóng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao quả bóng bay để ngoài nắng to lâu có thể bị nổ?","o":["Vì không khí trong bóng nóng lên, nở ra làm bóng căng quá mức","Vì nắng làm cao su tan chảy ngay","Vì gió thổi mạnh","Vì bóng bay sợ nắng"],"a":"Vì không khí trong bóng nóng lên, nở ra làm bóng căng quá mức","h":"Không chỉ chất rắn, chất khí nóng lên cũng nở ra.","e":"Nắng nóng làm không khí trong bóng nở ra, thể tích tăng làm bóng căng vượt giới hạn và nổ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao cục nước đá lại nổi trên mặt nước thay vì chìm xuống như cục đá thường?","o":["Vì băng nhẹ hơn nước lỏng cùng thể tích","Vì trong băng có nhiều bong bóng khí","Vì nước đá có nam châm","Vì băng được sơn chống chìm"],"a":"Vì băng nhẹ hơn nước lỏng cùng thể tích","h":"Đây là tính chất rất đặc biệt của nước, giúp cá sống sót mùa đông.","e":"Khi đóng băng, nước nở ra nên băng nhẹ hơn nước lỏng và nổi lên trên; lớp băng phủ mặt hồ giúp cá ở dưới sống qua mùa đông.","t":"khoa-hoc","l":"kho"},{"p":"Nữ bác học Marie Curie nổi tiếng với công trình nghiên cứu về lĩnh vực gì?","o":["Về các chất phóng xạ","Về các hành tinh","Về động vật biển","Về núi lửa"],"a":"Về các chất phóng xạ","h":"Bà là người phụ nữ đầu tiên đoạt giải Nobel khoa học, và đoạt tới hai lần.","e":"Marie Curie nghiên cứu về phóng xạ, phát hiện hai nguyên tố mới là polonium và radium, đoạt hai giải Nobel ở hai lĩnh vực khác nhau.","t":"khoa-hoc","l":"thu-thach"},{"p":"Nhà bác học \"tóc xù\" nổi tiếng nhất thế giới với công thức E = mc² là ai?","o":["Albert Einstein","Isaac Newton","Thomas Edison","Charles Darwin"],"a":"Albert Einstein","h":"Ông được coi là bộ óc vĩ đại nhất thế kỷ 20.","e":"Albert Einstein là nhà vật lý thiên tài với thuyết tương đối nổi tiếng và công thức E = mc².","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bơm lốp xe đạp căng lên được là nhờ tính chất gì của không khí?","o":["Không khí có thể bị nén lại (ép nhỏ) trong lốp","Không khí tự sinh ra trong lốp","Lốp xe tự phồng lên","Không khí biến thành cao su"],"a":"Không khí có thể bị nén lại (ép nhỏ) trong lốp","h":"Khi bơm, ta đang ép rất nhiều không khí vào một chỗ nhỏ.","e":"Không khí bị nén lại khi bơm; lượng khí lớn ép vào lốp làm lốp căng cứng và nâng được xe cùng người ngồi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Gương soi cho ta nhìn thấy hình của mình nhờ hiện tượng gì của ánh sáng?","o":["Ánh sáng bị phản chiếu (bật lại) trên mặt gương phẳng bóng","Gương tự phát sáng","Gương chụp ảnh rồi phát lại","Mắt ta nhớ lại hình ảnh cũ"],"a":"Ánh sáng bị phản chiếu (bật lại) trên mặt gương phẳng bóng","h":"Mặt nước phẳng lặng cũng soi bóng như gương vậy.","e":"Ánh sáng từ người chiếu tới gương phẳng bóng và phản chiếu trở lại mắt ta, tạo nên hình ảnh trong gương.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Rác thải nào sau đây phân hủy nhanh nhất trong tự nhiên?","o":["Vỏ chuối và lá cây","Túi ni lông","Chai nhựa","Lon kim loại"],"a":"Vỏ chuối và lá cây","h":"Rác từ cây cối và thức ăn được gọi là rác hữu cơ.","e":"Rác hữu cơ như vỏ quả, lá cây phân hủy trong vài tuần; còn nhựa và ni lông phải mất hàng trăm năm mới phân hủy hết.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Một chiếc túi ni lông bị vứt ra môi trường sẽ tồn tại bao lâu mới phân hủy hết?","o":["Hàng trăm năm","Một tuần","Một tháng","Một năm"],"a":"Hàng trăm năm","h":"Lâu hơn cả cuộc đời của một con người đấy.","e":"Túi ni lông mất hàng trăm năm mới phân hủy; vì vậy ta nên dùng túi vải và hạn chế đồ nhựa dùng một lần.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao chặt phá rừng bừa bãi dễ gây ra lũ lụt và sạt lở đất?","o":["Vì mất rễ cây giữ đất và hút nước mưa","Vì rừng làm mưa nhiều hơn","Vì thú rừng bỏ đi hết","Vì đất rừng màu đỏ"],"a":"Vì mất rễ cây giữ đất và hút nước mưa","h":"Hãy nhớ vai trò của rễ cây trên sườn đồi.","e":"Rễ cây giữ đất và giúp đất thấm nước mưa; mất rừng, đất đồi trơ trọi sẽ bị mưa cuốn trôi gây sạt lở và lũ quét.","t":"khoa-hoc","l":"thu-thach"},{"p":"Trồng thêm nhiều cây xanh mang lại lợi ích gì?","o":["Không khí sạch hơn, có bóng mát và là nhà của nhiều loài vật","Làm đường phố chật hơn","Làm trời tối hơn","Không có lợi ích gì"],"a":"Không khí sạch hơn, có bóng mát và là nhà của nhiều loài vật","h":"Cây xanh còn được gọi là lá phổi của Trái Đất.","e":"Cây xanh lọc bụi, nhả ô-xi, cho bóng mát, giảm lũ và là nơi sống của chim, sóc, côn trùng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hành động nào giúp tiết kiệm điện ở nhà?","o":["Tắt đèn và quạt khi ra khỏi phòng","Bật ti vi cả đêm","Mở tủ lạnh lâu cho mát","Bật nhiều bóng đèn cùng lúc"],"a":"Tắt đèn và quạt khi ra khỏi phòng","h":"Điện không tự nhiên mà có, phải tốn than, nước hoặc nắng để làm ra.","e":"Tắt các thiết bị điện khi không dùng giúp tiết kiệm điện, giảm tiền điện và bảo vệ môi trường.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nguồn năng lượng nào sau đây được gọi là năng lượng sạch, không bao giờ cạn?","o":["Năng lượng mặt trời và gió","Than đá","Dầu mỏ","Khí đốt"],"a":"Năng lượng mặt trời và gió","h":"Những nguồn này đến từ thiên nhiên mỗi ngày.","e":"Nắng và gió là năng lượng tái tạo, sạch và không bao giờ cạn; còn than, dầu là nhiên liệu hóa thạch sẽ cạn dần và gây ô nhiễm.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khi dầu tràn ra biển sau sự cố tàu, sinh vật biển bị hại nhiều nhất vì sao?","o":["Dầu bám vào lông chim, mang cá làm chúng không thở và không bay được","Dầu làm nước biển ngọt hơn","Dầu làm cá bơi nhanh hơn","Dầu chỉ làm biển đổi màu"],"a":"Dầu bám vào lông chim, mang cá làm chúng không thở và không bay được","h":"Chim biển bị dính dầu sẽ mất khả năng giữ ấm và bay.","e":"Dầu loang phủ mặt biển, bám vào lông chim và mang cá khiến chúng ngạt thở, mất khả năng giữ ấm và chết dần.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao không nên xả rác xuống sông, hồ và biển?","o":["Vì rác làm bẩn nước, hại cá và các sinh vật sống dưới nước","Vì sông sẽ chảy chậm lại","Vì rác sẽ quay lại nhà mình","Không có lý do"],"a":"Vì rác làm bẩn nước, hại cá và các sinh vật sống dưới nước","h":"Con người cũng uống nước và ăn cá từ những dòng sông đó.","e":"Rác và nước thải làm ô nhiễm sông biển, giết chết tôm cá và quay lại gây bệnh cho chính con người.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Tái chế giấy cũ giúp bảo vệ môi trường theo cách nào?","o":["Giảm số cây rừng phải chặt để làm giấy mới","Làm giấy đẹp hơn","Làm giấy thơm hơn","Không giúp gì"],"a":"Giảm số cây rừng phải chặt để làm giấy mới","h":"Một tấn giấy tái chế cứu được khoảng hơn chục cây xanh.","e":"Làm giấy từ giấy cũ tái chế giúp giảm chặt cây, tiết kiệm nước và năng lượng so với làm giấy từ gỗ mới.","t":"khoa-hoc","l":"thu-thach"},{"p":"Pin cũ và bóng đèn hỏng nên xử lý thế nào cho đúng?","o":["Cho vào thùng rác thải độc hại riêng, không vứt chung rác thường","Vứt xuống sông cho trôi đi","Chôn ở vườn rau","Đốt cùng rác nhà bếp"],"a":"Cho vào thùng rác thải độc hại riêng, không vứt chung rác thường","h":"Trong pin có nhiều chất độc như chì và thủy ngân.","e":"Pin chứa chất độc hại; vứt bừa bãi sẽ làm các chất này ngấm vào đất và nước gây bệnh cho người và vật.","t":"khoa-hoc","l":"thu-thach"},{"p":"Lớp ô-zôn trên cao có ích gì cho sự sống trên Trái Đất?","o":["Ngăn bớt tia tử ngoại có hại của Mặt Trời","Làm cho trời mưa","Tạo ra gió","Làm bầu trời màu xanh"],"a":"Ngăn bớt tia tử ngoại có hại của Mặt Trời","h":"Nó như một tấm kính bảo vệ vô hình vậy.","e":"Lớp ô-zôn trong khí quyển hấp thụ phần lớn tia tử ngoại của Mặt Trời, bảo vệ da và mắt của muôn loài.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hầu hết nước trên Trái Đất là nước gì?","o":["Nước mặn ở biển và đại dương","Nước ngọt ở sông hồ","Nước đóng băng","Nước mưa"],"a":"Nước mặn ở biển và đại dương","h":"Chỉ một phần rất nhỏ nước trên Trái Đất là nước ngọt ta dùng được.","e":"Khoảng 97% nước trên Trái Đất là nước mặn ở biển; nước ngọt rất ít nên ta phải biết tiết kiệm và giữ sạch nguồn nước.","t":"khoa-hoc","l":"thu-thach"},{"p":"San hô trong biển thực ra là gì?","o":["Là loài động vật nhỏ sống thành tập đoàn lớn","Là một loại đá quý","Là cây mọc dưới biển","Là xác của tàu đắm"],"a":"Là loài động vật nhỏ sống thành tập đoàn lớn","h":"San hô không có lá, không quang hợp như cây.","e":"San hô là động vật nhỏ bé họ hàng với sứa; chúng sống thành tập đoàn, tạo nên các rạn san hô là \"thành phố\" của vô số loài cá.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao người nông dân rất cần loài ong?","o":["Vì ong giúp thụ phấn cho cây trồng ra hoa kết quả","Vì ong đuổi hết chim","Vì ong làm đất tốt hơn","Vì ong kêu vui tai"],"a":"Vì ong giúp thụ phấn cho cây trồng ra hoa kết quả","h":"Không có ong, nhiều cây ăn quả sẽ không đậu quả.","e":"Ong bay từ hoa này sang hoa khác mang theo phấn hoa, giúp cây thụ phấn và kết quả; một phần lớn thức ăn của ta nhờ vào ong.","t":"khoa-hoc","l":"thu-thach"},{"p":"Hiện tượng băng ở hai cực Trái Đất đang tan nhanh chủ yếu do nguyên nhân nào?","o":["Trái Đất đang nóng lên vì khí thải nhà kính tăng cao","Mặt Trời đang to ra","Trái Đất nghiêng nhiều hơn","Gió thổi mạnh hơn"],"a":"Trái Đất đang nóng lên vì khí thải nhà kính tăng cao","h":"Khí nhà kính như tấm chăn giữ nhiệt quanh Trái Đất.","e":"Khí thải từ đốt than, dầu làm Trái Đất nóng lên, băng hai cực tan ra khiến nước biển dâng và thời tiết thất thường hơn.","t":"khoa-hoc","l":"kho"},{"p":"Để bảo vệ các loài vật quý hiếm như sao la, voọc, ta cần làm gì?","o":["Bảo vệ rừng nơi chúng sống và không săn bắt, mua bán chúng","Bắt về nuôi trong nhà","Cho chúng ăn thật nhiều kẹo","Không cần làm gì"],"a":"Bảo vệ rừng nơi chúng sống và không săn bắt, mua bán chúng","h":"Nơi sống bị mất là nguy cơ lớn nhất của các loài quý hiếm.","e":"Bảo vệ rừng và nghiêm cấm săn bắt, buôn bán động vật hoang dã là cách tốt nhất để cứu các loài quý hiếm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Núi lửa phun ra chất lỏng nóng đỏ gọi là gì?","o":["Dung nham (mắc-ma khi còn dưới lòng đất)","Nước sôi","Kim loại lỏng của con người","Dầu mỏ"],"a":"Dung nham (mắc-ma khi còn dưới lòng đất)","h":"Chất này nóng tới hơn 1.000 độ C.","e":"Dung nham là đá nóng chảy từ lòng đất phun lên; sau khi nguội nó đông lại thành đá núi lửa màu đen xám.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Động đất xảy ra chủ yếu do nguyên nhân nào?","o":["Các mảng đất đá khổng lồ dưới lòng đất dịch chuyển và va chạm","Gió bão rất mạnh","Mưa lớn kéo dài","Con người khoan đất"],"a":"Các mảng đất đá khổng lồ dưới lòng đất dịch chuyển và va chạm","h":"Trái Đất của ta như có một lớp vỏ gồm nhiều mảng ghép lại.","e":"Vỏ Trái Đất gồm nhiều mảng lớn luôn chậm chậm dịch chuyển; khi chúng va chạm hoặc trượt qua nhau sẽ gây động đất.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bên trong lòng Trái Đất, ở phần lõi, nhiệt độ như thế nào?","o":["Rất nóng, nóng như bề mặt Mặt Trời (khoảng 5.000–6.000 độ C)","Lạnh như băng","Bằng nhiệt độ phòng","Khoảng 100 độ C"],"a":"Rất nóng, nóng như bề mặt Mặt Trời (khoảng 5.000–6.000 độ C)","h":"Nhờ vậy mà lõi Trái Đất phần ngoài là kim loại nóng chảy.","e":"Lõi Trái Đất cực kỳ nóng, tới khoảng 5.000–6.000 độ C, nóng ngang bề mặt Mặt Trời.","t":"khoa-hoc","l":"kho"},{"p":"Hóa thạch là gì?","o":["Là dấu vết hoặc di tích của sinh vật thời xưa được lưu giữ trong đá","Là một loại đá quý","Là trứng của khủng long bằng đá","Là đồ chơi bằng đá"],"a":"Là dấu vết hoặc di tích của sinh vật thời xưa được lưu giữ trong đá","h":"Nhờ hóa thạch, các nhà khoa học biết được loài vật thời xưa trông thế nào.","e":"Hóa thạch là xương, vỏ, dấu chân… của sinh vật thời cổ đại bị chôn vùi và hóa đá qua hàng triệu năm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khủng long tuyệt chủng cách đây khoảng bao lâu?","o":["Khoảng 66 triệu năm","Khoảng 66 nghìn năm","Khoảng 660 năm","Chúng chưa tuyệt chủng"],"a":"Khoảng 66 triệu năm","h":"Lúc đó trên Trái Đất chưa hề có con người.","e":"Khủng long tuyệt chủng cách đây khoảng 66 triệu năm, nhiều nhà khoa học cho rằng do một thiên thạch lớn va vào Trái Đất gây biến đổi khí hậu mạnh.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khủng long bạo chúa (T-rex) là loài ăn gì?","o":["Ăn thịt, với hàm răng to và sắc","Ăn cỏ","Ăn lá cây","Ăn cá là chính"],"a":"Ăn thịt, với hàm răng to và sắc","h":"Nó là \"vua\" của các loài khủng long săn mồi.","e":"T-rex là khủng long ăn thịt khổng lồ với cái đầu to, hàm răng sắc như dao và đôi chân sau cực khỏe; tay của nó lại rất nhỏ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Những con khủng long cổ dài khổng lồ (như khủng long cổ dài ăn cỏ) ăn gì để sống?","o":["Lá cây trên những ngọn cây cao","Thịt các con vật khác","Cá dưới sông","Côn trùng"],"a":"Lá cây trên những ngọn cây cao","h":"Chiếc cổ dài như cần cẩu giúp chúng với tới nơi cao.","e":"Khủng long cổ dài là loài ăn thực vật; chiếc cổ dài giúp chúng ăn lá ở ngọn cây cao và thân hình khổng lồ khiến ít kẻ thù dám tấn công.","t":"khoa-hoc","l":"thu-thach"},{"p":"Loài vật ngày nay nào được coi là hậu duệ còn sống của một nhóm khủng long?","o":["Chim","Cá sấu là duy nhất","Rắn","Ếch"],"a":"Chim","h":"Đây là kết luận khiến nhiều người bất ngờ đấy.","e":"Các nhà khoa học kết luận chim chính là hậu duệ của một nhóm khủng long có lông vũ; cá sấu cũng là họ hàng gần của khủng long.","t":"khoa-hoc","l":"kho"},{"p":"Than đá hình thành từ đâu qua hàng triệu năm?","o":["Từ cây cối cổ đại bị chôn vùi dưới lòng đất","Từ xương khủng long","Từ cát biển","Từ dung nham núi lửa"],"a":"Từ cây cối cổ đại bị chôn vùi dưới lòng đất","h":"Vì vậy than đá được gọi là nhiên liệu hóa thạch.","e":"Than đá hình thành từ những khu rừng cổ đại bị chôn sâu dưới đất, chịu nóng và ép nén hàng triệu năm.","t":"khoa-hoc","l":"thu-thach"},{"p":"Những thạch nhũ đẹp trong hang động như Phong Nha hình thành nhờ điều gì?","o":["Nước mưa hòa tan đá vôi và nhỏ giọt tích tụ hàng nghìn năm","Do người xưa chạm khắc","Do dung nham chảy qua","Do sóng biển tạo nên"],"a":"Nước mưa hòa tan đá vôi và nhỏ giọt tích tụ hàng nghìn năm","h":"Từng giọt nước mang theo một chút đá lắng lại.","e":"Nước thấm qua khe đá vôi mang theo chất đá hòa tan; nhỏ giọt và lắng đọng hàng nghìn năm tạo thành thạch nhũ và măng đá đẹp kỳ ảo.","t":"khoa-hoc","l":"thu-thach"},{"p":"Khoáng vật tự nhiên nào cứng nhất, thường được mài thành đồ trang sức lấp lánh?","o":["Kim cương","Thạch anh","Vàng","Ngọc trai"],"a":"Kim cương","h":"Nó cứng đến mức cắt được cả kính.","e":"Kim cương là khoáng vật cứng nhất trong tự nhiên, hình thành sâu trong lòng đất dưới nóng và áp suất cực lớn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cát trên bãi biển và trong sa mạc từ đâu mà có?","o":["Từ đá bị gió, nước và thời gian bào mòn, vỡ vụn ra","Từ vỏ ốc mà thôi","Từ muối biển khô lại","Từ bụi vũ trụ rơi xuống"],"a":"Từ đá bị gió, nước và thời gian bào mòn, vỡ vụn ra","h":"Quá trình này diễn ra chậm hàng triệu năm.","e":"Cát chủ yếu là những hạt đá nhỏ bị phong hóa, mài mòn qua thời gian rất dài rồi được gió và nước cuốn đi tích lại.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Dấu vân tay của mỗi người như thế nào?","o":["Không ai giống ai, mỗi người một kiểu riêng","Mọi người đều giống nhau","Anh em sinh đôi thì giống hệt","Thay đổi mỗi năm một kiểu"],"a":"Không ai giống ai, mỗi người một kiểu riêng","h":"Vì thế vân tay dùng để nhận dạng từng người.","e":"Dấu vân tay của mỗi người là duy nhất, ngay cả anh em sinh đôi cũng khác nhau, và không thay đổi suốt cuộc đời.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao ta phải nháy mắt liên tục mỗi ngày?","o":["Để làm ẩm và làm sạch bề mặt con mắt","Để tập thể dục cho mắt","Vì mắt bị khô là chính","Không có lý do"],"a":"Để làm ẩm và làm sạch bề mặt con mắt","h":"Mỗi lần nháy mắt như một lần \"lau kính\" cho mắt vậy.","e":"Nháy mắt giúp dàn đều nước mắt làm ẩm và rửa sạch bụi trên mắt; mỗi ngày ta nháy mắt hàng nghìn lần.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi có bụi bay vào mũi, cơ thể phản ứng bằng cách nào để tống bụi ra?","o":["Hắt hơi thật mạnh","Chảy nước mắt","Đổ mồ hôi","Buồn ngủ"],"a":"Hắt hơi thật mạnh","h":"Phản ứng này rất mạnh và nhanh.","e":"Hắt hơi là phản xạ tống bụi và dị vật ra khỏi mũi bằng luồng hơi mạnh.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Giọng nói của em được tạo ra ở đâu?","o":["Ở dây thanh trong cổ họng, rung lên khi hơi thở đi qua","Ở lưỡi","Ở răng","Ở phổi tự nó"],"a":"Ở dây thanh trong cổ họng, rung lên khi hơi thở đi qua","h":"Hãy đặt tay lên cổ khi nói sẽ cảm thấy rung rung.","e":"Khi nói, hơi từ phổi làm hai dây thanh trong cổ họng rung lên tạo thành tiếng; lưỡi và miệng biến tiếng đó thành lời nói.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao máu của chúng ta có màu đỏ?","o":["Vì trong hồng cầu có chất chứa sắt gọi là huyết sắc tố (hê-mô-glo-bin)","Vì máu chứa phẩm màu","Vì tim nhuộm máu đỏ","Vì ta ăn nhiều cà chua"],"a":"Vì trong hồng cầu có chất chứa sắt gọi là huyết sắc tố (hê-mô-glo-bin)","h":"Chất này cũng giúp máu chở ô-xi.","e":"Hồng cầu chứa huyết sắc tố có sắt nên máu có màu đỏ; chất này gắn ô-xi để chở đi khắp cơ thể.","t":"khoa-hoc","l":"thu-thach"},{"p":"Tóc và móng tay có điểm chung thú vị nào?","o":["Chúng vẫn tiếp tục mọc ra suốt đời","Chúng mọc rồi ngừng hẳn khi 10 tuổi","Chúng không bao giờ dài thêm","Chúng đổi màu mỗi tháng"],"a":"Chúng vẫn tiếp tục mọc ra suốt đời","h":"Vì vậy ta phải cắt móng và cắt tóc thường xuyên.","e":"Tóc và móng tay mọc liên tục suốt đời từ phần gốc của chúng; phần ta cắt đi là phần đã \"chết\" nên không đau.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Phần ruột già trong bụng chủ yếu làm công việc gì trong tiêu hoá?","o":["Hấp thụ nước từ bã thức ăn tạo thành phân","Nghiền nát thức ăn","Tiết mật tiêu mỡ","Hấp thụ hết chất đạm"],"a":"Hấp thụ nước từ bã thức ăn tạo thành phân","h":"Sau khi ruột non lấy chất dinh dưỡng, phần còn lại đi xuống đây.","e":"Ruột già hấp thụ nước và muối khoáng từ bã thức ăn, phần còn lại tạo thành phân để thải ra ngoài.","t":"khoa-hoc","l":"kho"},{"p":"Khi trời lạnh, vì sao da em nổi \"da gà\" và lông dựng lên?","o":["Cơ thể phản ứng để giữ nhiệt, giảm mất nhiệt ra ngoài","Vì da bị khô","Vì em sắp mọc thêm lông","Vì gió thổi mạnh quá"],"a":"Cơ thể phản ứng để giữ nhiệt, giảm mất nhiệt ra ngoài","h":"Các loài thú có lông cũng dựng lông lên khi lạnh đấy.","e":"Lạnh làm các cơ nhỏ ở chân lông co lại, lông dựng lên tạo lớp không khí giữ nhiệt — đó là hiện tượng nổi da gà.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cá mập thuộc nhóm động vật nào?","o":["Là cá, nhưng bộ xương bằng sụn mềm thay vì xương cứng","Là thú như cá heo","Là bò sát biển","Là động vật lưỡng cư"],"a":"Là cá, nhưng bộ xương bằng sụn mềm thay vì xương cứng","h":"Dù to và bơi nhanh, nó thở bằng mang và đẻ trứng hoặc con dưới nước.","e":"Cá mập là cá: nó thở bằng mang, và bộ xương của nó làm bằng sụn mềm dẻo như xương ở tai và mũi của người.","t":"khoa-hoc","l":"thu-thach"},{"p":"Dơi ngủ nghỉ theo tư thế nào thật đặc biệt?","o":["Treo ngược mình từ trên cao xuống","Nằm ngửa trên đất","Ngủ đứng như ngựa","Ngủ trong tổ chim"],"a":"Treo ngược mình từ trên cao xuống","h":"Chân của nó có móc bám rất chắc.","e":"Dơi treo ngược mình trên cành cây hoặc trần hang khi ngủ; tư thế này giúp nó thả mình rơi xuống và bay ngay khi cần.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Một con kiến có thể cõng vật nặng gấp bao nhiêu lần cơ thể nó?","o":["Gấp nhiều lần, có thể tới khoảng 50 lần","Chỉ bằng cơ thể nó","Gấp 2 lần","Kiến không cõng được gì"],"a":"Gấp nhiều lần, có thể tới khoảng 50 lần","h":"Nhờ cơ bắp khỏe so với thân hình bé nhỏ.","e":"Kiến có thể mang vật nặng gấp hàng chục lần cơ thể mình — kiến là một trong những \"vận động viên cử tạ\" khỏe nhất tự nhiên.","t":"khoa-hoc","l":"thu-thach"},{"p":"Ong thợ chỉ đường cho đồng đội đến nơi có hoa bằng cách nào đặc biệt?","o":["Nhảy một điệu nhảy hình số 8 để \"vẽ bản đồ\" bằng điệu nhảy","Hát một bài hát","Để lại dấu chân","Bay đi bay lại nhiều lần cho bạn nhìn"],"a":"Nhảy một điệu nhảy hình số 8 để \"vẽ bản đồ\" bằng điệu nhảy","h":"Điệu nhảy này cho biết cả hướng và khoảng cách đến hoa.","e":"Ong thợ nhảy điệu nhảy lắc bụng hình số 8; góc và độ dài điệu nhảy cho đồng đội biết hướng và khoảng cách tới nguồn hoa.","t":"khoa-hoc","l":"kho"},{"p":"Đàn chim di cư thường bay thành hình gì trên trời để tiết kiệm sức?","o":["Hình chữ V","Hình tròn","Hình vuông","Bay lung tung không hàng lối"],"a":"Hình chữ V","h":"Con bay đầu phải khỏe nhất và được thay phiên.","e":"Bay hình chữ V giúp các con phía sau được luồng khí nâng đỡ từ con phía trước, tiết kiệm sức cho cả đàn trong chuyến bay dài.","t":"khoa-hoc","l":"thu-thach"},{"p":"Tổ yến sào quý giá mà người ta thu hoạch được làm từ gì?","o":["Từ nước bọt của chim yến","Từ lá cây và cỏ","Từ bùn đất","Từ tơ nhện"],"a":"Từ nước bọt của chim yến","h":"Chim yến xây tổ trên vách đá cao ở đảo biển.","e":"Chim yến dùng nước bọt của mình quện thành tổ bám trên vách đá; tổ yến là món ăn bổ dưỡng nổi tiếng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Ngựa có thể ngủ theo cách nào mà nhiều loài vật khác không làm được?","o":["Ngủ đứng","Ngủ treo ngược","Ngủ dưới nước","Ngủ mở mắt trên cây"],"a":"Ngủ đứng","h":"Khớp chân của nó khóa lại được để không bị ngã.","e":"Ngựa có thể ngủ đứng nhờ khớp chân khóa chắc; chúng chỉ nằm xuống khi cần ngủ thật sâu trong thời gian ngắn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Sừng của tê giác được làm từ chất gì?","o":["Chất sừng giống như móng tay và tóc của người","Ngà voi","Xương cứng","Đá"],"a":"Chất sừng giống như móng tay và tóc của người","h":"Vì thế sừng tê giác không hề có tác dụng chữa bệnh như lời đồn.","e":"Sừng tê giác là khối chất sừng (keratin) nén chặt — cùng chất với móng tay và tóc; nó không phải ngà cũng không phải thuốc chữa bệnh.","t":"khoa-hoc","l":"kho"},{"p":"Vì sao lợn (heo) thích lăn mình trong bùn?","o":["Để làm mát cơ thể và chống nắng, chống côn trùng đốt","Vì lợn thích bẩn","Để tìm thức ăn trong bùn là chính","Để tập bơi"],"a":"Để làm mát cơ thể và chống nắng, chống côn trùng đốt","h":"Da lợn không có tuyến mồ hôi để tự làm mát.","e":"Lợn không đổ mồ hôi được nên lăn bùn để làm mát; lớp bùn khô còn che nắng và ngăn ruồi muỗi đốt.","t":"khoa-hoc","l":"thu-thach"},{"p":"Chim hồng hạc có bộ lông màu hồng là nhờ đâu?","o":["Nhờ sắc tố trong thức ăn là tôm, tép và tảo nhỏ mà chúng ăn","Vì chúng sinh ra đã hồng","Vì nắng nhuộm màu lông","Vì chúng lăn trong hoa hồng"],"a":"Nhờ sắc tố trong thức ăn là tôm, tép và tảo nhỏ mà chúng ăn","h":"Hồng hạc nuôi trong vườn thú nếu thiếu thức ăn đó sẽ nhạt màu dần.","e":"Hồng hạc ăn tôm tép và tảo chứa sắc tố carotenoid; sắc tố này làm lông chúng hồng rực — thiếu thức ăn đó lông sẽ phai thành trắng xám.","t":"khoa-hoc","l":"kho"},{"p":"Con vẹt học nói tiếng người được là nhờ khả năng gì?","o":["Bắt chước âm thanh nghe được","Hiểu hết mọi điều người nói","Có dây thanh giống hệt người","Đọc được chữ"],"a":"Bắt chước âm thanh nghe được","h":"Nó nhại lại tiếng chứ không hiểu nghĩa như người đâu.","e":"Vẹt có khả năng bắt chước âm thanh rất giỏi; chúng nhại lại tiếng người và các tiếng động xung quanh mình.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Hổ có bơi giỏi không?","o":["Có, hổ bơi rất giỏi và thích tắm nước","Không, hổ rất sợ nước","Hổ chỉ lội được nước nông","Hổ bơi kém hơn mèo nhà"],"a":"Có, hổ bơi rất giỏi và thích tắm nước","h":"Khác với mèo nhà sợ nước, hổ là ngoại lệ đặc biệt.","e":"Hổ là loài mèo lớn rất thích nước: chúng bơi giỏi, thường xuống sông suối tắm mát và săn mồi.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây nắp ấm \"ăn thịt\" côn trùng bằng cách nào?","o":["Lá biến thành cái bình chứa nước tiêu hóa, côn trùng rơi vào không ra được","Cây có răng cắn con mồi","Cây đuổi theo bắt côn trùng","Cây phun chất độc từ xa"],"a":"Lá biến thành cái bình chứa nước tiêu hóa, côn trùng rơi vào không ra được","h":"Cây này thường mọc ở đất nghèo chất dinh dưỡng.","e":"Nắp ấm có lá hình bình với nắp che; côn trùng trượt vào trong, bị dịch tiêu hóa phân hủy để cây lấy thêm chất đạm nuôi mình.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây xấu hổ (cây trinh nữ) có phản ứng gì đặc biệt khi ta chạm vào lá?","o":["Lá cụp lại và cành rủ xuống","Lá đổi màu đỏ ngay","Cây nhảy lên","Lá rụng hết ngay"],"a":"Lá cụp lại và cành rủ xuống","h":"Chạm nhẹ thôi là nó \"xấu hổ\" cụp lại rồi.","e":"Khi chạm vào, lá cây xấu hổ cụp lại nhanh chóng để tự bảo vệ; sau vài phút lá lại mở ra như cũ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao vào mùa thu, lá nhiều cây ở xứ lạnh chuyển sang vàng, đỏ rồi rụng?","o":["Vì cây ngừng tạo chất xanh, các màu khác trong lá hiện ra","Vì lá bị nắng cháy","Vì sâu ăn hết chất xanh","Vì cây sơn lại lá"],"a":"Vì cây ngừng tạo chất xanh, các màu khác trong lá hiện ra","h":"Chất xanh (diệp lục) che mất các màu kia suốt mùa hè.","e":"Mùa thu lạnh và ít nắng, cây rút chất xanh về thân; sắc vàng, đỏ vốn có trong lá hiện ra rồi lá rụng để cây nghỉ đông.","t":"khoa-hoc","l":"thu-thach"},{"p":"Cây đước ở rừng ngập mặn ven biển có loại rễ đặc biệt nào giúp đứng vững và \"thở\"?","o":["Rễ chống như những chiếc nạng và rễ thở nhô lên khỏi mặt bùn","Rễ bay trong không khí","Không có rễ","Rễ bằng đá"],"a":"Rễ chống như những chiếc nạng và rễ thở nhô lên khỏi mặt bùn","h":"Vùng này ngày hai lần nước biển dâng ngập.","e":"Cây đước có rễ chống hình nạng cắm xuống bùn giữ cây khỏi bị sóng đánh ngã, cùng rễ thở nhô lên để lấy không khí.","t":"khoa-hoc","l":"thu-thach"},{"p":"Loài hoa nào lớn nhất thế giới, có mùi hôi như thịt thối để dụ ruồi đến thụ phấn, mọc ở rừng Đông Nam Á?","o":["Hoa Rafflesia (hoa xác thối)","Hoa hướng dương","Hoa sen","Hoa lan"],"a":"Hoa Rafflesia (hoa xác thối)","h":"Bông hoa này có thể to bằng cái mâm và nặng gần 10 kg.","e":"Hoa Rafflesia ở rừng Đông Nam Á là hoa lớn nhất thế giới (đường kính tới 1 mét) và tỏa mùi hôi để dụ ruồi thụ phấn.","t":"khoa-hoc","l":"kho"},{"p":"Quả chuối khi chín trên cây thường cong lên vì lý do gì?","o":["Vì quả chuối luôn mọc hướng lên tìm ánh sáng","Vì gió thổi cong","Vì ong đậu làm cong","Vì người trồng uốn"],"a":"Vì quả chuối luôn mọc hướng lên tìm ánh sáng","h":"Hãy để ý nải chuối: các quả đều cong ngửa lên trời.","e":"Quả chuối mọc ngược lên phía ánh sáng mặt trời nên cong dần thành hình vòng cung quen thuộc.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Cây lạc (đậu phộng) có điều gì đặc biệt về nơi quả của nó chín?","o":["Quả chín ở dưới lòng đất","Quả chín trên ngọn cây","Quả chín trong nước","Quả chín trong quả khác"],"a":"Quả chín ở dưới lòng đất","h":"Hoa thì nở trên mặt đất, còn quả lại chui xuống đất.","e":"Sau khi thụ phấn, cuống hoa lạc dài ra và đâm xuống đất; quả lạc hình thành và chín ở dưới lòng đất.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Quả dưa hấu chứa phần lớn là gì khiến ăn vào ngày hè rất mát?","o":["Nước (chiếm hơn 90%)","Đường là chính","Chất xơ là chính","Không khí"],"a":"Nước (chiếm hơn 90%)","h":"Ăn dưa hấu vừa giải khát vừa mát người.","e":"Dưa hấu chứa tới khoảng 92% là nước nên ăn rất mát và giải khát trong ngày hè.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao tay cầm của chảo và nồi thường làm bằng nhựa hoặc gỗ thay vì kim loại?","o":["Vì nhựa và gỗ dẫn nhiệt kém, cầm không bị bỏng","Vì nhựa rẻ hơn sắt","Vì kim loại quá nặng","Vì trông đẹp hơn"],"a":"Vì nhựa và gỗ dẫn nhiệt kém, cầm không bị bỏng","h":"Thân nồi bằng kim loại dẫn nhiệt tốt để nấu nhanh chín.","e":"Kim loại dẫn nhiệt tốt giúp nấu nhanh; nhựa, gỗ dẫn nhiệt kém nên làm tay cầm sẽ cách nhiệt, cầm không bỏng tay.","t":"khoa-hoc","l":"thu-thach"},{"p":"Sáng mùa đông, em thở ra thấy \"khói trắng\" từ miệng. Đó là gì?","o":["Hơi nước trong hơi thở gặp không khí lạnh ngưng tụ thành giọt li ti","Khói thật từ phổi","Bụi bay ra từ miệng","Hơi nóng nhìn thấy được"],"a":"Hơi nước trong hơi thở gặp không khí lạnh ngưng tụ thành giọt li ti","h":"Hiện tượng này giống hơi trắng ở vòi ấm đun nước.","e":"Hơi thở ấm và ẩm gặp không khí lạnh buổi sáng sẽ ngưng tụ thành những giọt nước li ti trông như khói trắng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Bóng đèn LED tiết kiệm điện hơn bóng đèn sợi đốt (đèn tròn ngày xưa) vì sao?","o":["Vì phần lớn điện năng biến thành ánh sáng thay vì tỏa nhiệt lãng phí","Vì đèn LED nhỏ hơn","Vì đèn LED không cần dây điện","Vì đèn LED sáng ít hơn"],"a":"Vì phần lớn điện năng biến thành ánh sáng thay vì tỏa nhiệt lãng phí","h":"Sờ vào bóng sợi đốt đang sáng sẽ thấy rất nóng.","e":"Bóng sợi đốt biến phần lớn điện thành nhiệt nóng gây lãng phí; đèn LED biến điện thành ánh sáng hiệu quả hơn nhiều nên tiết kiệm điện.","t":"khoa-hoc","l":"thu-thach"},{"p":"Vì sao ngồi trước quạt em thấy mát dù quạt không làm không khí lạnh đi?","o":["Vì gió quạt làm mồ hôi trên da bay hơi nhanh, mang theo nhiệt","Vì quạt thổi ra hơi lạnh","Vì quạt xua hết nắng","Vì quạt làm phòng nhỏ lại"],"a":"Vì gió quạt làm mồ hôi trên da bay hơi nhanh, mang theo nhiệt","h":"Quạt chỉ tạo gió, không tạo lạnh như điều hòa đâu.","e":"Gió từ quạt làm mồ hôi bay hơi nhanh hơn, lấy đi nhiệt trên da nên ta cảm thấy mát.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao búp bê lật đật không bao giờ ngã hẳn mà luôn tự đứng dậy?","o":["Vì phần đáy của nó nặng và tròn, trọng tâm thấp nên luôn tự cân bằng lại","Vì trong búp bê có nam châm","Vì búp bê có lò xo","Vì nó được dán chặt xuống bàn"],"a":"Vì phần đáy của nó nặng và tròn, trọng tâm thấp nên luôn tự cân bằng lại","h":"Hãy thử đẩy nghiêng nó rồi buông tay mà xem.","e":"Lật đật có đáy tròn và nặng ở dưới, trọng tâm rất thấp; khi bị đẩy nghiêng, trọng lực kéo nó trở lại vị trí đứng thẳng.","t":"khoa-hoc","l":"thu-thach"},{"p":"Con diều giấy bay lên cao được chủ yếu nhờ lực nào?","o":["Lực nâng của gió tác động lên mặt diều nghiêng","Sức hút của mặt trời","Nam châm trong diều","Lực của sợi dây tự kéo lên"],"a":"Lực nâng của gió tác động lên mặt diều nghiêng","h":"Không có gió thì diều không bay lên được.","e":"Gió thổi vào mặt diều đặt nghiêng tạo lực nâng đẩy diều lên; sợi dây giúp người điều khiển giữ và lái diều.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vào mùa đông ở xứ lạnh, mặt hồ đóng băng nhưng cá ở dưới vẫn sống được. Vì sao cá không chết rét?","o":["Vì lớp băng mỏng nổi phía trên cách nhiệt, nước dưới đáy hồ vẫn ở khoảng 4 độ C","Vì cá có áo ấm","Vì cá ngủ đông trong bùn là chính","Vì nước dưới băng tự nóng lên 20 độ"],"a":"Vì lớp băng mỏng nổi phía trên cách nhiệt, nước dưới đáy hồ vẫn ở khoảng 4 độ C","h":"Tính chất nổi của băng mà em đã học giúp ích ở đây đấy.","e":"Băng nổi và phủ kín mặt hồ như tấm chăn cách nhiệt; nước ở đáy sâu giữ khoảng 4 độ C nên cá vẫn sống và bơi được bên dưới.","t":"khoa-hoc","l":"thu-thach"},{"p":"Không khí có vai trò nào sau đây đối với con người và các sinh vật?","o":["Giúp con người và động vật hô hấp để sống","Làm cho đồ vật nặng hơn","Làm cho nước biển mặn hơn","Chỉ dùng để làm mát vào mùa hè"],"a":"Giúp con người và động vật hô hấp để sống","h":"Hãy nhớ trong không khí có khí ô-xi mà chúng ta hít vào mỗi ngày.","e":"Không khí chứa khí ô-xi rất cần cho sự hô hấp của con người, động vật và cả thực vật. Không có không khí, các sinh vật không thể sống được.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Việc làm nào sau đây giúp bảo vệ bầu không khí trong lành?","o":["Đốt rác thải nhựa ngoài sân","Trồng nhiều cây xanh và giữ vệ sinh nơi ở","Đổ dầu thải xuống cống","Đốt than tổ ong trong phòng kín"],"a":"Trồng nhiều cây xanh và giữ vệ sinh nơi ở","h":"Cây xanh giúp không khí thêm trong lành, còn khói bụi làm không khí bị ô nhiễm.","e":"Trồng cây xanh, giữ vệ sinh nơi ở, không đốt rác bừa bãi và hạn chế khói bụi là những việc làm thiết thực để bảo vệ bầu không khí trong lành.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao khi học bài, chúng ta cần có đủ ánh sáng?","o":["Để căn phòng thơm hơn","Để sách vở bền hơn","Ánh sáng giúp mắt nhìn rõ mọi vật xung quanh","Để bàn ghế không bị ẩm"],"a":"Ánh sáng giúp mắt nhìn rõ mọi vật xung quanh","h":"Nếu tắt hết đèn vào ban đêm, em có nhìn thấy chữ trong sách không?","e":"Ánh sáng giúp mắt chúng ta nhìn rõ mọi vật. Học bài ở nơi thiếu ánh sáng lâu ngày sẽ làm mắt mỏi và dễ bị cận thị.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Ánh sáng mặt trời có ích lợi gì đối với cây xanh và con người?","o":["Làm cho cây không cần nước nữa","Làm cho con người không cần ăn uống","Làm cho mọi vật chuyển sang màu xanh","Giúp cây quang hợp tạo thức ăn và giúp cơ thể con người tổng hợp vitamin D"],"a":"Giúp cây quang hợp tạo thức ăn và giúp cơ thể con người tổng hợp vitamin D","h":"Cây xanh cần ánh sáng để làm ra thức ăn nuôi cây.","e":"Ánh sáng mặt trời giúp cây xanh quang hợp để tạo thức ăn và nhả khí ô-xi. Với con người, tắm nắng hợp lý giúp cơ thể tổng hợp vitamin D để xương chắc khỏe.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Âm thanh trong cuộc sống giúp ích cho chúng ta như thế nào?","o":["Làm cho không khí sạch hơn","Giúp mọi người nói chuyện với nhau, nghe nhạc và nghe tiếng còi xe, chuông báo để tránh nguy hiểm","Giúp cây lớn nhanh hơn","Làm cho đồ ăn ngon hơn"],"a":"Giúp mọi người nói chuyện với nhau, nghe nhạc và nghe tiếng còi xe, chuông báo để tránh nguy hiểm","h":"Nhờ nghe được tiếng còi xe, em biết tránh đường khi tham gia giao thông.","e":"Âm thanh giúp con người giao tiếp, học tập, giải trí bằng âm nhạc và nhận biết các tín hiệu cảnh báo như còi xe, chuông báo cháy để giữ an toàn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Âm thanh quá to và kéo dài (tiếng ồn) có thể gây hại gì cho chúng ta?","o":["Làm cho mắt sáng hơn","Làm cho răng chắc khỏe hơn","Làm đau tai, hại thính giác và khiến ta khó ngủ, khó tập trung học bài","Làm cho tóc mọc nhanh hơn"],"a":"Làm đau tai, hại thính giác và khiến ta khó ngủ, khó tập trung học bài","h":"Ở nơi quá ồn ào, em có thấy khó chịu và khó nghe rõ lời cô giáo không?","e":"Tiếng ồn lớn, kéo dài làm hại thính giác, gây khó ngủ, mệt mỏi và giảm khả năng tập trung. Vì vậy, em không nên hét sát tai bạn và cần tránh ở lâu nơi quá ồn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Để sống và lớn lên khỏe mạnh, động vật cần những gì?","o":["Thức ăn, nước uống, không khí để thở và nơi ở có nhiệt độ phù hợp","Chỉ cần thức ăn là đủ","Chỉ cần nước uống là đủ","Không cần gì cả, động vật tự lớn lên"],"a":"Thức ăn, nước uống, không khí để thở và nơi ở có nhiệt độ phù hợp","h":"Hãy nghĩ xem chú chó hoặc con cá cảnh ở nhà em cần gì mỗi ngày.","e":"Giống như con người, động vật cần thức ăn, nước uống, không khí để thở, ánh sáng và nhiệt độ phù hợp mới sống và phát triển được.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vào mùa đông rất lạnh, một số loài động vật ngủ đông hoặc bay đi nơi ấm hơn. Điều đó cho thấy động vật cần điều gì để sống?","o":["Cần có thật nhiều bạn bè","Cần được con người đặt tên cho","Cần được con người cho ăn mỗi ngày","Cần nhiệt độ môi trường phù hợp với cơ thể"],"a":"Cần nhiệt độ môi trường phù hợp với cơ thể","h":"Khi trời quá lạnh hoặc quá nóng, cơ thể động vật sẽ khó chịu và khó sống.","e":"Động vật cần nhiệt độ môi trường phù hợp. Khi mùa đông quá lạnh và thức ăn khan hiếm, một số loài ngủ đông hoặc di cư đến nơi ấm hơn để sống sót.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Em chăm sóc cây trồng ở nhà như thế nào để cây khỏe mạnh?","o":["Để cây tự sống, không cần quan tâm","Mang cây vào phòng tối cho mát","Tưới nước vừa đủ, đặt cây nơi có ánh sáng, bón phân và bắt sâu cho cây","Tưới thật nhiều nước mặn cho cây"],"a":"Tưới nước vừa đủ, đặt cây nơi có ánh sáng, bón phân và bắt sâu cho cây","h":"Cây cần nước, ánh sáng và chất dinh dưỡng trong đất để lớn lên.","e":"Chăm sóc cây trồng gồm: tưới nước vừa đủ, để cây nơi có ánh sáng, bón phân, nhổ cỏ và bắt sâu. Làm tốt những việc này cây sẽ xanh tốt và cho hoa, quả.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chăm sóc vật nuôi đúng cách là làm những việc nào sau đây?","o":["Để vật nuôi tự tìm ăn, không cần cho uống nước","Cho ăn uống sạch sẽ, giữ chuồng trại sạch và đưa đi tiêm phòng khi cần","Nhốt vật nuôi trong hộp kín cả ngày","Cho vật nuôi ăn thật nhiều kẹo bánh"],"a":"Cho ăn uống sạch sẽ, giữ chuồng trại sạch và đưa đi tiêm phòng khi cần","h":"Vật nuôi cũng cần ăn sạch, ở sạch như con người vậy.","e":"Chăm sóc vật nuôi cần cho ăn uống đầy đủ, sạch sẽ, vệ sinh chuồng trại thường xuyên và tiêm phòng bệnh. Vật nuôi khỏe mạnh sẽ lớn nhanh và không lây bệnh cho người.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Loại nấm nào sau đây là nấm ăn được, thường dùng để nấu canh, xào rau?","o":["Nấm mốc xanh mọc trên cơm thiu","Nấm độc màu đỏ sặc sỡ trong rừng","Nấm mốc đen mọc trên bánh mì hỏng","Nấm hương và nấm rơm"],"a":"Nấm hương và nấm rơm","h":"Đây là những loại nấm quen thuộc, hay bán ở chợ để nấu ăn.","e":"Nấm hương, nấm rơm, nấm sò là những loại nấm ăn ngon và giàu chất dinh dưỡng. Em chỉ ăn nấm do người lớn mua hoặc hái chắc chắn, tuyệt đối không ăn nấm lạ.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi làm bánh mì, người ta cho nấm men vào bột để làm gì?","o":["Nấm men giúp bột nở xốp, bánh mềm và thơm ngon","Nấm men làm bánh có màu xanh","Nấm men làm bánh cứng như đá","Nấm men làm mất hết chất dinh dưỡng của bánh"],"a":"Nấm men giúp bột nở xốp, bánh mềm và thơm ngon","h":"Nhờ có nấm men mà chiếc bánh mì phồng to và xốp mềm.","e":"Nấm men là một loại nấm có ích. Khi trộn vào bột và ủ ấm, nấm men làm bột nở ra, giúp bánh mì, bánh bao xốp mềm. Nấm men còn được dùng để làm rượu, bia.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Bạn nhỏ ăn quá nhiều đồ ngọt, thức ăn nhanh và lười vận động trong thời gian dài có thể mắc bệnh gì?","o":["Bệnh suy dinh dưỡng","Bệnh béo phì","Bệnh quáng gà","Bệnh sâu răng do vi khuẩn"],"a":"Bệnh béo phì","h":"Ăn vào nhiều năng lượng hơn mức cơ thể dùng sẽ làm cơ thể tích mỡ.","e":"Ăn quá nhiều chất béo, đồ ngọt và ít vận động khiến cơ thể tích mỡ thừa, dẫn đến béo phì. Trẻ béo phì dễ mệt mỏi và có nguy cơ mắc nhiều bệnh khác.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Trẻ em ăn uống thiếu chất trong thời gian dài, cơ thể gầy yếu và chậm lớn là dấu hiệu của bệnh gì?","o":["Bệnh béo phì","Bệnh thừa cân","Bệnh suy dinh dưỡng","Bệnh cận thị"],"a":"Bệnh suy dinh dưỡng","h":"Cơ thể không được cung cấp đủ chất dinh dưỡng để lớn lên.","e":"Suy dinh dưỡng xảy ra khi trẻ ăn uống thiếu chất trong thời gian dài, khiến cơ thể gầy yếu, chậm lớn và dễ ốm. Em cần ăn đủ bữa, đủ các nhóm chất để phòng bệnh này.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi mua thực phẩm, em nên chọn như thế nào để bảo đảm an toàn?","o":["Chọn quả đã dập nát vì rẻ hơn","Chọn đồ ăn không ghi ngày sản xuất","Chọn thực phẩm đã quá hạn sử dụng","Chọn thực phẩm tươi, sạch, còn hạn sử dụng và có nguồn gốc rõ ràng"],"a":"Chọn thực phẩm tươi, sạch, còn hạn sử dụng và có nguồn gốc rõ ràng","h":"Hãy nhớ xem hạn sử dụng in trên bao bì trước khi mua đồ ăn.","e":"Thực phẩm an toàn là thực phẩm tươi, sạch, còn hạn sử dụng và rõ nguồn gốc. Ăn thực phẩm ôi thiu, quá hạn có thể gây đau bụng, ngộ độc.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Thức ăn đã nấu chín để lâu ngoài trời và có mùi lạ, em nên làm gì?","o":["Không ăn nữa vì thức ăn có thể đã ôi thiu, ăn vào sẽ đau bụng","Ăn thật nhanh cho hết","Mang cho bạn khác ăn thử trước","Để thêm một ngày nữa rồi ăn"],"a":"Không ăn nữa vì thức ăn có thể đã ôi thiu, ăn vào sẽ đau bụng","h":"Mùi lạ là dấu hiệu thức ăn đã bị hỏng.","e":"Thức ăn để lâu ngoài trời dễ bị vi khuẩn xâm nhập và ôi thiu. Khi thức ăn có mùi lạ, màu lạ, em tuyệt đối không ăn và báo cho người lớn biết.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi đi bơi, em cần tuân thủ điều nào sau đây để phòng tránh đuối nước?","o":["Bơi một mình ở ao sâu cho thoải mái","Nhảy xuống vùng nước có biển báo nguy hiểm","Chỉ bơi khi có người lớn đi cùng, ở nơi được phép bơi và không bơi quá xa bờ","Bơi ngay sau khi vừa ăn thật no"],"a":"Chỉ bơi khi có người lớn đi cùng, ở nơi được phép bơi và không bơi quá xa bờ","h":"Người lớn sẽ trông chừng và giúp em khi có nguy hiểm dưới nước.","e":"Để phòng tránh đuối nước, em chỉ bơi ở nơi an toàn, có người lớn đi cùng, khởi động trước khi xuống nước và không bơi ra xa bờ hay vào vùng nước nguy hiểm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi đi thuyền hoặc tập bơi, em nên làm gì để phòng tránh đuối nước?","o":["Đứng lên nhảy nhót trên thuyền","Mặc áo phao đúng cách và ngồi yên trên thuyền","Tháo áo phao ra cho mát","Thò tay chân xuống nước nghịch khi thuyền đang chạy"],"a":"Mặc áo phao đúng cách và ngồi yên trên thuyền","h":"Áo phao giúp em nổi trên mặt nước nếu không may rơi xuống nước.","e":"Mặc áo phao đúng cách khi đi thuyền, đò hoặc khi tập bơi giúp em nổi trên nước và an toàn hơn. Trên thuyền, em cần ngồi yên, không đùa nghịch, không thò tay chân xuống nước.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Trong chuỗi thức ăn: cỏ, châu chấu, chim (chim ăn châu chấu, châu chấu ăn cỏ), thực vật là cỏ giữ vai trò gì?","o":["Là nguồn thức ăn đầu tiên, nuôi sống các động vật ăn cỏ","Là con vật ăn thịt đứng cuối chuỗi","Không có vai trò gì trong chuỗi thức ăn","Là nơi ở duy nhất của chim"],"a":"Là nguồn thức ăn đầu tiên, nuôi sống các động vật ăn cỏ","h":"Mọi chuỗi thức ăn trong tự nhiên thường bắt đầu từ cây xanh.","e":"Thực vật là mắt xích đầu tiên trong chuỗi thức ăn: cây xanh tự tạo thức ăn nhờ ánh sáng mặt trời, rồi trở thành thức ăn cho động vật ăn cỏ, và động vật ăn cỏ lại là thức ăn của động vật ăn thịt.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nếu một khu rừng bị chặt hết cây xanh, điều gì có thể xảy ra với các động vật sống ở đó?","o":["Động vật sẽ tự tạo được thức ăn như cây xanh","Động vật ăn cỏ sẽ khỏe mạnh hơn trước","Không có gì thay đổi với các động vật","Động vật ăn cỏ mất nguồn thức ăn và nơi ở, cả chuỗi thức ăn bị ảnh hưởng"],"a":"Động vật ăn cỏ mất nguồn thức ăn và nơi ở, cả chuỗi thức ăn bị ảnh hưởng","h":"Không còn cây cỏ thì động vật ăn cỏ lấy gì để ăn và ở đâu?","e":"Thực vật vừa là nguồn thức ăn đầu tiên, vừa là nơi ở của nhiều loài vật. Mất rừng, động vật ăn cỏ mất thức ăn và nơi ở, các động vật ăn thịt cũng bị ảnh hưởng theo.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Đất trồng gồm những thành phần chính nào?","o":["Chỉ có cát và đá","Chất khoáng, chất mùn, nước và không khí","Chỉ có nước và không khí","Chỉ có lá cây mục"],"a":"Chất khoáng, chất mùn, nước và không khí","h":"Chất mùn từ xác cây và động vật phân hủy làm cho đất tơi xốp, màu mỡ.","e":"Đất gồm chất khoáng, chất mùn, nước và không khí. Đất có nhiều chất mùn thì tơi xốp và màu mỡ, giúp cây trồng sinh trưởng tốt.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Đất có vai trò gì đối với cây trồng?","o":["Đất chỉ để cây đứng cho đẹp","Đất làm cho cây không cần ánh sáng","Đất giữ cho cây đứng vững và cung cấp nước, chất khoáng cho cây","Đất giúp cây không cần nước"],"a":"Đất giữ cho cây đứng vững và cung cấp nước, chất khoáng cho cây","h":"Rễ cây bám vào đất và hút những gì từ đất để nuôi cây?","e":"Đất là nơi rễ cây bám vào để cây đứng vững, đồng thời cung cấp nước và chất khoáng cho cây lớn lên. Vì vậy, chúng ta cần bảo vệ và cải tạo đất trồng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi em khuấy đều một thìa đường vào cốc nước, đường tan hết và không nhìn thấy nữa. Hỗn hợp thu được gọi là gì?","o":["Hỗn hợp cát và nước","Hỗn hợp dầu và nước","Kết tủa","Dung dịch"],"a":"Dung dịch","h":"Khi một chất tan hoàn toàn trong nước, ta được một hỗn hợp trong suốt gọi là...","e":"Khi đường tan hoàn toàn trong nước, ta thu được dung dịch nước đường. Trong dung dịch, chất tan phân bố đều và không nhìn thấy bằng mắt thường nữa.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Để tách cát ra khỏi nước cát, em dùng cách nào đơn giản nhất?","o":["Lọc qua giấy lọc hoặc vải sạch, cát bị giữ lại còn nước chảy qua","Cho thêm đường vào rồi khuấy đều","Để cốc nước ra ngoài nắng","Dùng tay nhặt từng hạt cát"],"a":"Lọc qua giấy lọc hoặc vải sạch, cát bị giữ lại còn nước chảy qua","h":"Cát không tan trong nước nên có thể bị giữ lại khi nước chảy qua một lớp lọc.","e":"Cát không tan trong nước nên ta tách cát bằng cách lọc: đổ nước cát qua giấy lọc hoặc vải sạch, cát bị giữ lại, nước trong chảy xuống dưới.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Chiếc đinh sắt để lâu ở nơi ẩm ướt bị gỉ sét. Đây là sự biến đổi gì?","o":["Biến đổi lí học vì đinh vẫn là sắt","Không có biến đổi gì xảy ra","Biến đổi hóa học vì đã tạo thành chất mới là gỉ sắt","Biến đổi vì đinh bị bẩn"],"a":"Biến đổi hóa học vì đã tạo thành chất mới là gỉ sắt","h":"Gỉ sắt là một chất mới, khác hẳn với sắt ban đầu.","e":"Sắt bị gỉ là biến đổi hóa học: sắt tác dụng với ô-xi và hơi nước tạo thành gỉ sắt, một chất mới màu nâu đỏ, giòn và khác hẳn sắt ban đầu.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Việc nào sau đây là biến đổi lí học, tức là không tạo thành chất mới?","o":["Đốt tờ giấy thành tro","Nước đá tan chảy thành nước","Thức ăn để lâu bị ôi thiu","Đinh sắt bị gỉ sét"],"a":"Nước đá tan chảy thành nước","h":"Sau khi biến đổi, chất đó vẫn là chính nó, chỉ thay đổi trạng thái hoặc hình dạng.","e":"Nước đá tan thành nước là biến đổi lí học vì chất vẫn là nước, chỉ thay đổi trạng thái. Còn đốt giấy, thức ăn ôi thiu, sắt gỉ đều tạo thành chất mới nên là biến đổi hóa học.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vì sao mọi hoạt động của con người và máy móc đều cần năng lượng?","o":["Năng lượng giúp cơ thể hoạt động, học tập, lao động và giúp máy móc vận hành","Năng lượng chỉ để làm cho đồ vật sáng lên","Năng lượng chỉ cần cho xe cộ, không cần cho con người","Năng lượng làm cho mọi vật nặng thêm"],"a":"Năng lượng giúp cơ thể hoạt động, học tập, lao động và giúp máy móc vận hành","h":"Khi đói và mệt, em có còn sức chạy nhảy và học bài không?","e":"Năng lượng có ở khắp nơi và rất cần thiết: cơ thể cần năng lượng từ thức ăn để sống và hoạt động; máy móc cần năng lượng điện, năng lượng chất đốt để vận hành.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Nếu không có năng lượng điện và chất đốt, cuộc sống của chúng ta sẽ như thế nào?","o":["Vẫn bình thường, không có gì thay đổi","Mọi người sẽ khỏe mạnh hơn","Máy móc tự chạy được mà không cần năng lượng","Rất khó khăn: không có điện thắp sáng, khó nấu chín thức ăn, máy móc ngừng hoạt động"],"a":"Rất khó khăn: không có điện thắp sáng, khó nấu chín thức ăn, máy móc ngừng hoạt động","h":"Hãy tưởng tượng một buổi tối bị mất điện hoàn toàn ở nhà em.","e":"Năng lượng điện và năng lượng chất đốt phục vụ thắp sáng, nấu ăn, đi lại và sản xuất. Thiếu năng lượng, cuộc sống sẽ gặp rất nhiều khó khăn, vì vậy em cần sử dụng năng lượng tiết kiệm.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Một mạch điện đơn giản để thắp sáng bóng đèn gồm những bộ phận nào?","o":["Chỉ cần một bóng đèn","Pin, dây dẫn điện và bóng đèn được nối thành vòng kín","Pin và một cái kéo","Bóng đèn và một chiếc thước nhựa"],"a":"Pin, dây dẫn điện và bóng đèn được nối thành vòng kín","h":"Muốn đèn sáng, dòng điện phải chạy được thành một vòng khép kín.","e":"Mạch điện đơn giản gồm nguồn điện (pin), dây dẫn điện và bóng đèn nối với nhau thành vòng kín. Khi mạch kín, dòng điện chạy qua làm bóng đèn sáng.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Dây điện thường có lõi bằng đồng và vỏ bọc bằng nhựa. Vì sao lại làm như vậy?","o":["Vì đồng và nhựa đều rất rẻ và nhẹ như nhau","Vì nhựa làm cho dòng điện chạy nhanh hơn","Vì đồng dẫn điện tốt, còn nhựa cách điện nên bọc ngoài giúp an toàn","Vì đồng dùng để cách điện, nhựa dùng để dẫn điện"],"a":"Vì đồng dẫn điện tốt, còn nhựa cách điện nên bọc ngoài giúp an toàn","h":"Kim loại như đồng, nhôm cho dòng điện đi qua; nhựa, gỗ khô, cao su thì không.","e":"Các kim loại như đồng, nhôm, sắt là vật dẫn điện, thường dùng làm lõi dây điện. Nhựa, cao su, gỗ khô là vật cách điện, dùng bọc ngoài dây điện và làm tay cầm dụng cụ điện để bảo đảm an toàn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vi khuẩn sống ở đâu xung quanh chúng ta?","o":["Chỉ sống trong bệnh viện","Chỉ sống dưới đáy biển sâu","Không sống ở nơi nào cả","Có ở khắp nơi: trên da, trong đất, nước, không khí và đồ vật, nhưng rất nhỏ nên mắt thường không nhìn thấy được"],"a":"Có ở khắp nơi: trên da, trong đất, nước, không khí và đồ vật, nhưng rất nhỏ nên mắt thường không nhìn thấy được","h":"Muốn nhìn thấy vi khuẩn, các nhà khoa học phải dùng kính hiển vi.","e":"Vi khuẩn là sinh vật rất nhỏ, có ở khắp nơi xung quanh ta: trên da, trong đất, nước, không khí. Muốn quan sát vi khuẩn phải dùng kính hiển vi.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Vi khuẩn có ích được con người dùng để làm món ăn nào sau đây?","o":["Sữa chua và dưa muối chua","Bánh kem","Kẹo ngọt","Nước ngọt có ga"],"a":"Sữa chua và dưa muối chua","h":"Những món ăn này có vị chua nhẹ nhờ quá trình lên men.","e":"Một số vi khuẩn có ích giúp lên men thực phẩm: vi khuẩn lactic làm sữa chua, muối dưa, muối cà. Nhờ chúng, thức ăn có vị chua ngon và bảo quản được lâu hơn.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Môi trường tự nhiên có chức năng gì đối với sinh vật?","o":["Chỉ để con người ngắm cảnh","Làm cho sinh vật không cần thức ăn","Cung cấp thức ăn, nước, không khí và nơi sống cho sinh vật","Làm cho mọi sinh vật giống hệt nhau"],"a":"Cung cấp thức ăn, nước, không khí và nơi sống cho sinh vật","h":"Cá sống nhờ nước, chim sống nhờ cây và không khí — tất cả đều từ môi trường.","e":"Môi trường cung cấp cho sinh vật thức ăn, nước uống, không khí để thở và nơi ở. Không có môi trường phù hợp, sinh vật không thể tồn tại và phát triển.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Rừng cây là môi trường sống quan trọng đối với nhiều loài vật vì sao?","o":["Vì rừng làm cho trời mưa nhiều hơn mỗi ngày","Vì rừng cho nhiều loài vật nơi ở, thức ăn và không khí trong lành","Vì rừng giúp con người không cần trồng trọt","Vì rừng làm cho động vật không cần uống nước"],"a":"Vì rừng cho nhiều loài vật nơi ở, thức ăn và không khí trong lành","h":"Chim làm tổ trên cây, khỉ ăn quả rừng — rừng là ngôi nhà chung của chúng.","e":"Rừng là môi trường sống của rất nhiều loài sinh vật: cây rừng cho nơi ở, thức ăn, bóng mát và giúp không khí trong lành. Bảo vệ rừng là bảo vệ ngôi nhà chung của muôn loài.","t":"khoa-hoc","l":"nhe-nhang"},{"p":"Khi đèn tín hiệu giao thông chuyển sang màu đỏ, người đi đường phải làm gì?","o":["Dừng lại","Đi nhanh qua","Đi chậm lại rồi qua","Bấm còi để qua"],"a":"Dừng lại","h":"Đỏ là dừng, xanh là đi, vàng là chuẩn bị.","e":"Đèn đỏ nghĩa là phải dừng lại trước vạch dừng; đèn xanh mới được đi, đèn vàng báo hiệu chuẩn bị dừng.","t":"an-toan","l":"nhe-nhang"},{"p":"Người đi bộ muốn sang đường an toàn thì nên đi ở đâu?","o":["Trên vạch kẻ đường dành cho người đi bộ (vạch ngựa vằn)","Chỗ nào vắng xe là qua","Giữa ngã tư","Leo qua dải phân cách"],"a":"Trên vạch kẻ đường dành cho người đi bộ (vạch ngựa vằn)","h":"Vạch này có những sọc trắng giống vằn của con ngựa vằn.","e":"Sang đường ở vạch ngựa vằn, nơi có đèn tín hiệu càng tốt; quan sát kỹ hai phía rồi mới bước xuống đường.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi sang đường, em nên nhìn các phía theo thứ tự nào cho đúng?","o":["Nhìn trái, rồi phải, rồi lại trái, thấy an toàn mới đi","Chỉ nhìn bên phải","Chỉ nhìn bên trái","Nhìn lên trời"],"a":"Nhìn trái, rồi phải, rồi lại trái, thấy an toàn mới đi","h":"Ở nước ta xe cộ đi bên phải đường, xe từ bên trái tới gần em trước.","e":"Vì xe chạy phía bên trái đến gần ta trước nên phải nhìn trái trước, rồi nhìn phải, rồi nhìn trái lần nữa cho chắc.","t":"an-toan","l":"thu-thach"},{"p":"Khi ngồi trên xe máy cùng người lớn, em bắt buộc phải làm gì để an toàn?","o":["Đội mũ bảo hiểm vừa đầu và cài quai đúng cách","Đội mũ vải cho mát","Không cần đội gì","Ngồi quay mặt về phía sau"],"a":"Đội mũ bảo hiểm vừa đầu và cài quai đúng cách","h":"Mũ bảo hiểm bảo vệ phần đầu — nơi quan trọng nhất của cơ thể.","e":"Mọi người ngồi trên xe máy, kể cả trẻ em, đều phải đội mũ bảo hiểm đạt chuẩn, vừa đầu và cài quai chắc chắn.","t":"an-toan","l":"nhe-nhang"},{"p":"Điều nào sau đây là ĐÚNG khi ngồi trên xe máy?","o":["Ngồi yên, ôm người lái, không thò chân tay lung tung","Đứng lên trên yên xe","Ngồi vắt vẻo một bên","Cầm ô che cho người lái"],"a":"Ngồi yên, ôm người lái, không thò chân tay lung tung","h":"Hãy tưởng tượng em là \"ba lô\" ngồi gọn sau lưng người lái.","e":"Ngồi xe máy phải ngồi yên, hai tay ôm người lái, hai chân để đúng chỗ; không đùa nghịch hay thò đầu, thò tay ra ngoài.","t":"an-toan","l":"nhe-nhang"},{"p":"Em đang chơi thì quả bóng lăn ra giữa đường lớn nhiều xe. Em nên làm gì?","o":["Không chạy theo bóng; nhờ người lớn lấy giúp hoặc bỏ quả bóng","Chạy thât nhanh ra nhặt bóng","Kêu bạn nhỏ hơn ra lấy","Nằm xuống đường để xe tránh"],"a":"Không chạy theo bóng; nhờ người lớn lấy giúp hoặc bỏ quả bóng","h":"Dù quả bóng có quý đến đâu cũng không quý bằng tính mạng.","e":"Tuyệt đối không lao ra đường nhặt bóng vì xe cộ không dừng kịp; hãy nhờ người lớn giúp hoặc chấp nhận mất quả bóng.","t":"an-toan","l":"thu-thach"},{"p":"Đi bộ trên đường, em nên đi ở đâu?","o":["Trên vỉa hè; nếu không có vỉa hè thì đi sát lề đường","Giữa lòng đường","Đi trên đường ray","Đi chỗ nào cũng được"],"a":"Trên vỉa hè; nếu không có vỉa hè thì đi sát lề đường","h":"Vỉa hè là phần đường dành riêng cho người đi bộ.","e":"Người đi bộ phải đi trên vỉa hè; nơi không có vỉa hè thì đi sát mép đường và luôn để ý xe cộ.","t":"an-toan","l":"nhe-nhang"},{"p":"Ở đoạn đường không có vỉa hè, người đi bộ nên đi phía nào để dễ nhìn thấy xe đang tới?","o":["Đi sát lề và đi ngược chiều với xe đang chạy","Đi cùng chiều xe chạy","Đi giữa đường","Đi theo hàng ngang kín đường"],"a":"Đi sát lề và đi ngược chiều với xe đang chạy","h":"Đi ngược chiều giúp em chủ động nhìn thấy xe và tránh kịp.","e":"Đi bộ ngược chiều xe chạy (sát lề an toàn) giúp ta quan sát được xe đang tới và chủ động tránh.","t":"an-toan","l":"thu-thach"},{"p":"Khi đi xe đạp, điều nào sau đây là nguy hiểm, tuyệt đối không làm?","o":["Buông cả hai tay và đi hàng ba nói chuyện","Đi chậm sát lề phải","Đội mũ bảo hiểm khi đi xe đạp","Dừng lại khi đèn đỏ"],"a":"Buông cả hai tay và đi hàng ba nói chuyện","h":"Buông tay thì không làm chủ được tay lái nữa.","e":"Đi xe đạp không buông hai tay, không đi hàng hai hàng ba chiếm đường, không đeo tai nghe nhạc làm mất tập trung.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi đi xe buýt, em nên lên và xuống xe vào lúc nào?","o":["Khi xe đã dừng hẳn tại điểm đón trả khách","Khi xe đang chạy chậm","Bất cứ lúc nào xe gần đến nơi","Nhảy xuống trước khi xe dừng cho nhanh"],"a":"Khi xe đã dừng hẳn tại điểm đón trả khách","h":"Hãy kiên nhẫn chờ xe đứng yên đã nhé.","e":"Chỉ lên, xuống xe buýt khi xe đã dừng hẳn và cửa mở; không chen lấn, xô đẩy để tránh ngã và bị kẹt cửa.","t":"an-toan","l":"thu-thach"},{"p":"Khi ngồi trong ô tô, em cần làm gì để được an toàn khi xe chạy?","o":["Ngồi yên trên ghế và thắt dây an toàn","Đứng lên ngó ra cửa sổ","Thò đầu ra cửa kính trời","Ngồi vào lòng người lái"],"a":"Ngồi yên trên ghế và thắt dây an toàn","h":"Dây an toàn giữ em khỏi văng về phía trước khi xe phanh gấp.","e":"Ngồi ô tô phải ngồi yên, thắt dây an toàn; trẻ em nên ngồi ghế sau và tuyệt đối không thò đầu, tay ra ngoài cửa xe.","t":"an-toan","l":"nhe-nhang"},{"p":"Vì sao tuyệt đối không được chơi đùa gần đường ray tàu hỏa và không ném đá lên tàu?","o":["Vì tàu chạy rất nhanh, không dừng kịp và đá ném có thể làm vỡ kính, thương người","Vì đường ray rất bẩn","Vì tàu kêu to khó chịu","Vì bảo vệ sẽ phạt tiền là chính"],"a":"Vì tàu chạy rất nhanh, không dừng kịp và đá ném có thể làm vỡ kính, thương người","h":"Tàu hỏa cần quãng đường rất dài mới dừng lại được.","e":"Tàu hỏa chạy nhanh và phanh rất chậm; chơi gần đường ray hay ném đá lên tàu đều cực kỳ nguy hiểm cho em và cho hành khách.","t":"an-toan","l":"thu-thach"},{"p":"Biển báo giao thông hình tròn, viền đỏ, nền trắng thường là loại biển gì?","o":["Biển cấm (cấm làm một việc nào đó)","Biển chỉ đường đi","Biển quảng cáo","Biển chào mừng"],"a":"Biển cấm (cấm làm một việc nào đó)","h":"Hãy nhớ: tròn đỏ là \"cấm\".","e":"Biển tròn viền đỏ là biển báo cấm, ví dụ cấm đi ngược chiều, cấm xe đạp, cấm người đi bộ.","t":"an-toan","l":"nhe-nhang"},{"p":"Biển báo giao thông hình tam giác, viền đỏ, nền vàng thường là loại biển gì?","o":["Biển báo nguy hiểm phía trước để ta cẩn thận","Biển cấm tuyệt đối","Biển chỉ nơi đỗ xe","Biển tên đường"],"a":"Biển báo nguy hiểm phía trước để ta cẩn thận","h":"Hình tam giác như một lời nhắc \"chú ý!\".","e":"Biển tam giác viền đỏ nền vàng là biển cảnh báo nguy hiểm phía trước như đường cong, trẻ em qua đường, đường trơn.","t":"an-toan","l":"thu-thach"},{"p":"Ban đêm đi bộ ngoài đường, mặc quần áo thế nào thì an toàn hơn?","o":["Mặc áo màu sáng hoặc có dải phản quang để lái xe dễ nhìn thấy","Mặc toàn đồ đen cho gọn","Mặc đồ cùng màu với đường","Đội mũ che kín mặt"],"a":"Mặc áo màu sáng hoặc có dải phản quang để lái xe dễ nhìn thấy","h":"Lái xe khó nhìn thấy người đi bộ vào ban đêm.","e":"Ban đêm nên mặc đồ sáng màu hoặc có phản quang để người lái xe nhận ra em từ xa và tránh kịp.","t":"an-toan","l":"thu-thach"},{"p":"Khi nào em mới được tự đi xe máy hoặc xe đạp điện công suất lớn ngoài đường?","o":["Khi đủ tuổi theo quy định của pháp luật và có hiểu biết về giao thông","Khi biết giữ thăng bằng là được","Khi bố mẹ bận không đưa đón được","Khi bạn bè rủ đi cùng"],"a":"Khi đủ tuổi theo quy định của pháp luật và có hiểu biết về giao thông","h":"Luật giao thông quy định rõ độ tuổi cho từng loại xe.","e":"Trẻ em chưa đủ tuổi tuyệt đối không được lái xe máy hay xe đạp điện lớn; hãy đi xe đạp thường, xe buýt hoặc nhờ người lớn đưa đón.","t":"an-toan","l":"nhe-nhang"},{"p":"Nếu thấy một vụ tai nạn giao thông có người bị thương nặng, em nên làm gì?","o":["Giữ khoảng cách an toàn, gọi người lớn và gọi số cấp cứu 115","Lại gần sờ vào người bị thương","Tự khiêng người bị thương vào lề","Đứng xem cùng đám đông giữa đường"],"a":"Giữ khoảng cách an toàn, gọi người lớn và gọi số cấp cứu 115","h":"Di chuyển người bị thương sai cách có thể làm họ nặng hơn.","e":"Khi gặp tai nạn: tránh xa hiện trường nguy hiểm, báo ngay người lớn gần nhất và gọi 115; không tự ý di chuyển người bị thương.","t":"an-toan","l":"thu-thach"},{"p":"Xe đạp điện và xe đạp thường, khi tham gia giao thông em nên đi ở phần đường nào?","o":["Đi sát về phía bên phải theo chiều đi của mình","Đi giữa đường cho nhanh","Đi bên trái ngược chiều","Đi trên vỉa hè đông người"],"a":"Đi sát về phía bên phải theo chiều đi của mình","h":"Nhớ nhé: đi sát phải, theo đúng chiều đường.","e":"Xe đạp và xe đạp điện phải đi sát lề bên phải theo chiều đi, không đi ngược chiều gây nguy hiểm.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi trời mưa to đường trơn, đi xe đạp em cần chú ý điều gì?","o":["Đi chậm lại, phanh nhẹ từ xa và mặc áo mưa gọn gàng không che tầm nhìn","Đi nhanh để về nhà sớm","Buông tay để xòe áo mưa","Đi sát theo đuôi ô tô lớn để tránh mưa"],"a":"Đi chậm lại, phanh nhẹ từ xa và mặc áo mưa gọn gàng không che tầm nhìn","h":"Đường ướt phanh sẽ trượt dài hơn bình thường.","e":"Trời mưa đường trơn: đi chậm, phanh từ xa nhẹ nhàng, mặc áo mưa gọn không trùm kín đầu che mất tầm nhìn và không đi sát xe lớn.","t":"an-toan","l":"thu-thach"},{"p":"Vì sao không được bám vào đuôi xe tải, xe buýt đang chạy khi đi xe đạp?","o":["Vì xe dừng hoặc rẽ bất ngờ sẽ làm em ngã ra đường rất nguy hiểm","Vì xe sẽ chạy chậm lại","Vì tài xế sẽ la mắng","Vì làm vậy xe tốn xăng hơn"],"a":"Vì xe dừng hoặc rẽ bất ngờ sẽ làm em ngã ra đường rất nguy hiểm","h":"Nhiều vụ tai nạn thương tâm đã xảy ra vì trò nghịch này.","e":"Bám theo đuôi xe là trò chơi nguy hiểm chết người: xe phanh gấp hoặc đánh lái là em ngã ngay vào gầm xe hoặc ra giữa đường.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi có cháy, em cần gọi số điện thoại khẩn cấp nào để báo cứu hỏa?","o":["114","113","115","111"],"a":"114","h":"Nhớ nhé: 114 là cứu hỏa.","e":"Số 114 là số điện thoại báo cháy và cứu nạn cứu hộ; khi gọi hãy nói rõ địa chỉ nơi cháy và bình tĩnh trả lời.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi ngửi thấy mùi khét, mùi gas hoặc thấy khói trong nhà, việc đầu tiên em nên làm là gì?","o":["Báo ngay cho người lớn ở gần nhất","Tự đi tìm xem cháy ở đâu một mình","Mở cửa sổ và mặc kệ","Giấu đi không nói cho ai"],"a":"Báo ngay cho người lớn ở gần nhất","h":"Người lớn sẽ biết cách xử lý và gọi cứu hỏa kịp thời.","e":"Ngửi mùi khét, thấy khói hay mùi gas rò rỉ phải báo ngay người lớn; không tự ý kiểm tra bếp gas, ổ điện vì rất nguy hiểm.","t":"an-toan","l":"thu-thach"},{"p":"Điều nào sau đây tuyệt đối không được làm vì dễ gây cháy nhà?","o":["Chơi diêm, bật lửa, nến gần rèm cửa, giấy và quần áo","Đọc sách dưới đèn bàn","Xem ti vi cùng gia đình","Chơi xếp hình trong phòng"],"a":"Chơi diêm, bật lửa, nến gần rèm cửa, giấy và quần áo","h":"Lửa nhỏ cũng có thể bùng thành đám cháy lớn trong chốc lát.","e":"Trẻ em không được nghịch lửa: diêm, bật lửa, nến, pháo đều có thể gây cháy nhà và bỏng nặng.","t":"an-toan","l":"nhe-nhang"},{"p":"Nhà em bị cháy lớn, khói đen mù mịt. Em nên làm gì là ĐÚNG nhất?","o":["Chạy ngay ra ngoài nhà, tri hô cho mọi người biết và gọi 114","Quay lại phòng lấy đồ chơi yêu thích","Trốn vào tủ quần áo","Chạy vào nhà vệ sinh đóng cửa lại"],"a":"Chạy ngay ra ngoài nhà, tri hô cho mọi người biết và gọi 114","h":"Ra khỏi nhà càng nhanh càng tốt, đừng tiếc bất cứ đồ vật nào.","e":"Khi cháy: ra ngoài ngay bằng lối an toàn, hô to báo mọi người, gọi 114; tuyệt đối không quay lại lấy đồ và không trốn trong tủ hay gầm giường.","t":"an-toan","l":"thu-thach"},{"p":"Khi phải di chuyển qua căn phòng đầy khói, em nên di chuyển thế nào?","o":["Cúi thấp người hoặc bò sát sàn, dùng khăn ướt che mũi miệng","Đứng thẳng chạy thật nhanh","Nín thở và nhắm mắt chạy","Leo lên bàn ghế cao"],"a":"Cúi thấp người hoặc bò sát sàn, dùng khăn ướt che mũi miệng","h":"Khói độc thường bay ở trên cao, không khí sạch hơn ở gần sàn.","e":"Khói và khí độc bốc lên cao nên hãy cúi thấp hoặc bò sát sàn nhà, dùng khăn ẩm che mũi miệng để thở và tìm lối thoát.","t":"an-toan","l":"thu-thach"},{"p":"Khi tòa nhà đang cháy, vì sao không được dùng thang máy để chạy xuống?","o":["Vì thang máy có thể mất điện dừng giữa chừng và khói lửa lọt vào rất nguy hiểm","Vì thang máy chạy chậm hơn cầu thang","Vì thang máy chỉ dành cho người lớn","Vì thang máy kêu to"],"a":"Vì thang máy có thể mất điện dừng giữa chừng và khói lửa lọt vào rất nguy hiểm","h":"Hãy luôn chọn cầu thang bộ khi có cháy.","e":"Khi cháy phải dùng cầu thang bộ thoát hiểm; thang máy có thể kẹt do mất điện và trở thành bẫy khói lửa.","t":"an-toan","l":"nhe-nhang"},{"p":"Nếu chẳng may quần áo của em bén lửa bốc cháy, em phải làm gì ngay?","o":["Dừng lại, nằm xuống và lăn qua lăn lại cho lửa tắt","Chạy thật nhanh cho gió thổi tắt lửa","Đứng yên và la hét","Lấy tay phủi lửa"],"a":"Dừng lại, nằm xuống và lăn qua lăn lại cho lửa tắt","h":"Hãy nhớ ba bước: Dừng — Nằm — Lăn.","e":"Quần áo cháy: dừng chạy (chạy làm lửa to hơn), nằm xuống, lăn qua lăn lại nhiều vòng để dập lửa, sau đó gọi người lớn và đi cấp cứu.","t":"an-toan","l":"thu-thach"},{"p":"Vì sao không được chạm vào ổ điện, công tắc khi tay đang ướt?","o":["Vì nước dẫn điện, dễ bị điện giật","Vì sẽ làm bẩn công tắc","Vì tay ướt trơn khó bấm","Vì điện sợ nước"],"a":"Vì nước dẫn điện, dễ bị điện giật","h":"Điện và nước ướt là đôi bạn rất nguy hiểm.","e":"Nước dẫn điện tốt; tay ướt chạm vào thiết bị điện có thể bị điện giật gây nguy hiểm đến tính mạng.","t":"an-toan","l":"nhe-nhang"},{"p":"Điều nào sau đây là cực kỳ nguy hiểm với ổ cắm điện trong nhà?","o":["Chọc que sắt, chìa khóa hay ngón tay vào ổ cắm","Nhìn ổ cắm từ xa","Nhờ bố mẹ cắm phích điện","Để ổ cắm có nắp che an toàn"],"a":"Chọc que sắt, chìa khóa hay ngón tay vào ổ cắm","h":"Ổ cắm điện chỉ dành cho phích cắm của thiết bị.","e":"Tuyệt đối không chọc bất cứ vật gì vào ổ cắm và không tự ý cắm, rút thiết bị điện khi không có người lớn.","t":"an-toan","l":"nhe-nhang"},{"p":"Thấy một đoạn dây điện bị đứt rơi xuống đất sau cơn bão, em nên làm gì?","o":["Tránh xa, không chạm vào và báo ngay cho người lớn","Nhặt lên vắt lên cây cho gọn","Lấy que gỗ gạt ra đường","Chạy qua thật nhanh"],"a":"Tránh xa, không chạm vào và báo ngay cho người lớn","h":"Dây đứt vẫn có thể còn điện và gây giật chết người.","e":"Dây điện đứt có thể vẫn mang điện; hãy tránh xa ít nhất vài mét và báo người lớn hoặc thợ điện xử lý.","t":"an-toan","l":"thu-thach"},{"p":"Vì sao không được thả diều hoặc chơi gần đường dây điện cao thế?","o":["Vì dây diều ướt hoặc vướng vào dây điện sẽ dẫn điện gây giật, rất nguy hiểm","Vì diều sẽ bay quá cao mất luôn","Vì chim sẽ sợ","Vì gió ở đó yếu"],"a":"Vì dây diều ướt hoặc vướng vào dây điện sẽ dẫn điện gây giật, rất nguy hiểm","h":"Nhiều tai nạn thương tâm đã xảy ra khi diều vướng dây điện.","e":"Chỉ chơi và thả diều ở bãi đất trống xa đường dây điện; nếu diều vướng dây điện, tuyệt đối không trèo lên lấy hay giật dây.","t":"an-toan","l":"thu-thach"},{"p":"Khi trời có sấm sét, nơi trú ẩn nào sau đây là an toàn nhất?","o":["Vào trong nhà kiên cố, tránh xa cửa sổ và thiết bị điện","Đứng dưới gốc cây cao giữa đồng","Đứng trên đồi cao cầm ô kim loại","Tắm mưa giữa sân"],"a":"Vào trong nhà kiên cố, tránh xa cửa sổ và thiết bị điện","h":"Sét thường đánh vào những điểm cao và vật dẫn điện.","e":"Khi có dông sét: vào nhà ngay, không trú dưới cây cao, không cầm vật kim loại dài, không tắm mưa và tránh xa mặt nước.","t":"an-toan","l":"thu-thach"},{"p":"Điều nào ĐÚNG khi dùng sạc điện thoại cho an toàn?","o":["Không sạc điện thoại trên giường nệm và không vừa sạc vừa chơi, nhờ người lớn rút sạc khi đầy","Sạc để qua đêm trên gối","Vừa sạc vừa chơi game cho tiện","Dùng sạc lạ rẻ tiền không rõ nguồn gốc"],"a":"Không sạc điện thoại trên giường nệm và không vừa sạc vừa chơi, nhờ người lớn rút sạc khi đầy","h":"Điện thoại khi sạc sẽ nóng lên, để trên nệm rất dễ cháy.","e":"Sạc pin phải để nơi thoáng, cứng và khô ráo; không sạc trên giường, không vừa sạc vừa dùng và rút sạc khi đã đầy để tránh cháy nổ.","t":"an-toan","l":"nhe-nhang"},{"p":"Vì sao không nên cắm quá nhiều thiết bị vào cùng một ổ điện?","o":["Vì ổ điện quá tải dễ nóng chảy, chập điện gây cháy","Vì điện sẽ yếu đi một chút","Vì trông bừa bộn","Vì các thiết bị sẽ hỏng màu"],"a":"Vì ổ điện quá tải dễ nóng chảy, chập điện gây cháy","h":"Mỗi ổ điện chỉ chịu được một lượng điện nhất định.","e":"Cắm chung quá nhiều thiết bị làm ổ điện quá tải, sinh nhiệt, chập cháy — là nguyên nhân của nhiều vụ cháy nhà.","t":"an-toan","l":"thu-thach"},{"p":"Khi ra khỏi nhà đi chơi cả ngày, gia đình em nên nhớ làm gì với bếp và thiết bị điện?","o":["Tắt bếp, khóa gas và rút các thiết bị điện không cần thiết","Để bếp lửa nhỏ cho nhà ấm","Để quạt chạy cho mát nhà","Không cần làm gì"],"a":"Tắt bếp, khóa gas và rút các thiết bị điện không cần thiết","h":"Một phút cẩn thận phòng được hỏa hoạn lớn.","e":"Trước khi ra khỏi nhà: tắt bếp, khóa van gas, tắt và rút điện các thiết bị không dùng đến, nhất là bàn là, bếp điện, ấm siêu tốc.","t":"an-toan","l":"nhe-nhang"},{"p":"Quy tắc quan trọng nhất khi đi bơi hoặc tắm biển là gì?","o":["Chỉ bơi khi có người lớn đi cùng trông coi và bơi ở nơi an toàn","Tự đi bơi một mình cho tự do","Bơi ra càng xa càng giỏi","Bơi lúc sóng to cho thích"],"a":"Chỉ bơi khi có người lớn đi cùng trông coi và bơi ở nơi an toàn","h":"Dù em bơi giỏi đến đâu cũng không được chủ quan.","e":"Trẻ em chỉ được tắm, bơi khi có người lớn giám sát, ở nơi được phép và an toàn; tuyệt đối không tắm sông, hồ một mình.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi đi thuyền, ca nô hoặc tắm biển, em nên mặc gì để an toàn?","o":["Áo phao vừa người và cài khóa chắc chắn","Áo khoác dày cho ấm","Ba lô đựng đồ","Không cần mặc gì thêm"],"a":"Áo phao vừa người và cài khóa chắc chắn","h":"Áo phao giúp em nổi lên nếu chẳng may rơi xuống nước.","e":"Khi đi tàu thuyền và khi tắm biển, mặc áo phao đúng cỡ, cài khóa cẩn thận giúp em nổi và an toàn hơn rất nhiều.","t":"an-toan","l":"nhe-nhang"},{"p":"Trước khi xuống nước bơi, vì sao nên khởi động, làm nóng người trước?","o":["Để cơ bắp ấm lên, tránh bị chuột rút khi xuống nước","Để người lớn khen ngoan","Để bơi nhanh hơn bạn","Không có lý do"],"a":"Để cơ bắp ấm lên, tránh bị chuột rút khi xuống nước","h":"Chuột rút dưới nước là một trong những nguyên nhân gây đuối nước.","e":"Khởi động kỹ làm cơ thể nóng lên, máu lưu thông tốt, tránh chuột rút và sốc nhiệt khi xuống nước lạnh.","t":"an-toan","l":"thu-thach"},{"p":"Đang bơi mà bị chuột rút đau cứng chân, em nên làm gì?","o":["Bình tĩnh, thả nổi ngửa người, co duỗi chân nhẹ nhàng và kêu cứu","Hoảng loạn vùng vẫy mạnh","Lặn xuống sâu cho đỡ đau","Cố bơi thật nhanh vào bờ"],"a":"Bình tĩnh, thả nổi ngửa người, co duỗi chân nhẹ nhàng và kêu cứu","h":"Hoảng loạn khiến em chìm nhanh hơn; thả nổi giúp em thở được.","e":"Bị chuột rút: giữ bình tĩnh, nằm ngửa thả nổi, dùng tay bóp và co duỗi chân cho hết chuột rút đồng thời kêu to để được giúp đỡ.","t":"an-toan","l":"thu-thach"},{"p":"Thấy bạn bị đuối nước ở sông, em bơi chưa giỏi. Cách giúp bạn ĐÚNG nhất là gì?","o":["Hô hoán thật to gọi người lớn, ném phao, sào hoặc dây cho bạn bám","Nhảy ngay xuống nước cứu bạn","Đứng nhìn và chờ bạn tự bơi vào","Chạy về nhà báo rồi mới quay lại"],"a":"Hô hoán thật to gọi người lớn, ném phao, sào hoặc dây cho bạn bám","h":"Rất nhiều người bị đuối nước vì nhảy xuống cứu bạn khi mình bơi chưa giỏi.","e":"Khi thấy người đuối nước: tri hô gọi người lớn ngay, ném vật nổi (phao, can nhựa, dây, sào dài) cho họ bám; không tự nhảy xuống nếu mình không phải người cứu hộ giỏi bơi.","t":"an-toan","l":"thu-thach"},{"p":"Điều nào sau đây em KHÔNG nên làm khi ở bể bơi?","o":["Chạy nhảy trên bờ bể trơn và xô đẩy bạn xuống nước","Đi nhẹ nhàng quanh bể","Xuống bể ở khu vực nông","Nghe theo hiệu lệnh của cứu hộ"],"a":"Chạy nhảy trên bờ bể trơn và xô đẩy bạn xuống nước","h":"Bờ bể ướt rất trơn, ngã có thể đập đầu nguy hiểm.","e":"Ở bể bơi: không chạy nhảy trên bờ trơn, không xô đẩy nhau, không nhảy cắm đầu ở chỗ nước nông và luôn tuân theo quy định của bể.","t":"an-toan","l":"nhe-nhang"},{"p":"Vì sao không nên xuống sông, hồ tắm ngay sau khi ăn no hoặc khi vừa chạy nhảy mệt, người đầy mồ hôi?","o":["Vì dễ bị chuột rút và sốc nhiệt nguy hiểm","Vì nước sẽ bị đục","Vì sẽ làm cá sợ","Không có lý do gì"],"a":"Vì dễ bị chuột rút và sốc nhiệt nguy hiểm","h":"Hãy nghỉ ngơi, lau khô mồ hôi rồi mới xuống nước.","e":"Vừa ăn no hoặc vừa vận động mệt, xuống nước lạnh đột ngột dễ chuột rút, choáng và đuối nước; hãy nghỉ khoảng 20–30 phút trước khi bơi.","t":"an-toan","l":"thu-thach"},{"p":"Ở nhà có em bé nhỏ, xô chậu đựng nước cần được xử lý thế nào cho an toàn?","o":["Đổ hết nước sau khi dùng hoặc đậy kín, để xa tầm với của em bé","Để đầy nước cho tiện dùng","Để giữa lối đi","Không cần quan tâm"],"a":"Đổ hết nước sau khi dùng hoặc đậy kín, để xa tầm với của em bé","h":"Chỉ một ít nước cũng đủ làm em bé ngạt nếu ngã chúi đầu vào.","e":"Xô, chậu, bể nước trong nhà phải đậy kín hoặc đổ hết sau khi dùng vì em bé rất dễ bị đuối nước ngay trong nhà.","t":"an-toan","l":"nhe-nhang"},{"p":"Bể nước, giếng nước ở nhà cần có điều gì để an toàn cho trẻ em?","o":["Có nắp đậy chắc chắn và khóa lại","Để mở cho thoáng khí","Có bậc thang cho trẻ trèo lên xem","Sơn màu đẹp"],"a":"Có nắp đậy chắc chắn và khóa lại","h":"Nhiều tai nạn đuối nước ở nhà xảy ra vì giếng, bể không có nắp.","e":"Giếng và bể nước phải có nắp đậy chắc chắn, thành cao hoặc rào chắn để trẻ không ngã xuống.","t":"an-toan","l":"thu-thach"},{"p":"Khi thấy biển báo \"Cấm tắm – nguy hiểm\" ở bãi biển, em phải làm gì?","o":["Tuyệt đối không xuống tắm ở khu vực đó","Tắm gần bờ một chút thì được","Chờ không có ai nhìn thì tắm","Tắm nhanh rồi lên"],"a":"Tuyệt đối không xuống tắm ở khu vực đó","h":"Biển báo được cắm vì nơi đó từng có người gặp nạn.","e":"Biển cấm tắm báo hiệu vùng nước nguy hiểm (dòng chảy xiết, vực sâu); phải tuân thủ tuyệt đối và tắm ở khu vực có cứu hộ.","t":"an-toan","l":"nhe-nhang"},{"p":"Một người lạ ở cổng trường cho em kẹo và rủ: \"Đi với chú, chú cho thêm đồ chơi\". Em nên làm gì?","o":["Từ chối, đi ngay về phía thầy cô hoặc nơi đông người và kể lại cho người lớn","Đi theo xem đồ chơi ở đâu","Ăn kẹo trước rồi tính","Rủ thêm bạn đi cùng cho vui"],"a":"Từ chối, đi ngay về phía thầy cô hoặc nơi đông người và kể lại cho người lớn","h":"Người tốt thật sự không bao giờ dụ trẻ em đi theo bằng quà bánh.","e":"Tuyệt đối không đi theo và không nhận quà của người lạ; hãy đến chỗ an toàn và kể ngay cho thầy cô, bố mẹ.","t":"an-toan","l":"nhe-nhang"},{"p":"Người lạ dừng xe hỏi đường và bảo em lên xe ngồi chỉ đường cho gần. Em nên làm gì?","o":["Không lên xe; đứng ở khoảng cách an toàn và chỉ tay về phía có người lớn hoặc công an để họ hỏi","Lên xe chỉ đường giúp người ta","Đứng sát vào cửa xe để nói cho rõ","Lấy điện thoại của họ để xem bản đồ hộ"],"a":"Không lên xe; đứng ở khoảng cách an toàn và chỉ tay về phía có người lớn hoặc công an để họ hỏi","h":"Giữ khoảng cách với xe của người lạ là nguyên tắc sống còn.","e":"Không bao giờ lên xe của người lạ vì bất cứ lý do gì; hãy giữ khoảng cách và hướng họ tới người lớn hoặc chú công an.","t":"an-toan","l":"thu-thach"},{"p":"Tan học, một người em chưa từng gặp nói: \"Bố mẹ cháu bận, nhờ chú đón cháu về\". Em nên làm gì?","o":["Không đi theo; vào trường nhờ cô giáo gọi điện cho bố mẹ để kiểm tra","Đi theo vì họ biết tên bố mẹ em","Đi theo nếu họ cho xem điện thoại","Đi theo một đoạn xem có đúng đường về nhà không"],"a":"Không đi theo; vào trường nhờ cô giáo gọi điện cho bố mẹ để kiểm tra","h":"Người xấu có thể biết tên em và tên bố mẹ qua nhiều cách.","e":"Chỉ về với người mà bố mẹ đã dặn trước là sẽ đón; mọi trường hợp khác phải vào trường nhờ thầy cô gọi điện xác nhận với bố mẹ.","t":"an-toan","l":"thu-thach"},{"p":"Vùng cơ thể được đồ bơi che kín là vùng riêng tư của em. Nếu ai đó chạm vào vùng đó hoặc bắt em chạm vào vùng đó của họ, em phải làm gì?","o":["Nói \"KHÔNG!\" dứt khoát, bỏ chạy tới nơi an toàn và kể ngay cho người lớn em tin cậy","Giữ bí mật vì xấu hổ","Im lặng chịu đựng","Chỉ kể cho bạn thân"],"a":"Nói \"KHÔNG!\" dứt khoát, bỏ chạy tới nơi an toàn và kể ngay cho người lớn em tin cậy","h":"Cơ thể của em là của em; không ai được xâm phạm.","e":"Hãy nói KHÔNG, rời đi ngay và kể cho bố mẹ, thầy cô hoặc người lớn tin cậy; em không bao giờ có lỗi trong chuyện này.","t":"an-toan","l":"thu-thach"},{"p":"Điều nào sau đây là \"bí mật xấu\" mà em bắt buộc phải kể cho bố mẹ, dù người kia dặn không được kể?","o":["Bí mật làm em sợ hãi, lo lắng hoặc liên quan đến việc ai đó chạm vào cơ thể em","Bí mật về món quà sinh nhật bất ngờ cho mẹ","Bí mật về kế hoạch tặng quà thầy cô","Bí mật một trò chơi vui với bạn"],"a":"Bí mật làm em sợ hãi, lo lắng hoặc liên quan đến việc ai đó chạm vào cơ thể em","h":"Bí mật vui sẽ sớm được bật mí và làm mọi người vui; bí mật làm em sợ thì khác hẳn.","e":"Bí mật vui là bí mật tạm thời để tạo bất ngờ tốt đẹp; bí mật khiến em sợ, khó chịu hoặc về cơ thể thì phải kể ngay cho người lớn tin cậy.","t":"an-toan","l":"kho"},{"p":"Bị lạc bố mẹ trong siêu thị đông người, cách làm ĐÚNG nhất là gì?","o":["Đứng yên gần đó và tìm chú bảo vệ hoặc cô nhân viên nhờ gọi loa tìm bố mẹ","Chạy khắp nơi tìm bố mẹ","Đi theo một người lạ tốt bụng","Ra bãi xe đứng chờ"],"a":"Đứng yên gần đó và tìm chú bảo vệ hoặc cô nhân viên nhờ gọi loa tìm bố mẹ","h":"Người lớn sẽ quay lại tìm em ở nơi em bị lạc.","e":"Khi bị lạc: đứng yên, tìm nhân viên mặc đồng phục hoặc bảo vệ nhờ giúp đỡ và gọi loa; không tự ý rời khỏi khu vực và không đi theo người lạ.","t":"an-toan","l":"nhe-nhang"},{"p":"Em ở nhà một mình, có người lạ gõ cửa nói là thợ sửa điện cần vào nhà ngay. Em nên làm gì?","o":["Không mở cửa; gọi điện cho bố mẹ để bố mẹ xử lý","Mở cửa cho họ vào sửa","Mở hé cửa xem mặt họ","Cho họ vào rồi khóa cửa phòng mình lại"],"a":"Không mở cửa; gọi điện cho bố mẹ để bố mẹ xử lý","h":"Dù họ nói lý do gì, trẻ ở nhà một mình không mở cửa cho người lạ.","e":"Không mở cửa cho bất kỳ người lạ nào khi ở nhà một mình; hãy gọi điện báo bố mẹ ngay.","t":"an-toan","l":"thu-thach"},{"p":"Thông tin nào sau đây em nên thuộc lòng để khi bị lạc còn nhờ người lớn liên lạc giúp?","o":["Số điện thoại của bố hoặc mẹ và địa chỉ nhà mình","Số điện thoại của bạn thân","Tên trường của em là đủ","Không cần thuộc gì cả"],"a":"Số điện thoại của bố hoặc mẹ và địa chỉ nhà mình","h":"Hãy nhờ bố mẹ cùng em học thuộc ngay hôm nay.","e":"Thuộc số điện thoại của bố mẹ và địa chỉ nhà giúp người lớn liên lạc và đưa em về nhà an toàn khi bị lạc.","t":"an-toan","l":"nhe-nhang"},{"p":"Trên mạng, một người lạ kết bạn với em và xin em gửi ảnh của mình cho họ. Em nên làm gì?","o":["Không gửi bất cứ ảnh nào và báo ngay cho bố mẹ","Gửi một ảnh bình thường thì không sao","Gửi ảnh nhưng che mặt","Hỏi họ là ai rồi mới quyết định"],"a":"Không gửi bất cứ ảnh nào và báo ngay cho bố mẹ","h":"Ảnh gửi đi rồi thì không lấy lại được nữa.","e":"Không gửi ảnh cá nhân cho người lạ trên mạng; hãy chặn họ và kể với bố mẹ ngay.","t":"an-toan","l":"thu-thach"},{"p":"Người quen trên mạng rủ em ra ngoài gặp mặt mà không cho bố mẹ biết. Em nên làm gì?","o":["Tuyệt đối không đi và kể ngay cho bố mẹ","Đi nhưng rủ thêm bạn","Đi gặp ở nơi đông người một lát","Đi nếu họ hứa tặng quà"],"a":"Tuyệt đối không đi và kể ngay cho bố mẹ","h":"Người trên mạng có thể không phải là người như họ nói.","e":"Không bao giờ gặp mặt người quen trên mạng khi chưa có bố mẹ đi cùng và đồng ý; hãy kể ngay cho bố mẹ khi bị rủ rê.","t":"an-toan","l":"thu-thach"},{"p":"Bị một bạn lớn hơn ở trường bắt nạt, đánh hoặc lấy đồ nhiều lần, em nên làm gì?","o":["Kể ngay cho thầy cô và bố mẹ để được giúp đỡ","Giấu kín vì sợ bị trả thù","Tự đánh lại bạn đó","Bỏ học ở nhà"],"a":"Kể ngay cho thầy cô và bố mẹ để được giúp đỡ","h":"Kể ra không phải là \"mách lẻo\" — đó là tự bảo vệ mình.","e":"Khi bị bắt nạt, hãy kể cho thầy cô và bố mẹ; người lớn sẽ giúp chấm dứt việc đó an toàn.","t":"an-toan","l":"nhe-nhang"},{"p":"Em đang đi bộ về nhà thì thấy một chiếc xe lạ chạy chậm bám theo mình. Em nên làm gì?","o":["Đi nhanh về phía cửa hàng hoặc nơi đông người gần nhất, vào trong và gọi điện cho bố mẹ","Tiếp tục đi vào ngõ vắng cho nhanh về nhà","Dừng lại xem họ muốn gì","Chạy ngược vào bụi cây trốn"],"a":"Đi nhanh về phía cửa hàng hoặc nơi đông người gần nhất, vào trong và gọi điện cho bố mẹ","h":"Nơi đông người và có người lớn là nơi an toàn nhất lúc này.","e":"Khi bị bám theo: đến ngay nơi đông người, cửa hàng hoặc nhà người quen, gọi điện cho bố mẹ và không đi vào đường vắng.","t":"an-toan","l":"kho"},{"p":"Khi cảm thấy nguy hiểm hoặc sợ hãi ở nơi công cộng, em nên tìm đến ai để nhờ giúp đỡ?","o":["Chú công an, chú bảo vệ, cô giáo hoặc nhân viên mặc đồng phục ở đó","Một người lạ bất kỳ đi ngang qua","Không tìm ai, tự xử lý","Một anh chị lớn hơn không quen biết"],"a":"Chú công an, chú bảo vệ, cô giáo hoặc nhân viên mặc đồng phục ở đó","h":"Những người mặc đồng phục làm nhiệm vụ ở đó là người đáng tin cậy nhất.","e":"Khi cần giúp đỡ ở nơi công cộng, hãy tìm công an, bảo vệ, giáo viên hoặc nhân viên mặc đồng phục đang làm việc tại đó.","t":"an-toan","l":"nhe-nhang"},{"p":"Em muốn sang nhà bạn chơi hoặc đi chơi xa hơn thường ngày, em cần làm gì trước?","o":["Xin phép và báo cho bố mẹ biết đi đâu, với ai, khi nào về","Đi luôn, về rồi nói sau","Chỉ cần nói với bạn là được","Để lại giấy nhắn trên bàn là đủ"],"a":"Xin phép và báo cho bố mẹ biết đi đâu, với ai, khi nào về","h":"Bố mẹ cần luôn biết em đang ở đâu để bảo vệ em.","e":"Trước khi đi chơi ở đâu, phải xin phép bố mẹ và nói rõ nơi đến, người đi cùng và giờ về; không tự ý thay đổi kế hoạch.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi đi nhà vệ sinh ở nơi công cộng lạ và vắng, em nên làm gì cho an toàn?","o":["Đi cùng người lớn hoặc bạn, không đi một mình vào khu vắng","Đi một mình cho nhanh","Nhờ một người lạ trông chừng hộ","Nhịn về nhà mới đi"],"a":"Đi cùng người lớn hoặc bạn, không đi một mình vào khu vắng","h":"An toàn là trên hết, nhất là ở nơi lạ.","e":"Ở nơi công cộng lạ, trẻ em nên đi vệ sinh cùng người lớn đi kèm và tránh các khu vực vắng người.","t":"an-toan","l":"nhe-nhang"},{"p":"Em bắt buộc phải rửa tay bằng xà phòng vào những lúc nào?","o":["Trước khi ăn, sau khi đi vệ sinh và sau khi từ ngoài đường, sân chơi về nhà","Chỉ khi tay trông bẩn rõ ràng","Một lần vào buổi sáng là đủ","Khi người lớn nhắc mới rửa"],"a":"Trước khi ăn, sau khi đi vệ sinh và sau khi từ ngoài đường, sân chơi về nhà","h":"Nhiều vi khuẩn không nhìn thấy bằng mắt thường đâu.","e":"Rửa tay với xà phòng trước khi ăn, sau khi đi vệ sinh, sau khi chơi và ho, hắt hơi giúp ngăn hầu hết bệnh truyền nhiễm.","t":"an-toan","l":"nhe-nhang"},{"p":"Rửa tay đúng cách với xà phòng cần chà tay khoảng bao lâu?","o":["Khoảng 20 giây (bằng thời gian hát bài \"Chúc mừng sinh nhật\" hai lần)","Rửa qua loa 2 giây","Càng lâu càng tốt, khoảng 10 phút","Chỉ cần nhúng nước là sạch"],"a":"Khoảng 20 giây (bằng thời gian hát bài \"Chúc mừng sinh nhật\" hai lần)","h":"Chà kỹ cả mu bàn tay, kẽ ngón và đầu ngón tay nhé.","e":"Chà xà phòng ít nhất 20 giây khắp các mặt của bàn tay rồi xả sạch — đó là cách rửa tay đúng chuẩn.","t":"an-toan","l":"thu-thach"},{"p":"Vì sao ông bà ta dạy \"ăn chín, uống sôi\"?","o":["Vì nấu chín và đun sôi sẽ diệt vi khuẩn gây bệnh trong thức ăn, nước uống","Vì đồ nóng ngon hơn","Vì ăn đồ sống sẽ lạnh bụng đơn thuần","Vì đó là thói quen xưa không còn đúng"],"a":"Vì nấu chín và đun sôi sẽ diệt vi khuẩn gây bệnh trong thức ăn, nước uống","h":"Nước lã ở sông, suối, vòi chưa đun có thể chứa nhiều mầm bệnh.","e":"Ăn chín uống sôi giúp diệt vi khuẩn, tránh tiêu chảy và các bệnh đường ruột nguy hiểm cho trẻ em.","t":"an-toan","l":"nhe-nhang"},{"p":"Thức ăn để lâu có mùi chua, mùi lạ và nhớt. Em nên làm gì?","o":["Không ăn nữa và báo người lớn bỏ đi","Ngửi lại vài lần cho chắc rồi ăn","Ăn ít thôi thì không sao","Rửa qua nước rồi ăn tiếp"],"a":"Không ăn nữa và báo người lớn bỏ đi","h":"Thức ăn ôi thiu chứa rất nhiều vi khuẩn gây ngộ độc.","e":"Thức ăn ôi thiu phải bỏ đi ngay; ăn vào có thể bị ngộ độc đau bụng, nôn ói phải đi bệnh viện.","t":"an-toan","l":"nhe-nhang"},{"p":"Trước khi ăn bánh, uống sữa hộp, em nên kiểm tra điều gì trên bao bì?","o":["Hạn sử dụng (ngày hết hạn)","Màu sắc bao bì có đẹp không","Giá tiền","Hình vẽ trên hộp"],"a":"Hạn sử dụng (ngày hết hạn)","h":"Đồ ăn hết hạn dù trông vẫn bình thường cũng không an toàn.","e":"Luôn xem hạn sử dụng và tình trạng bao bì; đồ hết hạn hoặc hộp phồng, móp rỉ thì không dùng.","t":"an-toan","l":"thu-thach"},{"p":"Trái cây mua về, trước khi ăn em cần làm gì?","o":["Rửa sạch dưới vòi nước, gọt vỏ nếu cần","Ăn ngay cho tươi","Lau qua bằng tay","Để ra nắng cho chín thêm"],"a":"Rửa sạch dưới vòi nước, gọt vỏ nếu cần","h":"Vỏ trái cây dính bụi bẩn và thuốc trừ sâu còn sót lại.","e":"Rửa sạch trái cây dưới vòi nước chảy và gọt vỏ khi cần giúp loại bỏ bụi bẩn và hóa chất còn bám ngoài vỏ.","t":"an-toan","l":"nhe-nhang"},{"p":"Những hàng quà cổng trường bày đồ ăn trần trụi, không che đậy, ruồi bay đậu đầy. Em có nên mua ăn không?","o":["Không nên, vì đồ ăn đó đã nhiễm bụi bẩn và vi khuẩn","Nên, vì trông rất ngon và rẻ","Mua nhưng ăn ít thôi","Mua về rửa lại là ăn được"],"a":"Không nên, vì đồ ăn đó đã nhiễm bụi bẩn và vi khuẩn","h":"Đồ ăn không rõ nguồn gốc ở cổng trường là mối lo của nhiều phụ huynh đấy.","e":"Chỉ ăn đồ ăn rõ nguồn gốc, được che đậy sạch sẽ; đồ ăn bẩn gây đau bụng, tiêu chảy và ngộ độc.","t":"an-toan","l":"thu-thach"},{"p":"Bạn cùng lớp đang bị cúm ho nhiều và muốn uống chung cốc nước, dùng chung ống hút với em. Em nên làm gì?","o":["Từ chối khéo và dùng cốc riêng của mình","Cho bạn dùng chung cho thân thiết","Uống chung nhưng uống ít thôi","Đổi cốc cho bạn sau khi uống"],"a":"Từ chối khéo và dùng cốc riêng của mình","h":"Vi rút cúm lây qua giọt bắn và đồ dùng chung.","e":"Không dùng chung cốc, ống hút, khăn mặt, bàn chải với người khác, nhất là khi họ đang ốm, để tránh lây bệnh.","t":"an-toan","l":"thu-thach"},{"p":"Khi em bị sốt, ho và sổ mũi, việc làm nào là tốt nhất cho em và các bạn?","o":["Đeo khẩu trang, nghỉ ở nhà cho khỏe hẳn rồi mới đi học lại","Vẫn đi học bình thường không cần khẩu trang","Đi học và ho thoải mái","Uống thuốc của bạn cho nhanh khỏi"],"a":"Đeo khẩu trang, nghỉ ở nhà cho khỏe hẳn rồi mới đi học lại","h":"Nghỉ ngơi giúp em mau khỏe và không lây bệnh cho cả lớp.","e":"Khi bị ốm, hãy nghỉ ở nhà, đeo khẩu trang khi tiếp xúc và chỉ uống thuốc do người lớn hoặc bác sĩ cho.","t":"an-toan","l":"nhe-nhang"},{"p":"Những vật nhỏ như cúc áo, đồng xu, viên bi, pin cúc áo rất nguy hiểm với trẻ em nếu làm điều gì?","o":["Cho vào miệng, mũi hoặc tai","Để trong hộp","Cầm trên tay ngắm","Đếm số lượng"],"a":"Cho vào miệng, mũi hoặc tai","h":"Đặc biệt pin cúc áo nuốt phải có thể gây bỏng nặng bên trong cơ thể.","e":"Tuyệt đối không cho vật nhỏ vào miệng, mũi, tai vì dễ gây hóc, ngạt thở; pin cúc áo còn gây bỏng hóa chất cực kỳ nguy hiểm.","t":"an-toan","l":"thu-thach"},{"p":"Nếu em hoặc bạn bị hóc dị vật, ho sặc và khó thở, việc cần làm ngay là gì?","o":["Gọi thật to người lớn đến sơ cứu (vỗ lưng, ép bụng) và gọi cấp cứu 115 nếu cần","Tự móc tay vào miệng lấy ra","Cho uống thật nhiều nước","Nằm xuống nghỉ một lúc"],"a":"Gọi thật to người lớn đến sơ cứu (vỗ lưng, ép bụng) và gọi cấp cứu 115 nếu cần","h":"Hóc dị vật có thể gây ngạt thở trong vài phút.","e":"Khi có người hóc dị vật khó thở: kêu cứu ngay để người lớn sơ cứu đúng cách và gọi 115; không tự móc họng vì có thể đẩy dị vật sâu hơn.","t":"an-toan","l":"kho"},{"p":"Viên thuốc của người lớn nhiều viên tròn tròn, màu sắc giống hệt viên kẹo. Em có được tự lấy ăn không?","o":["Tuyệt đối không; thuốc chỉ uống khi người lớn cho, đúng liều","Được, ăn một viên không sao","Được nếu viên đó màu đẹp","Được nếu em đã thấy người lớn uống"],"a":"Tuyệt đối không; thuốc chỉ uống khi người lớn cho, đúng liều","h":"Ngộ độc thuốc là tai nạn rất thường gặp ở trẻ em.","e":"Thuốc không phải kẹo: uống nhầm thuốc của người lớn có thể ngộ độc nguy hiểm tính mạng; không tự ý lấy bất kỳ viên thuốc nào.","t":"an-toan","l":"thu-thach"},{"p":"Trong nhà có những chai nước rửa chén, nước lau sàn đựng trong chai giống chai nước ngọt. Điều nào ĐÚNG để an toàn?","o":["Không uống bất cứ chai lạ nào; hóa chất phải để xa tầm tay trẻ em và có nhãn rõ ràng","Nếm thử một ngụm để biết là gì","Ngửi thấy thơm là uống được","Đổ ra cốc rồi mới uống sẽ an toàn"],"a":"Không uống bất cứ chai lạ nào; hóa chất phải để xa tầm tay trẻ em và có nhãn rõ ràng","h":"Nhiều trẻ đã ngộ độc vì uống nhầm hóa chất đựng trong chai nước ngọt.","e":"Không bao giờ uống chất lỏng không rõ là gì; hóa chất gia đình phải có nhãn, đậy kín và để nơi trẻ em không với tới.","t":"an-toan","l":"kho"},{"p":"Một con chó lạ tiến lại gần em. Cách ứng xử an toàn nhất là gì?","o":["Đứng yên, tránh nhìn chằm chằm vào mắt chó và không bỏ chạy","Bỏ chạy thật nhanh","La hét và vung tay đuổi","Lại gần vuốt ve nó"],"a":"Đứng yên, tránh nhìn chằm chằm vào mắt chó và không bỏ chạy","h":"Chạy sẽ kích thích chó đuổi theo và cắn.","e":"Gặp chó lạ: đứng yên, thả tay xuôi, nhìn xuống và chờ chó bỏ đi; không trêu chọc, không chạy và không đến gần chó đang ăn hay đang nuôi con.","t":"an-toan","l":"thu-thach"},{"p":"Bị chó hoặc mèo cắn, cào đến chảy máu, việc phải làm ngay đầu tiên là gì?","o":["Rửa vết thương thật kỹ bằng xà phòng dưới vòi nước chảy trong nhiều phút rồi báo người lớn đưa đi khám ngay","Bôi kem đánh răng lên vết thương","Lấy lá cây đắp lên là khỏi","Băng chặt lại rồi để qua ngày mai"],"a":"Rửa vết thương thật kỹ bằng xà phòng dưới vòi nước chảy trong nhiều phút rồi báo người lớn đưa đi khám ngay","h":"Bệnh dại khi đã phát bệnh là không chữa được, nhưng phòng được ngay sau khi bị cắn.","e":"Bị chó mèo cắn: rửa ngay vết thương bằng xà phòng dưới vòi nước chảy ít nhất 15 phút, sau đó đi khám và tiêm phòng dại theo chỉ định của bác sĩ.","t":"an-toan","l":"kho"},{"p":"Bị ong đốt, em nên xử lý thế nào?","o":["Báo người lớn, lấy ngòi ong ra nếu còn sót, rửa sạch và theo dõi; nếu sưng nhiều hoặc khó thở phải đi viện ngay","Gãi mạnh cho đỡ ngứa","Bóp nặn vết đốt thật mạnh","Mặc kệ, tự khỏi là chính"],"a":"Báo người lớn, lấy ngòi ong ra nếu còn sót, rửa sạch và theo dõi; nếu sưng nhiều hoặc khó thở phải đi viện ngay","h":"Một số người dị ứng nặng với nọc ong có thể nguy hiểm.","e":"Ong đốt: báo người lớn, gạt bỏ ngòi nếu còn, rửa sạch; nếu sưng to, nổi mề đay hay khó thở phải đến cơ sở y tế ngay.","t":"an-toan","l":"thu-thach"},{"p":"Chơi nắng về, em bị chóng mặt, buồn nôn, mặt đỏ bừng — dấu hiệu say nắng. Em nên làm gì?","o":["Vào chỗ mát nằm nghỉ, nới lỏng quần áo, uống nước từng ngụm và báo người lớn","Tiếp tục chơi cho quen nắng","Tắm nước lạnh ngay lập tức","Uống một lúc thật nhiều nước đá"],"a":"Vào chỗ mát nằm nghỉ, nới lỏng quần áo, uống nước từng ngụm và báo người lớn","h":"Say nắng nặng có thể nguy hiểm nếu không xử lý kịp.","e":"Khi say nắng: vào bóng mát, nằm nghỉ đầu hơi cao, lau mát người, uống nước từng ngụm nhỏ và báo người lớn theo dõi.","t":"an-toan","l":"thu-thach"},{"p":"Ăn quá nhiều bánh kẹo ngọt và uống nước ngọt có ga mỗi ngày sẽ gây hại gì?","o":["Sâu răng, béo phì và không tốt cho sức khỏe","Cao lớn nhanh hơn","Răng chắc khỏe hơn","Không hại gì nếu uống thuốc bổ thêm"],"a":"Sâu răng, béo phì và không tốt cho sức khỏe","h":"Đường là \"kẻ thù\" thầm lặng của răng và cân nặng.","e":"Ăn nhiều đồ ngọt gây sâu răng và thừa cân; hãy ăn vừa phải, uống nước lọc là chính và súc miệng sau khi ăn ngọt.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi nhà có trộm đột nhập hoặc có người xấu đe dọa tính mạng, em gọi số khẩn cấp nào?","o":["113 (công an)","114 (cứu hỏa)","115 (cấp cứu)","111 (bảo vệ trẻ em)"],"a":"113 (công an)","h":"Nhớ bộ ba số: 113 công an, 114 cứu hỏa, 115 cấp cứu.","e":"Số 113 là số của công an để báo án, báo nguy hiểm về an ninh; 114 là cứu hỏa, 115 là cấp cứu y tế.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi có người bị thương nặng, ngất xỉu cần bác sĩ gấp, em gọi số nào?","o":["115 (cấp cứu)","113 (công an)","114 (cứu hỏa)","111 (bảo vệ trẻ em)"],"a":"115 (cấp cứu)","h":"115 là số của xe cứu thương đấy.","e":"Số 115 là tổng đài cấp cứu y tế; khi gọi hãy nói rõ địa chỉ và tình trạng của người bị nạn.","t":"an-toan","l":"nhe-nhang"},{"p":"Số điện thoại 111 ở nước ta là tổng đài về việc gì?","o":["Tổng đài quốc gia bảo vệ trẻ em","Tổng đài dự báo thời tiết","Tổng đài sửa điện thoại","Tổng đài tra cứu điểm thi"],"a":"Tổng đài quốc gia bảo vệ trẻ em","h":"Trẻ em bị bạo hành, xâm hại có thể gọi số này để được giúp đỡ miễn phí.","e":"111 là Tổng đài quốc gia bảo vệ trẻ em, hoạt động cả ngày lẫn đêm để tiếp nhận thông tin trẻ em bị bạo hành, xâm hại và giúp đỡ các em.","t":"an-toan","l":"thu-thach"},{"p":"Khi gọi điện thoại báo khẩn cấp, em cần nói những gì là quan trọng nhất?","o":["Nói rõ chuyện gì đang xảy ra, địa chỉ chính xác ở đâu và giữ máy nghe hướng dẫn","Chỉ la hét thật to","Kể dài dòng về bản thân","Gọi rồi cúp máy ngay"],"a":"Nói rõ chuyện gì đang xảy ra, địa chỉ chính xác ở đâu và giữ máy nghe hướng dẫn","h":"Bình tĩnh nói rõ ràng giúp lực lượng cứu hộ đến đúng nơi, đúng việc.","e":"Gọi khẩn cấp: nói chậm rãi, rõ ràng — việc gì, ở đâu, có ai bị thương không — và chỉ cúp máy khi được bảo cúp.","t":"an-toan","l":"thu-thach"},{"p":"Thấy một người bị điện giật đang nắm chặt dây điện, vì sao em TUYỆT ĐỐI không được lao vào kéo họ ra bằng tay không?","o":["Vì điện sẽ truyền qua người em và giật cả hai","Vì họ đang đau nên sẽ giận","Vì kéo ra là phạm luật","Vì phải chờ thợ điện đến mới được đụng"],"a":"Vì điện sẽ truyền qua người em và giật cả hai","h":"Cứu người bị điện giật phải ngắt điện trước tiên.","e":"Phải gọi người lớn ngắt nguồn điện (cầu dao) trước; chạm trực tiếp vào người đang bị điện giật sẽ làm điện truyền sang và giật cả người cứu.","t":"an-toan","l":"kho"},{"p":"Ngửi thấy mùi gas rất nồng trong bếp, điều nào sau đây TUYỆT ĐỐI không được làm?","o":["Bật hoặc tắt công tắc điện, bật lửa để xem cho rõ","Mở cửa sổ cho thoáng khí","Chạy ra khỏi nhà và báo người lớn","Khóa van bình gas nếu làm được an toàn"],"a":"Bật hoặc tắt công tắc điện, bật lửa để xem cho rõ","h":"Tia lửa điện nhỏ xíu cũng đủ làm nổ khí gas.","e":"Khi rò rỉ gas: không động vào công tắc điện hay bật lửa vì tia lửa gây nổ; hãy mở cửa thông gió, khóa van gas nếu an toàn, ra ngoài và gọi người lớn, cứu hỏa 114.","t":"an-toan","l":"kho"},{"p":"Bị bỏng nhẹ do nước sôi đổ vào tay, cách sơ cứu ĐÚNG là gì?","o":["Xả vết bỏng dưới nước mát sạch khoảng 15–20 phút rồi báo người lớn","Bôi kem đánh răng và nước mắm lên vết bỏng","Chườm đá cục trực tiếp lên da","Lấy kim chọc vỡ bọng nước"],"a":"Xả vết bỏng dưới nước mát sạch khoảng 15–20 phút rồi báo người lớn","h":"Các mẹo dân gian bôi kem đánh răng, nước mắm làm vết bỏng dễ nhiễm trùng hơn.","e":"Sơ cứu bỏng: làm mát bằng nước sạch mát chảy nhẹ 15–20 phút, tháo nhẫn vòng nếu có, che nhẹ bằng gạc sạch và báo người lớn; không bôi các chất lạ lên vết bỏng.","t":"an-toan","l":"thu-thach"},{"p":"Đang học trong lớp mà xảy ra động đất rung lắc mạnh, em nên làm gì?","o":["Chui xuống gầm bàn chắc chắn, ôm đầu và nghe theo thầy cô","Chạy ngay ra cầu thang","Đứng cạnh cửa kính ngó ra ngoài","Leo lên bàn đứng"],"a":"Chui xuống gầm bàn chắc chắn, ôm đầu và nghe theo thầy cô","h":"Gầm bàn chắc là nơi trú an toàn nhất trong phòng lúc rung lắc.","e":"Khi động đất: chui dưới gầm bàn, bảo vệ đầu, tránh xa cửa kính và vật dễ đổ; chờ hết rung rồi theo thầy cô ra nơi trống trải.","t":"an-toan","l":"thu-thach"},{"p":"Khi có mưa bão, gió giật rất mạnh, em nên ở đâu cho an toàn?","o":["Ở trong nhà kiên cố, tránh xa cửa kính và không ra ngoài","Ra sân xem bão","Đứng dưới gốc cây to cho khỏi ướt","Trèo lên mái nhà xem gió"],"a":"Ở trong nhà kiên cố, tránh xa cửa kính và không ra ngoài","h":"Bão mạnh cuốn bay cả tôn mái và làm gãy cây đấy.","e":"Khi bão: ở yên trong nhà chắc chắn, tránh xa cửa sổ kính, không ra ngoài và không trú dưới cây to hay biển quảng cáo.","t":"an-toan","l":"nhe-nhang"},{"p":"Em đang trông em bé giúp mẹ, thấy em bé nhặt một viên pin nhỏ cho vào miệng. Em nên làm gì?","o":["Nhẹ nhàng lấy viên pin ra / ngăn em lại và gọi mẹ đến ngay","Mặc kệ vì pin nhỏ không sao","Để em ngậm rồi lấy ra sau","Dọa em khóc thật to"],"a":"Nhẹ nhàng lấy viên pin ra / ngăn em lại và gọi mẹ đến ngay","h":"Pin nhỏ nuốt phải vô cùng nguy hiểm cho em bé.","e":"Phải ngăn em bé cho vật nhỏ vào miệng ngay và báo người lớn; nếu em đã nuốt pin, cần đưa đi cấp cứu lập tức.","t":"an-toan","l":"nhe-nhang"},{"p":"Ở trường, hành động nào sau đây nguy hiểm khi đi cầu thang?","o":["Xô đẩy, chạy nhảy và trượt trên tay vịn cầu thang","Đi chậm, bám tay vịn","Đi bên phải nhường bạn","Đi từng bậc một"],"a":"Xô đẩy, chạy nhảy và trượt trên tay vịn cầu thang","h":"Rất nhiều bạn bị ngã gãy tay chỉ vì đùa nghịch ở cầu thang.","e":"Đi cầu thang phải đi chậm, bám tay vịn, không chạy nhảy, xô đẩy hay leo trèo lên lan can.","t":"an-toan","l":"nhe-nhang"},{"p":"Khi dùng kéo, dao gọt hoa quả hay compa, điều nào là ĐÚNG để an toàn?","o":["Dùng cẩn thận, lưỡi sắc hướng ra xa người, không đùa nghịch chĩa vào bạn","Vung vẩy dọa bạn cho vui","Chạy trong lớp khi đang cầm kéo","Đưa kéo cho bạn bằng cách ném sang"],"a":"Dùng cẩn thận, lưỡi sắc hướng ra xa người, không đùa nghịch chĩa vào bạn","h":"Vật sắc nhọn là công cụ, không phải đồ chơi.","e":"Dùng vật sắc nhọn phải tập trung, hướng phần sắc ra xa cơ thể, đưa cho người khác bằng chuôi và cất đúng chỗ sau khi dùng.","t":"an-toan","l":"thu-thach"},{"p":"Chơi cầu trượt và xích đu ở sân chơi, cách chơi nào là an toàn?","o":["Chờ bạn trượt xuống hẳn mới trượt tiếp, ngồi yên trên xích đu không đứng lên đu","Đẩy bạn xuống cầu trượt thật mạnh","Đứng trên xích đu đu thật cao","Nhiều bạn chen lên cầu trượt cùng lúc"],"a":"Chờ bạn trượt xuống hẳn mới trượt tiếp, ngồi yên trên xích đu không đứng lên đu","h":"Chơi đúng cách thì vui mà không ai bị thương.","e":"Chơi thiết bị sân chơi phải xếp hàng, lần lượt từng bạn, không xô đẩy và không đứng lên xích đu hay trèo ngược cầu trượt.","t":"an-toan","l":"nhe-nhang"},{"p":"Thấy một vật lạ như kim tiêm vứt ở công viên hoặc một chai lọ không nhãn ở vệ đường, em nên làm gì?","o":["Không chạm vào và báo cho người lớn biết","Nhặt lên xem kỹ","Cầm về nhà chơi","Đá nó đi chỗ khác"],"a":"Không chạm vào và báo cho người lớn biết","h":"Kim tiêm và hóa chất lạ có thể mang mầm bệnh và chất độc.","e":"Không bao giờ chạm vào vật lạ sắc nhọn hay chai lọ không rõ nguồn gốc; hãy tránh xa và báo người lớn xử lý.","t":"an-toan","l":"thu-thach"},{"p":"Vì sao không nên trêu chọc tổ ong, chó đang ăn hoặc mèo đang nuôi con?","o":["Vì chúng sẽ tự vệ bằng cách đốt hoặc cắn rất nguy hiểm","Vì chúng sẽ bỏ nhà đi","Vì chúng rất nhát nên tội nghiệp","Vì người lớn sẽ mắng là chính"],"a":"Vì chúng sẽ tự vệ bằng cách đốt hoặc cắn rất nguy hiểm","h":"Con vật hiền đến mấy cũng tấn công khi cảm thấy con của nó bị đe dọa.","e":"Động vật khi đang ăn, đang nuôi con hoặc tổ bị phá sẽ hung dữ để tự vệ; hãy quan sát từ xa và không trêu chọc chúng.","t":"an-toan","l":"thu-thach"},{"p":"Đá bóng ở đâu là an toàn và đúng quy định?","o":["Ở sân bóng, sân trường hoặc bãi đất trống dành cho vui chơi","Giữa lòng đường","Trong hành lang lớp học","Ở bãi đỗ xe"],"a":"Ở sân bóng, sân trường hoặc bãi đất trống dành cho vui chơi","h":"Quả bóng lăn ra đường còn kéo theo tai nạn cho người đi đường nữa.","e":"Chỉ chơi bóng ở nơi quy định an toàn, xa đường giao thông và cửa kính; không chạy theo bóng ra đường.","t":"an-toan","l":"nhe-nhang"},{"p":"Đang chơi thể thao mà bị trẹo chân, bong gân, em nên xử lý thế nào?","o":["Dừng chơi ngay, ngồi nghỉ, chườm lạnh và báo thầy cô hoặc người lớn","Chạy tiếp cho chân quen dần","Xoay vặn khớp mạnh cho về chỗ cũ","Buộc thật chặt rồi chơi tiếp"],"a":"Dừng chơi ngay, ngồi nghỉ, chườm lạnh và báo thầy cô hoặc người lớn","h":"Chơi tiếp khi đã bong gân làm chấn thương nặng thêm nhiều.","e":"Bong gân: nghỉ ngơi ngay, chườm lạnh, kê cao chân và báo người lớn; không cố vận động tiếp hay tự nắn khớp.","t":"an-toan","l":"thu-thach"},{"p":"Đồ đạc để trên nóc tủ cao, em muốn lấy xuống. Cách an toàn nhất là gì?","o":["Nhờ người lớn lấy giúp","Trèo lên ghế chồng ghế","Đứng lên bàn nhảy với","Kéo mạnh cho nó tự rơi xuống"],"a":"Nhờ người lớn lấy giúp","h":"Ngã từ trên cao là tai nạn rất thường gặp ở trẻ em.","e":"Không leo trèo lên tủ, bàn ghế cao để lấy đồ; hãy nhờ người lớn giúp hoặc dùng dụng cụ phù hợp có người giữ.","t":"an-toan","l":"nhe-nhang"},{"p":"Các tòa nhà, siêu thị hay dùng cửa kính trong suốt rất lớn. Khi đi qua em cần chú ý gì?","o":["Đi chậm và nhìn kỹ để không đâm sầm vào cửa kính","Chạy thật nhanh qua cho gọn","Nhắm mắt đi theo bạn","Dựa người vào kính mà đi"],"a":"Đi chậm và nhìn kỹ để không đâm sầm vào cửa kính","h":"Kính trong suốt sạch quá khiến nhiều người không nhận ra và va vào rất đau.","e":"Đi qua cửa kính lớn phải quan sát kỹ tay nắm, khung cửa và đi chậm để tránh va đập.","t":"an-toan","l":"nhe-nhang"},{"p":"Vì sao không nên vừa chạy nhảy, vừa ngậm các xiên que đồ ăn trong miệng?","o":["Vì nếu vấp ngã, que nhọn sẽ đâm vào miệng, cổ họng gây thương tích nặng","Vì đồ ăn sẽ rơi mất ngon","Vì chạy làm đồ ăn lạnh đi","Vì người lớn không thích thế"],"a":"Vì nếu vấp ngã, que nhọn sẽ đâm vào miệng, cổ họng gây thương tích nặng","h":"Đây là tai nạn có thật và rất nguy hiểm với trẻ em.","e":"Khi ăn đồ xiên que, hãy ngồi yên một chỗ ăn cho xong; tuyệt đối không vừa đi chạy vừa ngậm que nhọn trong miệng.","t":"an-toan","l":"thu-thach"},{"p":"Khi đi xe buýt đang chạy, em đứng gần cửa và không bám vào đâu cả. Điều này nguy hiểm vì sao?","o":["Vì xe phanh gấp hoặc rẽ là em ngã nhào ngay","Vì cửa xe sẽ tự mở","Vì tài xế không nhìn thấy em","Không nguy hiểm gì"],"a":"Vì xe phanh gấp hoặc rẽ là em ngã nhào ngay","h":"Hãy luôn tìm tay vịn và bám chắc khi xe đang chạy.","e":"Trên xe đang chạy phải ngồi yên hoặc bám chắc tay vịn; xe phanh gấp có thể làm em ngã và bị thương.","t":"an-toan","l":"nhe-nhang"},{"p":"Đi ô tô về quê đường dài, em nên xuống xe ở phía nào khi xe đã dừng?","o":["Phía lề đường, vỉa hè — phía không có xe cộ chạy qua","Phía giữa lòng đường cho nhanh","Phía nào cũng như nhau","Nhảy xuống ngay khi xe chưa dừng hẳn"],"a":"Phía lề đường, vỉa hè — phía không có xe cộ chạy qua","h":"Rất nhiều tai nạn xảy ra ngay khi mở cửa xe bước xuống phía đường.","e":"Chỉ xuống xe khi xe dừng hẳn và xuống phía lề đường, quan sát kỹ xung quanh trước khi bước xuống.","t":"an-toan","l":"thu-thach"},{"p":"Khi nấu ăn xong, van bình gas trong bếp cần được làm gì, và trẻ em nên nhắc người lớn điều này?","o":["Khóa van bình gas lại để phòng rò rỉ gas","Để van mở cho lần sau tiện nấu","Vặn van thật lỏng","Không cần quan tâm đến gas"],"a":"Khóa van bình gas lại để phòng rò rỉ gas","h":"Rò rỉ gas là nguyên nhân của nhiều vụ cháy nổ trong nhà.","e":"Sau khi nấu, khóa van bình gas và kiểm tra bếp đã tắt hẳn giúp phòng cháy nổ; trẻ em không tự ý nghịch bếp gas.","t":"an-toan","l":"nhe-nhang"},{"p":"Ngày Tết, bạn rủ em cùng đốt pháo nổ mua lén. Em nên làm gì?","o":["Từ chối vì pháo nổ bị cấm và có thể gây bỏng, thương tích nặng, cháy nhà","Đốt một quả nhỏ cho vui","Đốt nhưng đứng xa một chút","Đốt trong nhà cho kín"],"a":"Từ chối vì pháo nổ bị cấm và có thể gây bỏng, thương tích nặng, cháy nhà","h":"Mỗi dịp Tết, bệnh viện tiếp nhận rất nhiều ca tai nạn vì pháo.","e":"Pháo nổ là hàng cấm nguy hiểm: gây bỏng nặng, mù mắt, cụt ngón tay và cháy nhà; tuyệt đối không mua, không đốt và không đứng gần người đốt pháo.","t":"an-toan","l":"nhe-nhang"},{"p":"Trời sắp có dông, em đang tắm ở biển hoặc bơi ở bể bơi ngoài trời. Em nên làm gì ngay?","o":["Lên khỏi mặt nước ngay và vào nơi trú an toàn","Bơi nốt vài vòng nữa","Lặn xuống nước tránh sét","Đứng trên bờ cao xem sét"],"a":"Lên khỏi mặt nước ngay và vào nơi trú an toàn","h":"Nước dẫn điện và mặt nước là nơi sét rất dễ đánh.","e":"Khi có dông sét, phải rời mặt nước ngay (biển, hồ, bể bơi) và vào nhà trú ẩn; không ở lại dưới nước hay trên bãi trống.","t":"an-toan","l":"thu-thach"},{"p":"Khi tắm biển, khu vực nào là nơi được phép tắm an toàn?","o":["Khu vực có dây phao giới hạn và có nhân viên cứu hộ trực","Chỗ nào nước trong là tắm được","Chỗ vắng người cho thoải mái","Ngoài xa khơi nước sạch hơn"],"a":"Khu vực có dây phao giới hạn và có nhân viên cứu hộ trực","h":"Dây phao giới hạn vùng nước đã được kiểm tra an toàn.","e":"Chỉ tắm trong khu vực có dây phao và cứu hộ; ngoài vùng đó có thể có vực sâu, dòng chảy xiết rất nguy hiểm.","t":"an-toan","l":"nhe-nhang"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm đi ngược chiều","Cấm đỗ xe","Đường một chiều","Cấm rẽ trái"],"a":"Cấm đi ngược chiều","h":"Biển tròn đỏ có một gạch trắng nằm ngang.","e":"Biển tròn nền đỏ với gạch trắng nằm ngang là biển \"Cấm đi ngược chiều\" — xe không được đi vào đường có biển này.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-di-nguoc-chieu.png"},{"p":"Thấy biển \"Cấm đi ngược chiều\", người lái xe phải làm gì?","o":["Không được đi vào đường này","Đi chậm lại rồi đi tiếp","Bấm còi rồi đi vào","Đi vào thoải mái"],"a":"Không được đi vào đường này","h":"Biển cấm nghĩa là tuyệt đối không được làm điều bị cấm.","e":"Gặp biển cấm đi ngược chiều, xe phải chọn đường khác, không được đi vào dù đường vắng.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-di-nguoc-chieu.png"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm dừng xe và đỗ xe","Cấm rẽ phải","Đường dành cho xe đạp","Được đỗ xe thoải mái"],"a":"Cấm dừng xe và đỗ xe","h":"Biển có hai gạch đỏ chéo nhau thành dấu nhân.","e":"Biển tròn nền xanh, viền đỏ, có hai gạch chéo đỏ là biển \"Cấm dừng xe và đỗ xe\" — xe không được dừng lại ở đoạn đường này.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-dung-xe-do-xe.png"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm đỗ xe","Cấm đi ngược chiều","Cấm người đi bộ","Dừng xe kiểm tra"],"a":"Cấm đỗ xe","h":"Biển này chỉ có một gạch chéo đỏ.","e":"Biển tròn nền xanh, viền đỏ, một gạch chéo đỏ là biển \"Cấm đỗ xe\". Khác với biển cấm dừng và đỗ (có hai gạch chéo).","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-do-xe.png"},{"p":"Biển báo trong hình cấm điều gì?","o":["Cấm rẽ trái","Cấm rẽ phải","Cấm quay đầu xe","Cấm đi thẳng"],"a":"Cấm rẽ trái","h":"Mũi tên trên biển đang ngoặt về bên trái.","e":"Biển tròn viền đỏ, mũi tên rẽ trái bị gạch chéo đỏ là biển \"Cấm rẽ trái\".","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-re-trai.png"},{"p":"Biển báo trong hình cấm điều gì?","o":["Cấm rẽ phải","Cấm rẽ trái","Cấm đi thẳng","Cấm đỗ xe"],"a":"Cấm rẽ phải","h":"Mũi tên trên biển đang ngoặt về bên phải.","e":"Biển tròn viền đỏ, mũi tên rẽ phải bị gạch chéo đỏ là biển \"Cấm rẽ phải\".","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-re-phai.png"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm xe đạp đi vào","Đường dành cho xe đạp","Nơi để xe đạp","Cấm xe máy"],"a":"Cấm xe đạp đi vào","h":"Trong biển là hình một chiếc xe đạp.","e":"Biển tròn viền đỏ có hình xe đạp là biển \"Cấm xe đạp\" — người đi xe đạp không được vào đường này.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-xe-dap.png"},{"p":"Em đang đạp xe, thấy biển \"Cấm xe đạp\" thì em phải làm gì?","o":["Không đi vào, chọn đường khác","Đạp thật nhanh qua","Xuống xe dắt bộ qua cũng bị cấm","Đi vào nếu đường vắng"],"a":"Không đi vào, chọn đường khác","h":"Biển cấm thì mình không được vào khu vực đó bằng xe đạp.","e":"Gặp biển cấm xe đạp, em không được đạp xe vào. Em nên chọn đường khác; nếu cần qua, hãy hỏi người lớn và dắt xe theo quy định tại nơi đó.","t":"giao-thong","l":"thu-thach","img":"traffic-img/cam-xe-dap.png"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm người đi bộ","Đường dành cho người đi bộ","Cấm chạy nhảy","Nơi qua đường"],"a":"Cấm người đi bộ","h":"Hình người đi bộ bị gạch chéo đỏ.","e":"Biển tròn viền đỏ, hình người đi bộ bị gạch chéo là biển \"Cấm người đi bộ\" — thường cắm ở đường cao tốc hoặc nơi nguy hiểm.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-nguoi-di-bo.png"},{"p":"Biển báo trong hình có ý nghĩa gì?","o":["Cấm ô tô đi vào","Nơi đỗ ô tô","Trạm rửa xe","Đường dành riêng cho ô tô"],"a":"Cấm ô tô đi vào","h":"Trong biển là hình đầu một chiếc ô tô.","e":"Biển tròn viền đỏ có hình ô tô là biển \"Cấm ô tô\" — ô tô không được đi vào đường này.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/cam-o-to.png"},{"p":"Biển báo trong hình cho biết điều gì?","o":["Tốc độ tối đa cho phép là 50 km/giờ","Đường dài 50 km","Còn 50 m là đến nơi","Tối thiểu phải chạy 50 km/giờ"],"a":"Tốc độ tối đa cho phép là 50 km/giờ","h":"Con số trên biển là giới hạn tốc độ.","e":"Biển tròn viền đỏ ghi số 50 là biển hạn chế tốc độ tối đa 50 km/giờ — xe không được chạy nhanh hơn.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/han-che-toc-do-50.png"},{"p":"Biển tam giác trong hình cảnh báo điều gì?","o":["Phía trước có trẻ em qua đường","Phía trước có công trường","Phía trước có đường sắt","Phía trước đường trơn"],"a":"Phía trước có trẻ em qua đường","h":"Trong biển là hình hai bạn nhỏ đang đi.","e":"Biển tam giác vàng viền đỏ có hình trẻ em là biển cảnh báo nơi trẻ em hay qua đường (gần trường học). Lái xe phải giảm tốc độ, chú ý quan sát.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-tre-em.png"},{"p":"Thấy biển \"Trẻ em qua đường\", chú lái xe phải làm gì?","o":["Giảm tốc độ và chú ý quan sát","Chạy nhanh hơn cho qua","Bấm còi liên tục","Không cần quan tâm"],"a":"Giảm tốc độ và chú ý quan sát","h":"Biển cảnh báo nhắc lái xe cẩn thận hơn.","e":"Biển cảnh báo trẻ em qua đường nhắc lái xe đi chậm lại, sẵn sàng dừng xe để nhường các bạn nhỏ qua đường an toàn.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-tre-em.png"},{"p":"Biển tam giác trong hình cảnh báo điều gì?","o":["Sắp đến chỗ giao nhau với đường sắt","Sắp đến trạm xăng","Phía trước có tàu hỏa đang bán vé","Đường dành cho tàu hỏa"],"a":"Sắp đến chỗ giao nhau với đường sắt","h":"Trong biển là hình đầu tàu hỏa.","e":"Biển có hình tàu hỏa cảnh báo phía trước là đường ngang giao với đường sắt. Phải quan sát kỹ, nghe tiếng còi tàu trước khi qua.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-duong-sat.png"},{"p":"Biển tam giác trong hình cảnh báo điều gì?","o":["Phía trước có công trường đang thi công","Phía trước là sân chơi","Phía trước có người bán hàng","Đường đã làm xong"],"a":"Phía trước có công trường đang thi công","h":"Trong biển là hình người công nhân đang đào đất.","e":"Biển hình người đang đào đất cảnh báo đoạn đường đang thi công, sửa chữa. Người tham gia giao thông phải đi chậm và cẩn thận.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-cong-truong.png"},{"p":"Biển tam giác trong hình cảnh báo điều gì?","o":["Đường trơn trượt","Đường đang ướt sơn","Phía trước có sông","Cấm rửa xe"],"a":"Đường trơn trượt","h":"Chiếc xe trong biển để lại vệt trượt ngoằn ngoèo.","e":"Biển hình ô tô với vệt trượt cảnh báo mặt đường trơn (mưa, dầu mỡ...). Lái xe phải đi chậm, giữ khoảng cách an toàn.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-duong-tron.png"},{"p":"Biển tam giác trong hình cảnh báo điều gì?","o":["Sắp đến đường giao nhau","Đường cụt","Cấm dừng xe","Nơi đỗ xe"],"a":"Sắp đến đường giao nhau","h":"Trong biển là dấu cộng — tượng trưng các đường cắt nhau.","e":"Biển có dấu cộng cảnh báo phía trước là nơi các đường giao nhau. Phải giảm tốc độ và nhường đường theo quy tắc.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/nguy-hiem-giao-nhau.png"},{"p":"Biển tròn xanh trong hình ra lệnh điều gì?","o":["Phải đi thẳng","Phải dừng lại","Được rẽ trái","Cấm đi thẳng"],"a":"Phải đi thẳng","h":"Mũi tên trắng chỉ thẳng lên trên.","e":"Biển tròn nền xanh là biển hiệu lệnh. Mũi tên chỉ thẳng nghĩa là xe bắt buộc phải đi thẳng.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/hieu-lenh-di-thang.png"},{"p":"Biển tròn xanh trong hình ra lệnh điều gì?","o":["Phải rẽ phải","Cấm rẽ phải","Được đi thẳng","Phải dừng lại"],"a":"Phải rẽ phải","h":"Mũi tên trắng ngoặt sang phải.","e":"Biển hiệu lệnh nền xanh, mũi tên rẽ phải: xe bắt buộc phải rẽ phải, không được đi thẳng hay rẽ trái.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/hieu-lenh-re-phai.png"},{"p":"Biển tròn xanh trong hình ra lệnh điều gì?","o":["Phải đi theo vòng xuyến","Phải quay đầu xe","Cấm đi vòng","Đường đang sửa vòng tròn"],"a":"Phải đi theo vòng xuyến","h":"Các mũi tên trắng xếp thành vòng tròn đuổi nhau.","e":"Biển có ba mũi tên cong xếp vòng tròn là biển \"Nơi giao nhau chạy theo vòng xuyến\" — xe phải chạy vòng quanh đảo theo chiều mũi tên.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/hieu-lenh-vong-xuyen.png"},{"p":"Biển tròn xanh trong hình có ý nghĩa gì?","o":["Đường dành cho người đi bộ","Cấm người đi bộ","Nơi tập thể dục","Đường dành cho xe đạp"],"a":"Đường dành cho người đi bộ","h":"Hình người đi bộ màu trắng trên nền xanh.","e":"Biển hiệu lệnh hình người đi bộ cho biết đây là đường/phần đường dành riêng cho người đi bộ.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/hieu-lenh-di-bo.png"},{"p":"Biển chữ nhật xanh trong hình có ý nghĩa gì?","o":["Đường một chiều","Đường hai chiều","Cấm đi thẳng","Đường dành cho ô tô"],"a":"Đường một chiều","h":"Mũi tên dài chỉ một hướng duy nhất.","e":"Biển chữ nhật nền xanh, mũi tên trắng dài là biển \"Đường một chiều\" — mọi xe chỉ được đi theo chiều mũi tên.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/duong-mot-chieu.png"},{"p":"Biển vuông xanh trong hình cho biết điều gì?","o":["Vị trí dành cho người đi bộ qua đường","Nơi đỗ xe","Vạch sơn trang trí","Đường đang sửa"],"a":"Vị trí dành cho người đi bộ qua đường","h":"Trong biển có các vạch sọc như vạch qua đường trên mặt đất.","e":"Biển hình người đi trên vạch sọc báo hiệu nơi có vạch dành cho người đi bộ qua đường. Em nhớ qua đường đúng ở vạch này nhé.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/vi-tri-qua-duong.png"},{"p":"Biển có chữ H trong hình cho biết điều gì?","o":["Gần đây có bệnh viện","Nơi đỗ trực thăng","Khách sạn ở gần","Trạm dừng xe buýt"],"a":"Gần đây có bệnh viện","h":"Chữ H là viết tắt của \"Hospital\" — bệnh viện.","e":"Biển chỉ dẫn chữ H cho biết phía trước có bệnh viện. Qua khu vực này, lái xe cần đi êm, hạn chế bấm còi để bệnh nhân được yên tĩnh.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/benh-vien.png"},{"p":"Đèn tín hiệu trong hình đang sáng màu đỏ. Người tham gia giao thông phải làm gì?","o":["Dừng lại trước vạch dừng","Đi nhanh qua","Đi chậm rồi qua luôn","Bấm còi rồi đi"],"a":"Dừng lại trước vạch dừng","h":"Đèn đỏ nghĩa là dừng lại.","e":"Đèn đỏ sáng: mọi xe và người đi bộ phải dừng lại trước vạch dừng, chờ đến đèn xanh mới được đi.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/den-do.png"},{"p":"Đèn tín hiệu chuyển sang màu vàng như hình. Xe chưa qua vạch dừng phải làm gì?","o":["Đi chậm lại và dừng trước vạch dừng","Tăng tốc để qua kịp","Đi tiếp như đèn xanh","Rẽ phải ngay lập tức"],"a":"Đi chậm lại và dừng trước vạch dừng","h":"Đèn vàng là tín hiệu chuẩn bị chuyển sang đèn đỏ.","e":"Đèn vàng báo hiệu sắp đèn đỏ. Xe nào chưa qua vạch dừng phải dừng lại; xe đã qua vạch thì đi tiếp cho an toàn.","t":"giao-thong","l":"thu-thach","img":"traffic-img/den-vang.png"},{"p":"Đèn tín hiệu trong hình đang sáng màu xanh. Điều đó có nghĩa là gì?","o":["Được phép đi tiếp","Phải dừng lại","Chuẩn bị dừng","Chỉ xe máy được đi"],"a":"Được phép đi tiếp","h":"Đèn xanh nghĩa là được đi.","e":"Đèn xanh sáng: các xe được phép đi tiếp, nhưng vẫn phải chú ý nhường người đi bộ đang qua đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/den-xanh.png"},{"p":"Đèn dành cho người đi bộ trong hình đang hiện hình người màu đỏ đứng yên. Em phải làm gì?","o":["Đứng chờ trên vỉa hè, chưa qua đường","Chạy nhanh qua đường","Đi từ từ qua đường","Nhờ bạn kéo qua"],"a":"Đứng chờ trên vỉa hè, chưa qua đường","h":"Hình người đỏ đứng yên nghĩa là chưa được đi.","e":"Đèn đi bộ đỏ: người đi bộ phải đứng chờ trên vỉa hè. Chỉ qua đường khi đèn chuyển sang hình người màu xanh.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/den-di-bo-do.png"},{"p":"Đèn dành cho người đi bộ trong hình hiện hình người màu xanh. Em được làm gì?","o":["Được qua đường trên vạch qua đường","Được chạy đùa giữa đường","Được đứng giữa đường chơi","Được qua đường ở bất cứ đâu"],"a":"Được qua đường trên vạch qua đường","h":"Hình người xanh đang bước đi nghĩa là được qua đường.","e":"Đèn đi bộ xanh: em được qua đường, nhưng nhớ đi trên vạch qua đường và vẫn quan sát xe hai bên.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/den-di-bo-xanh.png"},{"p":"Các vạch trắng kẻ ngang đường trong hình gọi là gì?","o":["Vạch dành cho người đi bộ qua đường","Vạch phân làn xe","Vạch dừng xe","Vạch trang trí đường"],"a":"Vạch dành cho người đi bộ qua đường","h":"Các vạch trắng xếp song song như vằn ngựa vằn.","e":"Những vạch trắng song song kẻ ngang đường (hay gọi là vạch \"ngựa vằn\") là lối dành cho người đi bộ qua đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/vach-qua-duong.png"},{"p":"Khi qua đường trên vạch dành cho người đi bộ, em nên làm gì?","o":["Quan sát hai bên rồi đi thẳng qua, không chạy đùa","Chạy thật nhanh không cần nhìn","Vừa đi vừa chơi điện thoại","Đứng lại giữa đường ngắm xe"],"a":"Quan sát hai bên rồi đi thẳng qua, không chạy đùa","h":"Qua đường an toàn là phải quan sát và đi thẳng, dứt khoát.","e":"Dù có vạch qua đường, em vẫn phải quan sát trái — phải — trái, đi thẳng qua đường, không chạy nhảy hay đùa nghịch giữa đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/vach-qua-duong.png"},{"p":"Trong hình, hai vạch vàng liền kẻ giữa đường có ý nghĩa gì?","o":["Phân cách hai chiều xe chạy ngược nhau, xe không được lấn qua","Vạch dành cho người đi bộ","Nơi được đỗ xe","Vạch báo đường sắp hẹp"],"a":"Phân cách hai chiều xe chạy ngược nhau, xe không được lấn qua","h":"Vạch vàng nằm ở tim đường, giữa hai chiều xe.","e":"Vạch vàng liền đôi ở giữa đường phân cách hai chiều xe chạy ngược nhau. Xe tuyệt đối không được đè lên hay vượt qua vạch này.","t":"giao-thong","l":"thu-thach","img":"traffic-img/vach-tim-duong.png"},{"p":"Trong hình, các vạch trắng đứt đoạn kẻ dọc đường có ý nghĩa gì?","o":["Phân chia các làn xe cùng chiều, xe được chuyển làn khi an toàn","Cấm xe đi qua","Vạch dành cho người đi bộ","Báo hiệu đường kết thúc"],"a":"Phân chia các làn xe cùng chiều, xe được chuyển làn khi an toàn","h":"Vạch đứt đoạn khác vạch liền: được phép cắt qua khi an toàn.","e":"Vạch trắng đứt đoạn phân chia các làn xe chạy cùng chiều. Xe được chuyển làn qua vạch này khi đã quan sát an toàn; còn vạch liền thì không được đè lên.","t":"giao-thong","l":"thu-thach","img":"traffic-img/vach-tim-duong.png"},{"p":"Vạch trắng ngang to kẻ trước vạch qua đường trong hình là gì?","o":["Vạch dừng xe — xe phải dừng sau vạch này khi đèn đỏ","Vạch bắt đầu đường","Vạch dành cho xe đạp dừng","Vạch sơn thử"],"a":"Vạch dừng xe — xe phải dừng sau vạch này khi đèn đỏ","h":"Vạch này nằm ngay trước lối qua đường của người đi bộ.","e":"Vạch dừng xe quy định vị trí xe phải dừng lại khi đèn đỏ hoặc có hiệu lệnh dừng, để nhường lối cho người đi bộ qua đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/vach-dung-xe.png"},{"p":"Chiếc xe có dấu chữ thập đỏ trong hình là xe gì?","o":["Xe cứu thương","Xe cứu hỏa","Xe cảnh sát","Xe buýt"],"a":"Xe cứu thương","h":"Dấu chữ thập đỏ là biểu tượng của ngành y tế.","e":"Xe có chữ thập đỏ là xe cứu thương, dùng để chở người bệnh, người bị thương đi cấp cứu.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/xe-cuu-thuong.png"},{"p":"Chiếc xe màu đỏ có thang dài trong hình là xe gì?","o":["Xe cứu hỏa (xe chữa cháy)","Xe cứu thương","Xe chở rác","Xe tưới cây"],"a":"Xe cứu hỏa (xe chữa cháy)","h":"Chiếc thang dài trên nóc là để leo lên cao chữa cháy nhà cao tầng.","e":"Xe màu đỏ có thang là xe cứu hỏa. Các chú lính cứu hỏa dùng xe này để đến dập lửa và cứu người.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/xe-cuu-hoa.png"},{"p":"Chiếc xe có đèn nhấp nháy xanh đỏ trên nóc trong hình là xe gì?","o":["Xe cảnh sát giao thông","Xe taxi","Xe cứu thương","Xe đưa thư"],"a":"Xe cảnh sát giao thông","h":"Đèn hiệu xanh đỏ nhấp nháy là dấu hiệu của xe công an.","e":"Xe có còi và đèn hiệu xanh đỏ là xe cảnh sát. Các chú cảnh sát giao thông giúp giữ trật tự và an toàn trên đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/xe-canh-sat.png"},{"p":"Đang đi trên đường, nghe tiếng còi xe cứu thương từ phía sau, mọi người phải làm gì?","o":["Nhường đường cho xe cứu thương đi qua","Đi nhanh hơn để tránh","Đứng lại xem xe đi đâu","Bịt tai lại đi tiếp"],"a":"Nhường đường cho xe cứu thương đi qua","h":"Xe cứu thương đang đi cứu người, mỗi phút đều quý.","e":"Xe cứu thương, xe cứu hỏa, xe cảnh sát khi hú còi là xe ưu tiên đang làm nhiệm vụ khẩn cấp. Mọi người phải nhường đường ngay.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/xe-cuu-thuong.png"},{"p":"Trong các xe sau, xe nào là xe ưu tiên được nhường đường trước?","o":["Xe cứu hỏa đang trên đường đi chữa cháy","Xe đạp của học sinh","Xe buýt chở khách","Xe máy đi chợ"],"a":"Xe cứu hỏa đang trên đường đi chữa cháy","h":"Xe ưu tiên là xe đang làm nhiệm vụ khẩn cấp như cứu hỏa, cứu thương.","e":"Xe cứu hỏa, xe cứu thương và xe cảnh sát khi đang làm nhiệm vụ khẩn cấp (có còi, đèn hiệu) là xe ưu tiên — tất cả các xe khác phải nhường đường.","t":"giao-thong","l":"thu-thach"},{"p":"Em đang đi bộ trên vỉa hè, thấy xe cứu hỏa hú còi chạy tới. Em nên làm gì?","o":["Đứng yên trên vỉa hè, không chạy xuống đường","Chạy xuống đường xem cho rõ","Vẫy tay gọi xe dừng lại","Chạy theo xe"],"a":"Đứng yên trên vỉa hè, không chạy xuống đường","h":"Người đi bộ nhường đường bằng cách đứng gọn trên vỉa hè.","e":"Người đi bộ chỉ cần đứng yên, gọn trên vỉa hè là đã nhường đường cho xe ưu tiên rồi. Tuyệt đối không chạy xuống lòng đường.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/xe-cuu-hoa.png"},{"p":"Đèn đỏ sáng, người đi bộ có được chạy nhanh qua đường không?","o":["Không, phải chờ đèn xanh mới qua","Được, miễn chạy thật nhanh","Được, nếu không thấy xe","Được, nếu đi cùng bạn"],"a":"Không, phải chờ đèn xanh mới qua","h":"Đèn đỏ là lệnh dừng cho cả xe và người.","e":"Đèn đỏ thì người đi bộ cũng phải dừng chờ, dù đường có vẻ vắng. Chạy qua khi đèn đỏ rất nguy hiểm.","t":"giao-thong","l":"nhe-nhang","img":"traffic-img/den-do.png"},{"p":"Xe chạy 60 km/giờ qua đoạn đường có biển hạn chế tốc độ 50 như hình. Vậy xe đó đi có đúng không?","o":["Không đúng, chỉ được chạy tối đa 50 km/giờ","Đúng, chạy càng nhanh càng tốt","Đúng, vì đường đang vắng","Không đúng, phải chạy đúng 50 mới được"],"a":"Không đúng, chỉ được chạy tối đa 50 km/giờ","h":"Biển ghi 50 nghĩa là không được vượt quá 50.","e":"Biển hạn chế tốc độ 50 quy định xe chạy tối đa 50 km/giờ. Chạy 60 km/giờ là vi phạm và không an toàn.","t":"giao-thong","l":"thu-thach","img":"traffic-img/han-che-toc-do-50.png"},{"p":"Nơi không có vạch qua đường, khi muốn qua đường em phải làm gì trước?","o":["Quan sát bên trái, bên phải rồi lại bên trái, chắc chắn an toàn mới qua","Cứ đi thẳng không cần nhìn","Chạy thật nhanh qua","Nhắm mắt đi qua"],"a":"Quan sát bên trái, bên phải rồi lại bên trái, chắc chắn an toàn mới qua","h":"Quy tắc quan sát qua đường là trái — phải — trái.","e":"Khi qua đường, em phải dừng lại, quan sát trái — phải — trái. Khi thấy an toàn, giơ tay ra hiệu và đi thẳng qua, không chạy.","t":"giao-thong","l":"nhe-nhang"},{"p":"Biển báo hình tam giác, nền vàng, viền đỏ thường là biển gì?","o":["Biển báo nguy hiểm (cảnh báo)","Biển cấm","Biển hiệu lệnh","Biển chỉ dẫn"],"a":"Biển báo nguy hiểm (cảnh báo)","h":"Nhớ hình dáng: tam giác vàng viền đỏ là cảnh báo phía trước có điều nguy hiểm.","e":"Biển hình tam giác nền vàng viền đỏ là nhóm biển báo nguy hiểm, cảnh báo trước những tình huống cần cẩn thận như trẻ em qua đường, đường sắt, công trường...","t":"giao-thong","l":"thu-thach","img":"traffic-img/nguy-hiem-tre-em.png"},{"p":"Biển báo hình tròn, nền xanh, hình vẽ trắng thường là biển gì?","o":["Biển hiệu lệnh (bắt buộc phải theo)","Biển cấm","Biển báo nguy hiểm","Biển quảng cáo"],"a":"Biển hiệu lệnh (bắt buộc phải theo)","h":"Tròn xanh là lệnh bắt buộc, khác với tròn viền đỏ là cấm.","e":"Biển tròn nền xanh là biển hiệu lệnh — báo điều bắt buộc phải làm như phải đi thẳng, phải rẽ phải, đường dành cho người đi bộ.","t":"giao-thong","l":"thu-thach","img":"traffic-img/hieu-lenh-di-thang.png"},{"p":"Biển báo hình tròn, viền đỏ, nền trắng thường là biển gì?","o":["Biển cấm","Biển hiệu lệnh","Biển chỉ dẫn","Biển báo nguy hiểm"],"a":"Biển cấm","h":"Viền đỏ tròn là dấu hiệu của điều bị cấm.","e":"Biển tròn viền đỏ là nhóm biển cấm — báo điều không được làm như cấm rẽ trái, cấm xe đạp, cấm người đi bộ...","t":"giao-thong","l":"thu-thach","img":"traffic-img/cam-re-trai.png"}];